        // Structur.PAS:295
        public virtual void ExecuteCancelProduction()
        {
            sbyte Player;
            if (FStatus == Status.Producing)
            {
                FQueue.GetItem(0).Order.Cancel(this);
                if (FSettings.FGroupID != 0)
                {
                    UnregisterGroupProduction();
                }

                Player = GetPlayer();
                if (Player > -1)
                {
                    var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnGold = CancelProductionReturnGold();
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).SetGems(players.FGems + cancelProductionReturnGold);
                    var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                    var cancelProductionReturnMana = CancelProductionReturnMana();
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + cancelProductionReturnMana);
                }

                FSettings.Clear();
                FStatus = Status.Waiting;
                Update();
            }
        }

