            EndUpdate();
        }

        // Structur.PAS:514
        public virtual ExecuteResult ExecuteProductionTE(ProductionTE Event)
        {
            ExecuteResult Result;
            switch (Event.FCommand)
            {
                case 0:
                    BeginUpdate();
                    if (!Event.FQueue)
                    {
                        ExecuteDeleteProductions();
                    }

                    ExecuteAddProduction(Event.FItem);
                    Result = ExecuteResult.Done;
                    EndUpdate();
                    break;
                case 1:
                    ExecuteDeleteProduction(Event.FIndex);
                    Result = ExecuteResult.Done;
                    break;
                case 2:
                    ExecuteDeleteProductions();
                    Result = ExecuteResult.Done;
                    break;
                case 3:
                    if (FQueue.Count != 0 && FStatus == Status.Waiting)
                    {
                        ExecuteProduction(FQueue.GetItem(0));
                    }

                    Result = ExecuteResult.Done;
                    break;
                case 4:
                    FLoopQueue = Event.FIndex == 1;
                    Update();
                    Result = ExecuteResult.Done;
                    break;
                default:
                    Result = ExecuteResult.Done;
                    break;
            }

            return Result;
        }

