        // Spells.PAS:1734
        public virtual void SetUpkeep(int Value)
        {
            if (Value != FUpkeep)
            {
                FUpkeep = Value;
                if (FSource > -1)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.Update();
                }
            }
        }

        // Spells.PAS:1742
        public virtual void SetSource(sbyte Player)
        {
            if (Player != FSource)
            {
                if (FSource > -1)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.UnregisterEnchantment(this);
                }

                FSource = Player;
                if (FSource > -1)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.RegisterEnchantment(this);
                }
