        // Spells.PAS:1706
        public virtual bool CenterToLocation()
        {
            bool Result;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            GetLocation(ref X, ref Y, ref L);
            if (X != -1)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.Visible(X, Y, L, 0))
                {
                    Aow.Game.World.Map.AoWHSMap.Current.CenterViewTo(X, Y, L);
                    Aow.Game.World.Map.AoWHSMap.Current.PlayCenterAnimation(X, Y, L);
                }
                else
                {
                    var binding = GetBinding();
                    var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.XIsOutOfSightRStr), [binding]);
                    Aow.Game.World.Map.AoWHSMap.Current.ShowMessage(format);
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:1751
        public virtual bool Dispel() => false;

        // Spells.PAS:1724
        public virtual void Select()
        {
            CenterToLocation();
        }

        // Spells.PAS:1753
        public int DispelChance(int Mana)
        {
            int Result = Mana - FDispelResistance * 10 + 50;
            if (Result < 10)
            {
                Result = 10;
            }

            if (Result > 90)
            {
                Result = 90;
            }

            return Result;
        }

