{

    // (mode, location, spell ID, value, enchantment name)
    public partial class PlayerMagicEventLog : EventLog
    {
        // Spells.PAS:1847
        // mode, location, spell ID, value, enchantment name
        public PlayerMagicEventLog(ECustomNode owner) : base(owner)
        {
            FLocation.Packed = 16777215;
        }

        public new const int ClassID = 131824;

        public PlayerMagicEventMode FMode;
        public XYL FLocation;
        public int FSpellID;
        public int FValue;
        public string FEnchantmentName = "";

        // Spells.PAS:1854
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwData(Bytes.Of(ref FMode, 1), 1, 20);
            Stream.rwInteger(ref FSpellID, 21);
            Stream.rwInteger(ref FValue, 22);
            Stream.rwString(ref FEnchantmentName, 23);
            Stream.rwInteger(ref FLocation.Packed, 24);
        }

        // Spells.PAS:1892
        public override string GetText()
        {
            string Result = "";
            switch (FMode)
            {
                case PlayerMagicEventMode.SpellResearched:
                    var spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FSpellID);
                    Result = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P4XResearchedRStr), [spell.FSpellName]);
                    break;
                case PlayerMagicEventMode.OutOfMana:
                    if (AoWHSMap.Current.FSeatedPlayer == FPlayer)
                    {
                        Result = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P4XRemovedOutOfManaRStr), [FEnchantmentName]);
                    }
                    else
                    {
                        Result = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.P4XRemovedRStr), [FEnchantmentName]);
                    }

                    break;
            }

            return Result;
        }

        // Spells.PAS:1874
        public override bool Execute(bool Mode, ExecuteTrigger Trigger, ExecuteDoneEvent Done)
        {
            bool Result = default;
            bool Show;
            switch (FMode)
            {
                case PlayerMagicEventMode.OutOfMana:
                    Show = Trigger == ExecuteTrigger.User;
                    break;
                case PlayerMagicEventMode.SpellResearched:
                    if (Trigger != ExecuteTrigger.User)
                    {
                        if (AoWHSMap.Current.FPlayMode == PlayMode.Turn)
                        {
                            Show = Aow.Game.Magic.Abilities.GameTables.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(WindowPopupEvent.SpellResearched);
                        }
                        else
                        {
                            Show = Aow.Game.Magic.Abilities.GameTables.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(WindowPopupEvent.SpellResearched);
                        }
                    }
                    else
                    {
                        Show = true;
                    }

                    break;
                case PlayerMagicEventMode.StartResearch:
                    Show = true;
                    break;
                default:
                    Show = false;
                    break;
            }

            if (Show)
            {
                Result = base.Execute(Mode, Trigger, Done);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:1863
        public override void ViewLocation()
        {
            sbyte X;
            X = FLocation.X;
            if (X != -1)
            {
                Aow.Game.World.Map.AoWHSMap.Current.CenterViewTo(X, FLocation.Y, FLocation.L);
                Aow.Game.World.Map.AoWHSMap.Current.PlayCenterAnimation(FLocation.X, FLocation.Y, FLocation.L);
            }
        }

        private static readonly string P4XResearchedRStr = "%s researched";
        private static readonly string P4XRemovedOutOfManaRStr = "%s removed (out of mana)";

        public enum PlayerMagicEventMode : byte
        {
            SpellResearched = 0, OutOfMana = 1, StartResearch = 2
        }

    }
}

