            {
                FMana = Value;
                if (AoWHSMap.Current.FVictoryCondition == AoWHSMap.VictoryCondition.AccumulateMana && AoWHSMap.Current.FVictoryMana <= FMana)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.GameOver(FPlayer.FPlayerIndex, GameOverStatus.Won);
                }

