            FEnchantmentStatus = FEnchantmentStatus + Set<GlobalEnchantmentStatusElement>.Of(GlobalEnchantmentStatusElement.Activated);
            Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.ValidateEnchantmentID(this);
            if (FEnchantmentMode.Contains(GlobalEnchantmentModeElement.Owned))
            {
                Owner = AoWHSMap.Current.FGlobalMagicControl.FEnchantments;
            }
            else
            {
                Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.FEnchantments.AddChild(this);
            }

            AddRef();
            Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.Update();
            if (FEnchantmentManaUpkeep != 0)
            {
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayerIndex).FMagicControl.Update();
            }

            return true;
        }

