        // Spells.PAS:2599
        public virtual bool Dispel(byte Player)
        {
            bool Result;
            string Reason = "";
            XYL Location;
            GlobalEnchantmentEventLog Log;
            if (CanDispel((sbyte)Player, ref Reason))
            {
                AddRef();
                Location = GetLocation();
                for (int I = 1, last = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetCount() - 1; I <= last; I++)
