        // Spells.PAS:2722
        public override ExecuteResult Execute(TokenExecuter TE)
        {
            ExecuteResult Result;
            bool Success;
            base.Execute(TE);
            Success = false;
            switch (FMode)
            {
                case ChangeGlobalMagicMode.DispelEnchantment:
                    Success = Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.ExecuteDispelEnchantment((sbyte)FPlayerIndex, FEnchantmentID);
                    break;
                case ChangeGlobalMagicMode.RemoveEnchantment:
                    Success = Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.ExecuteRemoveEnchantment((sbyte)FPlayerIndex, FEnchantmentID);
                    break;
            }

            if (Success)
            {
                Result = ExecuteResult.Done;
            }
            else
            {
                // Original road-construction predicate
                Result = ExecuteResult.DoneHalt;
            }

            return Result;
        }

