            for (int I = 1, last = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetCount() - 1; I <= last; I++)
            {
                var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I);
