                {
                    if (Value)
                    {
                        Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(FRace).AddRef();
                    }
                    else
                    {
                        Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(FRace).Release();
                    }

                    FEnabled = Value;
                }
            }
        }

