        private static int StatusToStatusValue(Status Status)
        {
            int result;
            switch ((int)Status)
            {
                case 0:
                    result = 10;
                    break;
                case 1:
                    result = 30;
                    break;
                case 2:
                    result = 50;
                    break;
                case 3:
                    result = 70;
                    break;
                case 4:
                    result = 90;
                    break;
                default:
                    result = 50;
                    new ArgumentException("Invalid TStatus Value");
                    break;
            }
            return result;
        }

        internal static Status StatusValueToStatus(int Value)
        {
            Status result;
            if (Value <= 20)
            {
                result = Status.Hostile;
            }
            else if (Value > 80)
            {
                result = Status.Friendly;
            }
            else
            {
                switch (Value)
                {
                    case 21:
                    case 22:
                    case 23:
                    case 24:
                    case 25:
                    case 26:
                    case 27:
                    case 28:
                    case 29:
                    case 30:
                    case 31:
                    case 32:
                    case 33:
                    case 34:
                    case 35:
                    case 36:
                    case 37:
                    case 38:
                    case 39:
                    case 40:
                        result = Status.Wary;
                        break;
                    case 41:
                    case 42:
                    case 43:
                    case 44:
                    case 45:
                    case 46:
                    case 47:
                    case 48:
                    case 49:
                    case 50:
                    case 51:
                    case 52:
                    case 53:
                    case 54:
                    case 55:
                    case 56:
                    case 57:
                    case 58:
                    case 59:
                    case 60:
                        result = Status.Neutral;
                        break;
                    case 61:
                    case 62:
                    case 63:
                    case 64:
                    case 65:
                    case 66:
                    case 67:
                    case 68:
                    case 69:
                    case 70:
                    case 71:
                    case 72:
                    case 73:
                    case 74:
                    case 75:
                    case 76:
                    case 77:
                    case 78:
                    case 79:
                    case 80:
                        result = Status.Polite;
                        break;
                    default:
                        result = Status.Neutral;
                        new ArgumentException("Invalid StatusValue");
                        break;
                }
            }
            return result;
        }

