        {
            int Result;
            if (FStatistics.FTurnInfo.Count != 0)
            {
                var count = FStatistics.FTurnInfo.Count;
                Result = FStatistics.FTurnInfo.GetTurnInfo(count - 1).GetSuperiority();
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

