        // Player.PAS:688
        public int GetHeroCountMax()
        {
            int Result;
            int Strength;
            int Maximum;
            var count = FStatistics.FTurnInfo.Count;
            Strength = FStatistics.FTurnInfo.GetTurnInfo(count - 1).FArmyStrength;
            if (Strength < 10)
            {
                Result = 1;
            }
            else
            {
                if (Strength < 40)
                {
                    Result = 2;
                }
                else
                {
                    if (Strength < 80)
                    {
                        Result = 3;
                    }
                    else
                    {
                        if (Strength < 120)
                        {
                            Result = 4;
                        }
                        else
                        {
                            if (Strength < 200)
                            {
                                Result = 5;
                            }
                            else
                            {
                                Result = (Strength - 200) / 100 + 5;
                            }
                        }
                    }
                }
            }

            Maximum = AoWHSMap.Current.FHeroCountMax;
            if (Maximum < Result)
            {
                Result = Maximum;
            }

            return Result;
        }

        // Player.PAS:703
        public int GetIdealHeroJoinDay()
        {
            int Average;
            int Maximum;
            int Result = FLastHeroJoinDay;
            Average = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetAverageHeroCount();
            Maximum = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetMaxHeroCount();
            if (Maximum > Average && FHeroes.Count == Maximum)
            {
                Result += 15;
            }
            else
            {
                if (Average <= FHeroes.Count && FHeroes.Count != 0 && AoWHSMap.Current.FDay > 15)
                {
                    Result += 10;
                }
                else
                {
                    Result += 5;
                }
            }

            return Result;
        }

        // Player.PAS:717
        public int GetIdealHeroEmergeDay()
        {
            int Average;
            int Maximum;
            int Earliest;
            int Result = GetIdealHeroJoinDay();
            Average = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetAverageHeroCount();
            Maximum = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetMaxHeroCount();
            if (Maximum > Average && FHeroes.Count == Maximum)
            {
                Result += 15;
            }
            else
            {
                if (Average < FHeroes.Count && FHeroes.Count != 0 && AoWHSMap.Current.FDay > 10)
                {
                    Result += 10;
                }
                else
                {
                    Result += 5;
                }
            }

            Earliest = FLastHeroEmergeDay + 5;
            if (Earliest > Result)
            {
                Result = Earliest;
            }

            return Result;
        }

