        // Player.PAS:921
        public void UpdateLogbook()
        {
            while (true)
            {
                bool condition = FEventLogbook.GetCount() != 0;
                if (condition)
                {
                    var logs = FEventLogbook.GetLogs(0);
                    condition = AoWHSMap.Current.FDay - logs.FDay >= 3;
