        // Player.PAS:1175
        public int CaptureLocationsLeft()
        {
            int Result = 0;
            for (int I = 0, last = FVictoryLocations.Count - 1; I <= last; I++)
            {
                if (FVictoryLocations.GetStructure(I).FPlayer != FPlayerIndex)
                {
                    bool condition = FVictoryLocations.GetStructure(I).FPlayer > 0;
                    if (condition)
                    {
                        var structure = FVictoryLocations.GetStructure(I);
                        condition = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation(structure.FPlayer, FPlayerIndex) == DiplomaticRelation.Alliance;
                    }

                    if (!(condition && AoWHSMap.Current.FAlliedVictory))
                    {
                        Result += 1;
                    }
                }
            }

            return Result;
        }

        // Player.PAS:1188
        public DiplomaticAction CreateDiplomaticAction(DiplomaticProposal Proposal, sbyte Target, sbyte Other)
        {
            DiplomaticAction Result;
            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Target).FStatus == Status.Playing)
            {
                Result = new DiplomaticAction(null);
                Result.FSource = FPlayerIndex;
                Result.FTarget = Target;
                Result.FOtherPlayer = Other;
                Result.Proposal = Proposal;
                Result.RetrieveDefaultMessage(FPlayerIndex, Target, Other, DiplomaticActionReaction.None);
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Player.PAS:1203
        public bool DiplomaticActionAleadySend(byte Kind, sbyte Target, sbyte Other)
        {
            EventLogbook Logbook;
            int I;
            DiplomaticAction Item;
            Logbook = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Target).FEventLogbook;
            bool Result = false;
            I = Logbook.GetCount();
            while (!Result && I != 0)
            {
                I -= 1;
                if (Logbook.GetLogs(I).FDay == AoWHSMap.Current.FDay)
                {
                    if (Logbook.GetLogs(I) is DiplomaticActionEventLog)
                    {
                        Item = ((DiplomaticActionEventLog)Logbook.GetLogs(I)).FAction;
                        Result = Item.Proposal.ToFields().Kind == Kind && Item.FSource == FPlayerIndex && Item.FTarget == Target && (Other == -1 || Item.FOtherPlayer == Other);
                    }
                }
            }

            return Result;
        }

        // Player.PAS:1226
        public int ListDiplomaticActions(sbyte Player, ref DiplomaticActionList Actions)
        {
            int Count;
            DiplomaticRelation Relation;
            DiplomaticAction Action;
            if (Player != FPlayerIndex && GetFirstDaySeen(Player) != -1)
            {
                Count = Actions.Count;
                Relation = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation(Player, FPlayerIndex);
                if (FPlayerType == PlayerType.Human && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType == PlayerType.Human)
                {
                    Action = CreateDiplomaticAction(new SendMessage(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (Set<DiplomaticRelation>.Of(DiplomaticRelation.War, DiplomaticRelation.Unknown).Contains(Relation) && !DiplomaticActionAleadySend(OfferPeace.Kind, Player, -1))
                {
                    Action = CreateDiplomaticAction(new OfferPeace(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (Relation != DiplomaticRelation.War && Relation != DiplomaticRelation.Alliance)
                {
                    Action = CreateDiplomaticAction(new DeclareWar(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (Set<DiplomaticRelation>.Of(DiplomaticRelation.Peace).Contains(Relation) && !DiplomaticActionAleadySend(ProposeAlliance.Kind, Player, -1))
                {
                    Action = CreateDiplomaticAction(new ProposeAlliance(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                if (Set<DiplomaticRelation>.Of(DiplomaticRelation.Peace, DiplomaticRelation.Unknown).Contains(Relation) && !DiplomaticActionAleadySend(ThreatenToAttack.Kind, Player, -1))
                {
                    Action = CreateDiplomaticAction(new ThreatenToAttack(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                Action = CreateDiplomaticAction(new MakeTribute(), Player, -1);
                if (Action != null)
                {
                    Actions.AddChild(Action);
                    Action.Release();
                }

                if (Set<DiplomaticRelation>.Of(DiplomaticRelation.Alliance).Contains(Relation))
                {
                    Action = CreateDiplomaticAction(new BreakAlliance(), Player, -1);
                    if (Action != null)
                    {
                        Actions.AddChild(Action);
                        Action.Release();
                    }
                }

                for (int I = 1, last = AoWHSMap.Current.FPlayers.Count - 1; I <= last; I++)
                {
                    if (I != Player && I != FPlayerIndex && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FStatus == Status.Playing)
                    {
                        bool condition = !DiplomaticActionAleadySend(DeclareWarToY.Kind, Player, (sbyte)I) && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1;
                        if (condition)
                        {
                            var diplomaticRelation = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation(Player, (sbyte)I);
                            condition = Set<DiplomaticRelation>.Of(DiplomaticRelation.Peace, DiplomaticRelation.Unknown).Contains(diplomaticRelation);
                        }

                        if (condition)
                        {
                            Action = CreateDiplomaticAction(new DeclareWarToY(), Player, (sbyte)I);
                            if (Action != null)
                            {
                                Actions.AddChild(Action);
                                Action.Release();
                            }
                        }
                    }
                }

                for (int I = 1, last = AoWHSMap.Current.FPlayers.Count - 1; I <= last; I++)
                {
                    if (I != Player && I != FPlayerIndex && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FStatus == Status.Playing)
                    {
                        if (!DiplomaticActionAleadySend(BreakAllianceWithY.Kind, Player, (sbyte)I) && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation(Player, (sbyte)I) == DiplomaticRelation.Alliance)
                        {
                            Action = CreateDiplomaticAction(new BreakAllianceWithY(), Player, (sbyte)I);
                            if (Action != null)
                            {
                                Actions.AddChild(Action);
                                Action.Release();
                            }
                        }
                    }
                }

                if (FPlayerRace == 5 && FHeroEmerging && FPlayerType == PlayerType.Human && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType == PlayerType.Human)
                {
                    for (int I = 1, last = AoWHSMap.Current.FPlayers.Count - 1; I <= last; I++)
                    {
                        if (I != Player && I != FPlayerIndex && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FStatus == Status.Playing && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType == PlayerType.Human)
                        {
                            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayerIndex).GetFirstDaySeen((sbyte)I) != -1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetFirstDaySeen((sbyte)I) != -1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).GetFirstDaySeen(Player) != -1)
                            {
                                Action = CreateDiplomaticAction(new SendMessageAsY(), Player, (sbyte)I);
                                if (Action != null)
                                {
                                    Actions.AddChild(Action);
                                    Action.Release();
                                }
                            }
                        }
                    }
                }

                Count = Actions.Count - Count;
            }
            else
            {
                Count = 0;
            }

            return Count;
        }

        // Player.PAS:1348
        public bool ValidAttackRelation(sbyte Player, sbyte IndependentRelation)
        {
            bool Result;
            Assert(FPlayerIndex != 0, "", "Player.PAS", 1390);
            if (Set<PlayerType>.Of(PlayerType.CPU1, PlayerType.CPU2, PlayerType.CPU3, PlayerType.CPU4, PlayerType.CPU5).Contains(FPlayerType))
            {
                Result = FAIValidAttackPlayers[Player];
            }
            else
            {
                var diplomaticRelation = Aow.Game.Magic.Abilities.AbilityRules.DiplomaticRelation(FPlayerIndex, 0, Player, IndependentRelation);
                Result = Set<DiplomaticRelation>.Of(DiplomaticRelation.War, DiplomaticRelation.Unknown).Contains(diplomaticRelation);
            }

            return Result;
        }

