        // Player.PAS:1657
        public void ValidateRaces(RaceList Races)
        {
            IntegerList Available;
            IntegerList Invalid;
            int I;
            int Index;
            int DefaultRace;
            Available = new IntegerList();
            Invalid = new IntegerList();
            I = 0;
            int last = Races.Count - 1;
            for (; I <= last; I += 1)
            {
                if (Races.GetRace(I).FEnabled)
                {
                    Available.Add(I);
                }
            }

            I = 1;
            int limit = FChildren.Count - 1;
            for (; I <= limit; I += 1)
            {
                Index = Available.IndexOf(((Player)FChildren.List[I]).FPlayerRace);
                if (Index == -1)
                {
                    Invalid.Add(I);
                }
                else
                {
                    Available.Delete(Index);
                }
            }

            I = 0;
            DefaultRace = -1;
            while (I != Count && DefaultRace == -1)
            {
                if (Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(I) != null)
                {
                    if (Races == null || Races.GetRace(I).FEnabled)
                    {
                        DefaultRace = I;
                    }
                }

                I += 1;
            }

            I = 0;
            int last2 = Invalid.Count - 1;
            for (; I <= last2; I += 1)
            {
                if (Available.Count == 0)
                {
                    var item = Invalid[I];
                    ((Player)FChildren.List[item]).SetRace((sbyte)DefaultRace);
                }
                else
                {
                    var item = Available[0];
                    var invalidItem = Invalid[I];
                    ((Player)FChildren.List[invalidItem]).SetRace((sbyte)item);
                    Available.Delete(0);
                }
            }

            Invalid?.Dispose();
            Available?.Dispose();
        }

