        // MoveT.PAS:1608
        public void CalculateGaps(int SourceX, int SourceY, int DestinationX, int DestinationY)
        {
            int X;
            int Y;
            int Direction;
            int OverCode;
            AoWMapField Field;
            bool Clear;
            int Points = default;
            Clear = true;
            FGapStarts.Count = 0;
            FGapEnds.Count = 0;
            FDirectRoute.Count = 0;
            OverCode = 1;
            FDirectRoute.AddXYL((sbyte)SourceX, (sbyte)SourceY, 0);
            X = 0;
            Y = 0;
            Direction = 0;
            while (SourceX != DestinationX || SourceY != DestinationY)
            {
                if (SourceX == DestinationX)
                {
                    if (SourceY > DestinationY)
                    {
                        Direction = 1;
                        X = SourceX;
                        Y = SourceY - 1;
                    }
                    else
                    {
                        if (SourceY < DestinationY)
                        {
                            Direction = 4;
                            X = SourceX;
                            Y = SourceY + 1;
                        }
                    }
                }
                else
                {
                    if ((SourceX & 1) == 0)
                    {
                        if (SourceX > DestinationX)
                        {
                            if (SourceY > DestinationY)
                            {
                                Direction = 6;
                                X = SourceX - 1;
                                Y = SourceY - 1;
                            }
                            else
                            {
                                Direction = 5;
                                X = SourceX - 1;
                                Y = SourceY;
                            }
                        }
                        else
                        {
                            if (SourceY > DestinationY)
                            {
                                Direction = 2;
                                X = SourceX + 1;
                                Y = SourceY - 1;
                            }
                            else
                            {
                                Direction = 3;
                                X = SourceX + 1;
                                Y = SourceY;
                            }
                        }
                    }
                    else
                    {
                        if (SourceX > DestinationX)
                        {
                            if (SourceY < DestinationY)
                            {
                                Direction = 5;
                                X = SourceX - 1;
                                Y = SourceY + 1;
                            }
                            else
                            {
                                Direction = 6;
                                X = SourceX - 1;
                                Y = SourceY;
                            }
                        }
                        else
                        {
                            if (SourceY < DestinationY)
                            {
                                Direction = 3;
                                X = SourceX + 1;
                                Y = SourceY + 1;
                            }
                            else
                            {
                                Direction = 2;
                                X = SourceX + 1;
                                Y = SourceY;
                            }
                        }
                    }
                }

                Field = (AoWMapField)FMapLevel.GetField(X, Y);
                Points = FOnMovePoint(Field, OverCode);
                if (Points >= 0)
                {
                    if ((Field.FFieldFlags & 8192) != 0 && (X != DestinationX || Y != DestinationY))
                    {
                        OverCode = Field.CanMoveOver(this);
                        if (OverCode == 0)
                        {
                            Points = -1;
                            OverCode = 1;
                        }
                    }
                    else
                    {
                        OverCode = 1;
                    }
                }

                if (Points < 0)
                {
                    if (Clear)
                    {
                        FGapStarts.AddXYL((sbyte)SourceX, (sbyte)SourceY, (sbyte)Direction);
                        Clear = false;
                        OverCode = 1;
                    }
                }
                else
                {
                    if (!Clear)
                    {
                        FGapEnds.AddXYL((sbyte)X, (sbyte)Y, -1);
                        Clear = true;
                    }
                }

                SourceX = X;
                SourceY = Y;
                FDirectRoute.AddXYL((sbyte)SourceX, (sbyte)SourceY, (sbyte)Points);
            }

            if (!Clear)
            {
                FGapEnds.AddXYL((sbyte)DestinationX, (sbyte)DestinationY, -1);
            }
        }

        // MoveT.PAS:1815
        public int GetMovePointsCostFast(int SourceX, int SourceY, int DestinationX, int DestinationY)
        {
            int I;
            int Points;
            int GapIndex;
            int Cost;
            I = 1;
            GapIndex = 0;
            Points = 0;
            CalculateGaps(SourceX, SourceY, DestinationX, DestinationY);
            while (I < FDirectRoute.Count && Points != -1)
            {
                Cost = FDirectRoute[I].L;
                if (Cost < 0)
                {
                    var item = FDirectRoute[I - 1];
                    var fDirectRouteItem = FDirectRoute[I - 1];
                    GapIndex = FGapStarts.IndexOfXY(fDirectRouteItem.X, item.Y);
                    Cost = CalculateTurnAroundMovePoints(ref GapIndex);
                    if (Cost != -1)
                    {
                        Points += Cost;
                        var fGapEndsItem = FGapEnds[GapIndex];
                        var item2 = FGapEnds[GapIndex];
                        I = FDirectRoute.IndexOfXY(item2.X, fGapEndsItem.Y);
                    }
                    else
                    {
                        Points = -1;
                    }
                }
                else
                {
                    Points += Cost;
                }

                I += 1;
            }

            return Points;
        }

        private static FixedArray_int_7 P5OppositeDirections = global::Aow.Game.Engine.Buffers.FixedArray_int_7.From([0, 4, 5, 6, 1, 2, 3]);
        private static FixedArray_Aow_Units_FixedArray_int_2_7 P5SideDirections = FixedArray_Aow_Units_FixedArray_int_2_7.From([FixedArray_int_2.From([-1, -1]), FixedArray_int_2.From([6, 2]), FixedArray_int_2.From([1, 3]), FixedArray_int_2.From([2, 4]), FixedArray_int_2.From([3, 5]), FixedArray_int_2.From([4, 6]), FixedArray_int_2.From([5, 1])]);
        private static FixedArray_Aow_Units_FixedArray_byte_3_6 P5OddDirections = FixedArray_Aow_Units_FixedArray_byte_3_6.From([FixedArray_byte_3.From([1, 3, 5]), FixedArray_byte_3.From([3, 1, 5]), FixedArray_byte_3.From([3, 5, 1]), FixedArray_byte_3.From([5, 3, 1]), FixedArray_byte_3.From([5, 1, 3]), FixedArray_byte_3.From([1, 5, 3])]);
        private static FixedArray_Aow_Units_FixedArray_byte_3_6 P5EvenDirections = FixedArray_Aow_Units_FixedArray_byte_3_6.From([FixedArray_byte_3.From([2, 4, 6]), FixedArray_byte_3.From([4, 2, 6]), FixedArray_byte_3.From([4, 6, 2]), FixedArray_byte_3.From([6, 4, 2]), FixedArray_byte_3.From([6, 2, 4]), FixedArray_byte_3.From([2, 6, 4])]);

