        // PlayerC.PAS:1018
        public void TriggerGameRestartedEvents(sbyte Player)
        {
            RestartGameEventLog Log;
            Aow.Game.World.Map.AoWHSMap.Current.SynchroniseBegin();
            Log = new RestartGameEventLog(null);
            Log.FPlayer = Player;
