            if (!FIgnoreMouseDown)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.Mouse.Shift.Contains(ShiftState.Shift))
                {
                    if (FMoveSettingsList.Count == 1 && FMoveSettingsList.GetMoveSettings(0).FPath.Count != 0)
                    {
