                    if (Aow.Game.World.Map.AoWHSMap.Current.Mouse.Shift.Contains(ShiftState.Ctrl))
                    {
                        if (FMoveSettingsList.Count > 1 && AoWHSMap.Current.Mouse.Xhx != -1)
