        // Army.PAS:3742
        public override bool ValidateSelection(AoWMapField Field)
        {
            bool Result;
            if (FMoveSettingsList.Count > 1)
            {
                Result = ValidMultiMoveSelection(Field);
            }
            else
            {
                Result = base.ValidateSelection(Field);
            }

            if (FMode == Mode.BuildRoads)
            {
                if (Field.GetPlayer() != -1 && Field.GetPlayer() != GetArmyHS().FArmy.FPlayer)
                {
                    Result = false;
                }
            }

            return Result;
        }

        // Army.PAS:3904
        public override void ExecuteMove()
        {
            ArmyHS ArmyHS;
            AoWMapField Field;
            int Cost;
            if (FMoveSettingsList.Count == 1)
            {
                var moveSettings = FMoveSettingsList.GetMoveSettings(FCurrentMove);
                if (moveSettings.FPath.Count > 1 && GetArmyHS() != null)
                {
                    ArmyHS = GetArmyHS();
                    var item = moveSettings.FPath[0];
                    var fPathItem = moveSettings.FPath[0];
                    var item2 = moveSettings.FPath[0];
                    Field = (AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(item2.X, fPathItem.Y, item.L);
                    bool condition = Field.GetMoveAction(ArmyHS.FArmy.FPlayer) != MoveAction.Attack || Field.GetPlayer() <= 0;
                    if (!condition)
                    {
                        var player = Field.GetPlayer();
                        var diplomaticRelation = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation(ArmyHS.FArmy.FPlayer, player);
                        condition = Set<DiplomaticRelation>.Of(DiplomaticRelation.War, DiplomaticRelation.Unknown).Contains(diplomaticRelation);
                    }

                    if (condition)
                    {
                        if (FMode == Mode.BuildRoads)
                        {
                            Cost = Aow.Game.Magic.Abilities.AbilityRules.RoadConstructionCost(ArmyHS.FArmy.FPlayer, moveSettings.FPath, moveSettings.FMovePoints);
                            if (Cost <= Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(ArmyHS.FArmy.FPlayer).FGems)
                            {
                                if (global::Aow.Game.Draw.ArmyHS.MoveArmyEx(ArmyHS, GetSelection(), moveSettings.FPath, Set<ArmyMoveModeElement>.Of(ArmyMoveModeElement.SelectEndLocation, ArmyMoveModeElement.BuildRoads), false))
                                {
                                    moveSettings.FPath.Clear();
                                    if (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting))
                                    {
                                        Aow.Game.World.Map.AoWHSMap.Current.Selection.UnselectLocation();
                                    }

                                    DeactivateMoveSelection();
                                }
                            }
                            else
                            {
                                var notEnoughGold = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NotEnoughGoldRStr);
                                Aow.Game.World.Map.AoWHSMap.Current.ShowWarning(notEnoughGold);
                            }
                        }
                        else
                        {
                            var item3 = moveSettings.FPath[0];
                            var item4 = moveSettings.FPath[0];
                            var item5 = moveSettings.FPath[0];
                            ArmyHS.FArmy.SetDestinationPos(item5.X, item4.Y, item3.L);
                            if (global::Aow.Game.Draw.ArmyHS.MoveArmy(ArmyHS, GetSelection(), moveSettings.FPath))
                            {
                                var movePoints = ArmyHS.FArmy.MovePoints(255);
                                if (moveSettings.FPath.MovePointsToPos(movePoints) > 0)
                                {
                                    var army = ArmyHS.FArmy;
                                    army.FUserMode = army.FUserMode + Set<ArmyUserModeElement>.Of(ArmyUserModeElement.TurnDone);
                                }

                                moveSettings.FPath.Clear();
                                if (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting))
                                {
                                    Aow.Game.World.Map.AoWHSMap.Current.Selection.UnselectLocation();
                                }

                                DeactivateMoveSelection();
                            }
                        }
                    }
                    else
                    {
                        if (((Field.FFieldFlags >> 16) & 255) != 0 || !AoWHSMap.Current.FFogEnabled)
                        {
                            var player = Field.GetPlayer();
                            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(player);
                            var raceNamesPlural = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameTables.RaceNamesPluralRStr[players.FPlayerRace]);
                            var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(ArmyNotAtWarRStr), [raceNamesPlural]);
                            Aow.Game.World.Map.AoWHSMap.Current.ShowMessage(format);
                        }
                    }
                }
            }
            else
            {
                if (FMoveSettingsList.Count > 1 && Aow.Game.Units.SelectedArmy.ExecuteMultiArmyMove(FMoveSettingsList))
                {
                    for (int I = 0, last = FMoveSettingsList.Count - 1; I <= last; I++)
                    {
                        var moveSettings = FMoveSettingsList.GetMoveSettings(I);
                        var item = moveSettings.FPath[0];
                        var fPathItem = moveSettings.FPath[0];
                        var item2 = moveSettings.FPath[0];
                        ((ArmyHS)moveSettings.FMoveObject).FArmy.SetDestinationPos(item2.X, fPathItem.Y, item.L);
                        moveSettings.FPath.Clear();
                    }

                    Deactivate();
                    Aow.Game.World.Map.AoWHSMap.Current.Selection.UnselectLocation();
                    Clear();
                }
            }
        }

