        // Army.PAS:3657
        public void UpdateSelectedUnitGFX()
        {
            int Index;
            IntegerList List;
            List = new IntegerList();
            if (GetArmyHS() != null)
            {
                for (int I = 0, last = GetArmyHS().FArmy.Count - 1; I <= last; I++)
                {
                    Index = GetArmyHS().FArmy.GetUnit(I).GetUnitGFXResourceIndex();
                    List.Add(Index);
                    Aow.Game.Engine.AoWHSSet.Current.FUnitGFXResources.GetUnitGFXResource(Index).AddRef();
