            }

            if (SelectStructure && Xhx != -1)
            {
                var yhx = Yhx;
                var xhx = Xhx;
                Structure = (Structure)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(xhx, yhx, AoWHSMap.Current.ViewL).FindNoneTransparentHS(typeof(Structure));
