                {
                    Aow.Game.World.Map.AoWHSMap.Current.Selection.UnselectLocation();
                    Aow.Game.World.Map.AoWHSMap.Current.Selection.SelectLocationHS(Structure);
                }
            }

            base.DblClick();
        }

