        // AoWHSMap.PAS:759
        public virtual void ShowBackHexagonSelector(int XhpSurf, int YhpSurf, in SurfaceDesc SurfaceDesc)
        {
            int Xhp = default;
            int Yhp = default;
            if (FSelectorX != -1 && FSelectorY != -1 && Mouse.Capture == AoWHSMap.Current.FSelectedArmy)
