            int Yhp = default;
            if (FSelectorX != -1 && FSelectorY != -1 && Mouse.Capture == AoWHSMap.Current.FSelectedArmy)
            {
                Aow.Game.World.Map.HexGeometry.HXtoHP(FSelectorX, FSelectorY, ref Xhp, ref Yhp);
