        // AoWHSMap.PAS:451
        public void MapChangedRad(int X, int Y, int L, int Radius)
        {
            Rect R = default;
            MapLevel Level;
            Level = MapContainer.GetMapLevel(L);
            R.Left = X - Radius;
            if (R.Left < 0)
            {
                R.Left = 0;
            }

            R.Right = X + Radius + 1;
            if (R.Right > Level.Width)
            {
                R.Right = Level.Width;
            }

            R.Top = Y - Radius;
            if (R.Top < 0)
            {
                R.Top = 0;
            }

            R.Bottom = Y + Radius + 1;
            if (R.Bottom > Level.Height)
            {
                R.Bottom = Level.Height;
            }

            TerrainChanged(R, (sbyte)L);
        }

