        public void InvalidateMap()
        {
            Rect R = default;
            R.Left = 0;
            R.Right = MapContainer.Width;
            R.Top = 0;
            R.Bottom = MapContainer.Height;
            for (int I = 0, last = MapContainer.LevelCount - 1; I <= last; I++)
            {
                MapChanged(R, I);
            }
        }

