        // AoWHSMap.PAS:892
        public void DrawSelectionRect(int XhpSurf, int YhpSurf, in Rect R, in SurfaceDesc SurfaceDesc)
        {
            int Color;
            Color = 2134015;
            if (R.Left > 0 && R.Top > 0 && XhpSurf < R.Right && YhpSurf < R.Bottom && R.Right < ViewWidth + XhpSurf && R.Bottom < ViewHeight + YhpSurf)
            {
                Aow.Game.World.Map.AbstractAoWHSMap.DrawLine(R.Left - XhpSurf, R.Top - YhpSurf, R.Right - XhpSurf, R.Top - YhpSurf, 0, Color, SurfaceDesc);
                Aow.Game.World.Map.AbstractAoWHSMap.DrawLine(R.Right - XhpSurf, R.Top - YhpSurf, R.Right - XhpSurf, R.Bottom - YhpSurf, 0, Color, SurfaceDesc);
                Aow.Game.World.Map.AbstractAoWHSMap.DrawLine(R.Right - XhpSurf, R.Bottom - YhpSurf, R.Left - XhpSurf, R.Bottom - YhpSurf, 0, Color, SurfaceDesc);
                Aow.Game.World.Map.AbstractAoWHSMap.DrawLine(R.Left - XhpSurf, R.Bottom - YhpSurf, R.Left - XhpSurf, R.Top - YhpSurf, 0, Color, SurfaceDesc);
            }
        }

        // AoWHSMap.PAS:666 advances a pointer one row. GetField retains that row order.
        public void DrawFog(in SurfaceDesc surface)
        {
            bool exploration = FExplorationEnabled || FSeatedPlayer == -1;
            if (!FFogEnabled && !exploration) return;
            var level = MapContainer.GetMapLevel(ViewL);
            for (int x = ViewXhx; x < ViewXhx + ViewWidthHX; x++)
            {
                int xhp = 0, yhp = 0;
                Aow.Game.World.Map.HexGeometry.HXtoHP(x, ViewYhx, ref xhp, ref yhp);
                xhp -= ViewXhp + 8;
                yhp -= ViewYhp + 4;
                for (int y = ViewYhx; y < ViewYhx + ViewHeightHX; y++, yhp += 32)
                {
                    var field = (AoWMapField)level.GetField(x, y);
                    bool unexplored = exploration && (FSeatedPlayer == -1 || !field.GetExplored(FSeatedPlayer));
                    if (unexplored) AoWHSSet.Current.FGeneralImages[3].Show(xhp, yhp, surface);
                    else if (FFogEnabled && ((field.FFieldFlags >> 16) & 255) == 0)
                        AoWHSSet.Current.FGeneralImages[1].Show(xhp, yhp, surface);
                }
            }
        }

        public void DrawGrid(in SurfaceDesc surface)
        {
            var level = MapContainer.GetMapLevel(ViewL);
            int maxX = ViewXhx + ViewWidthHX - 1, maxY = ViewYhx + ViewHeightHX - 1;
            for (int x = ViewXhx; x <= maxX; x++)
            {
                int xhp = 0, yhp = 0;
                Aow.Game.World.Map.HexGeometry.HXtoHP(x, ViewYhx, ref xhp, ref yhp);
                xhp = xhp - ViewXhp - 8;
                yhp = yhp - ViewYhp - 4 + 4;
                for (int y = ViewYhx; y <= maxY; y++, yhp += 32)
                    if (level.GetField(x, y).TerrainType != 15)
                        AoWHSSet.Current.FFlagControl.FFlags[7].Show(xhp, yhp, surface);
            }
        }

        private static void DrawLine(int X1, int Y1, int X2, int Y2, int Skip, int Color, in SurfaceDesc SD)
        {
            int pixelFormatID = SD.PixelFormatID;
            int num = pixelFormatID;
            if (num == 1431343888 || num == 1431409424 || num == 1448121104)
            {
                int num2 = global::Aow.Game.Draw.PixelFormats.Color2PixelInfo(Color, SD.PixelFormatID, null);
                DrawLine16(X1, Y1, X2, Y2, 0, (ushort)num2, in SD);
            }
        }

        private static void DrawLine16(int X1, int Y1, int X2, int Y2, int Skip, ushort Color, in SurfaceDesc SD)
        {
            Aow.Graphics.Blit.DrawLine16(X1, Y1, X2, Y2, Skip, Color, SD.View());
        }
    }
