        public StartupSongList(ECustomNode owner) : base(owner)
        {
            Songs.OnChange = OriginalSongsChanged;
        }

        // AoWHSMap.PAS:1221
        public void OriginalSongsChanged(object Sender)
        {
            string Name;
            SongNames.Clear();
            for (int I = Songs.Count - 1; I >= 0; I--)
            {
                try
                {
                    Name = Aow.Game.Audio.AudioPlayback.GetSongName(Songs[I]);
                }
                catch
                {
                    Name = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.FileNotFoundRStr);
                }

                SongNames.Insert(0, Name);
            }
        }

        // intf_P1_05.inc:194

    }
}

