        public IndependentAIMode GetIndependentAIMode()
        {
            IndependentAIMode Result = FIndependentAIMode;
            if (!global::Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting) && global::Aow.Game.World.Map.AoWHSMap.Current.FGlobalMagicControl.FActiveEnchantments.Contains(GlobalEnchantmentType.FireMastery))
            {
                if (Result == IndependentAIMode.Off)
                {
