        {
            FAILockCount += 1;
        }

        // AoWHSMap.PAS:1990
        public void UnlockExecuteEventLog()
        {
            FAILockCount -= 1;
            if (FAILockCount == 0)
            {
                ExecuteNextEventLog();
            }
        }

