            Aow.Game.Engine.Nodes.EMsg.InitMsg(ref Msg, 537002243, this);
            Msg.Payload = Messages;
            Msg.Data[0] = 0;
            global::Aow.Game.World.Map.AoWHSMap.Current.SendMsg(ref Msg, this);
            bool Result = Msg.Data[0] == 0;
            if (Result)
            {
                Messages.Add(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(MapSuccessfullyValidatedRStr));
