        // AoWHSMap.PAS:3086
        public int GetTurnTimeLeft()
        {
            int Time;
            int Left;
            Left = FTurnTimeElapsed;
            if (FTurnTimerStart != -1)
            {
                Time = Aow.Game.Draw.PixelFormats.GetElapsedMilliSeconds();
                if (Time >= FTurnTimerStart)
                {
                    Left = Left - (Time - FTurnTimerStart);
                }
                else
                {
                    Left = 0;
                }
            }

            if (Left < 0)
            {
                Left = 0;
            }

            return Left;
        }

