        private static readonly string InitializingLevelRStr = "Initializing Level ";

        private static readonly string UpdatingTerrainLevelRStr = "Updating Terrain Level ";

        private static readonly string ActivatingLevelRStr = "Activating Level ";

        private static readonly string SavingLevelRStr = "Saving Level ";

        private static readonly string DestroyingLevelRStr = "Destroying Level ";

        private static bool TryEndPlayerTurn(sbyte Player)
        {
            bool Result;
            if (Player != -1 && !global::Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetBusy() && !global::Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FSingleProcessCycle)
            {
                Result = Aow.Game.Magic.Abilities.AbilityRules.EndPlayerTurn(Player);
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        private static bool CancelPlayerTurn(sbyte Player)
        {
            bool Result;
            EndTurnTE Event;
            if (!global::Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetBusy() && global::Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FSingleProcessCycle)
            {
                Event = new EndTurnTE(null);
                Event.FPlayer = Player;
                Event.FDay = Current.FDay;
                Event.FMode = EndTurnTE.EndTurnMode.CancelEndTurn;
                global::Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(Player).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

