            SetAbCount(Source.GetAbCount());
            for (int I = Source.GetAbCount() - 1; I >= 0; I--)
            {
                if (Source.GetAbSet(I) != GetAbSet(I))
                {
                    SetAbSet(I, (byte)(Source.GetAbSet(I) ? 1 : 0));
                }
