            // { Original frees the temporary list only after all ability callbacks succeed. }
            for (int I = 0, last = List.Count - 1; I <= last; I++)
            {
                ((Ability)List[I]).ListInfo(Text, Mode);
                Text.Add("-------------------------------------------------");
                Text.Add("");
            }

            List?.Dispose();
        }

