namespace Aow.Game.Units
{

    // library name, image index, item type, library, references, hidden
    public partial class ItemGFX : EResource
    {
        public new const int ClassID = 131689;

        public ItemGFX(ECustomNode owner) : base(owner)
        { }

        public string FImageLibraryName = "";
        public int FImageIndex;
        public ItemType FItemType;
        public CustomImageLibrary FImageLibrary;
        public int FRefCount;
        public bool FHidden;

        // Army.PAS:5093
        public override Engine.Engine GetEngine() => GameTables.AoWEngine;

        // Army.PAS:5167
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            if (!Stream.StorageMode().Contains(StorageModeElement.TextOnly))
            {
                Stream.rwString(ref FImageLibraryName, 6);
            }

            Stream.rwInteger(ref FImageIndex, 7);
            Stream.rwData(Bytes.Of(ref FItemType, 1), 1, 8);
            Stream.rwBool(ref FHidden, 9);
        }

        public override void PersistFields(IPersister persister)
        {
            base.PersistFields(persister);
            persister.String("ImageLibraryName", ref FImageLibraryName);
            persister.Int("ImageIndex", ref FImageIndex);
            persister.Enum("ItemType", ref FItemType);
            persister.Bool("Hidden", ref FHidden);
        }

        // Army.PAS:5138
        public override int AddRef()
        {
            if (FRefCount == 0)
            {
                LinkToIL();
            }

            FRefCount += 1;
            return FRefCount;
        }

        // Army.PAS:5145
        public override int Release()
        {
            FRefCount -= 1;
            if (FRefCount == 0)
            {
                ReleaseIL();
            }

            return FRefCount;
        }

        // Army.PAS:5152
        public override LibraryImage GetCellImage()
        {
            LibraryImage Image;
            AddRef();
            Image = FImageLibrary[FImageIndex];
            Release();
            return Image;
        }

        // Army.PAS:5103
        public int ItemGFXIndex() => Owner.FindChildIndex(this);

        // Army.PAS:5108
        public void LinkToIL()
        {
            ReleaseIL();
            if (!IsEmpty(FImageLibraryName))
            {
                FImageLibrary = Aow.Game.Engine.AoWHSSet.Current.ImageLibraryManager.LinkToIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), FImageLibraryName);
            }
            else
            {
                FImageLibrary = null;
            }
        }

        // Army.PAS:5116
        public void ReleaseIL()
        {
            if (FImageLibrary != null)
            {
                if (!IsEmpty(FImageLibraryName))
                {
                    Aow.Game.Engine.AoWHSSet.Current.ImageLibraryManager.ReleaseIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), FImageLibraryName);
                }

                FImageLibrary = null;
            }
        }

        // Army.PAS:5126
        public void SetImageLibraryName(string Value)
        {
            if (!IsEmpty(FImageLibraryName))
            {
                Aow.Game.Engine.AoWHSSet.Current.ImageLibraryManager.ReleaseIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), FImageLibraryName);
                FImageLibrary = null;
            }

            FImageLibraryName = Value;
            if (!IsEmpty(FImageLibraryName) && FRefCount != 0)
            {
                FImageLibrary = Aow.Game.Engine.AoWHSSet.Current.ImageLibraryManager.LinkToIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), FImageLibraryName);
            }
        }

        // Army.PAS:5161
        public LibraryImage GetItemImage()
        {
            LibraryImage Result;
            if (FImageLibrary != null)
            {
                Result = FImageLibrary[FImageIndex];
            }
            else
            {
                Result = null;
            }

            return Result;
        }

    }

    // inherited children, engine, control style
    public partial class ItemGFXList : EResourceList
    {
        // Army.PAS:5176
        public ItemGFXList(ECustomNode owner) : base(owner)
        {
            SetControlStyle(Set<EControlStyleElement>.Of(EControlStyleElement.SaveLoad, EControlStyleElement.FixedChild, EControlStyleElement.ArrayMode));
        }

        // Army.PAS:5182
        public ItemGFX GetItemGFX(int Index)
        {
            ItemGFX Result;
            if (Index >= 0 && Index < FChildren.Count)
            {
                Result = (ItemGFX)FChildren.List[Index];
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Army.PAS:5189
        public int FindItemTypeGFX(ItemType ItemType)
        {
            int I;
            int Result = -1;
            I = 0;
            while (Result == -1 && I != FChildren.Count)
            {
                if (FChildren.List[I] != null && ((ItemGFX)FChildren.List[I]).FItemType == ItemType)
                {
                    Result = I;
                }

                I += 1;
            }

            return Result;
        }

        // intf_P2_04.inc:37

    }
}

namespace Aow.Game.Commands
{

    // item ID, action, hero ID
    public partial class ItemTE : TokenEvent
    {
        public ItemTE(ECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131698;

        public int FItemID;
        public byte FAction;
        // 0 = use
        public int FHeroID;

        // Army.PAS:4185
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FItemID, 20);
            Stream.rwData(Bytes.Of(ref FAction, 1), 1, 21);
            Stream.rwInteger(ref FHeroID, 22);
        }

        // Army.PAS:4193
        public override ExecuteResult Execute(TokenExecuter TE)
        {
            ExecuteResult Result;
            bool Done;
            Item Item;
            Hero Hero;
            base.Execute(TE);
            Done = false;
            Item = Aow.Game.World.Map.AoWHSMap.Current.FItemControl.FindItem(FItemID);
            if (Item != null)
            {
                switch (FAction)
                {
                    case 0:
                        Hero = Aow.Game.World.Map.AoWHSMap.Current.FHeroControl.FindID(FHeroID);
                        if (Hero != null)
                        {
                            Done = Item.ExecuteUse(Hero);
                        }
                        else
                        {
                            Done = false;
                        }

                        break;
                }
            }

            if (Done)
            {
                Result = ExecuteResult.Done;
            }
            else
            {
                Result = ExecuteResult.DoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

