        {
            string Result = "";
            if (FLibraryID != -1)
            {
                Result = FLibraryName;
                if (IsEmpty(Result))
                {
                    Result = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(ItemSystemLibraryRStr);
                }
            }

            return Result;
        }

        // Army.PAS:4381
        public void UpdateFromLibrary()
        {
            int ID;
            Item Item;
            if (FLibraryID != -1)
            {
                Item = Aow.Game.Engine.AoWHSSet.Current.FItemLibraries.FindItem(FLibraryName, FLibraryID);
                if (Item != null)
                {
                    ID = FItemID;
                    Assign(Item, GameTables.AoWEngine);
                    FItemID = ID;
                    Changed();
                }
                else
                {
                    if (FOwner == null)
                    {
                        this.Dispose();
