        // Army.PAS:4474
        public bool PlaceOnMap(AbstractAoWHSMap Map, sbyte X, sbyte Y, sbyte L)
        {
            bool Result;
            ItemHS HS;
            if (X >= 0 && Y >= 0 && L >= 0 && X < Map.MapContainer.Width && Y < Map.MapContainer.Height && L < Map.MapContainer.LevelCount && Map.MapContainer.GetField(X, Y, L).TerrainType != 15)
            {
                HS = (ItemHS)Map.MapContainer.GetField(X, Y, L).FindOwnedChild(131697);
                if (HS == null)
                {
                    HS = new ItemHS(null);
                    if (!Map.PlaceHX(HS, X, Y, L))
                    {
                        HS?.Dispose();
                        HS = null;
                    }
                }

                if (HS != null)
                {
                    SetOwner(HS.FItems);
                    Result = true;
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Army.PAS:4501
        public void EditDropMsg(ref DropMsg Msg)
        {
            int X = default;
            int Y = default;
            int L;
            L = Msg.Lhp;
            Aow.Game.World.Map.HexGeometry.HPtoHX(Msg.Xhp, Msg.Yhp, ref X, ref Y);
            if (!PlaceOnMap(AoWHSMap.Current, (sbyte)X, (sbyte)Y, (sbyte)L))
            {
                Msg.Result = -1;
            }
            else
            {
                Msg.Result = 0;
