            {
                Directory = ExtractFilePath(GameTables.AoWEngine.HSSFileName);
                if (Stream.StorageMode().Contains(StorageModeElement.Read))
                {
                    ReadUserLibraries();
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFile(Directory + "ITEMS.PFS", FSystemLibrary, null);
                }
                else
                {
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFile(Directory + "ITEMS.PFS", FSystemLibrary, null);
