        // Unit.PAS:260
        public virtual int GetUnitMoraleValue(sbyte Player, sbyte IndependentRelation)
        {
            sbyte Race;
            sbyte Xhx = default;
            sbyte Yhx = default;
            sbyte Lhx = default;
            AoWTerrainType TerrainType;
            byte RawTerrain;
            int RaceIndex;
            int Morale;
            if (Player >= 0 && GetUnitType() != UnitType.Machine && !Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting))
            {
                Race = GetRace();
                Morale = GetRelationValue(Player, IndependentRelation);
                if (Race != -1)
                {
                    GetLocation(ref Xhx, ref Yhx, ref Lhx);
                    if (Xhx != -1)
                    {
                        RawTerrain = (byte)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(Xhx, Yhx, Lhx).TerrainType;
                        RaceIndex = Race;
                        TerrainType = (AoWTerrainType)RawTerrain;
                        if (City.RaceTerrain[RaceIndex].Penalty.Contains((byte)(int)TerrainType))
                        {
                            // { Read the original shared table, not the private copy. }
                            Morale -= 10;
                        }

                        if (City.RaceTerrain[RaceIndex].Bonus.Contains((byte)(int)TerrainType))
                        {
                            Morale += 10;
                        }
                    }
                }

                if (GetAbilityEnabled(53))
                {
                    Morale -= 40;
                }

                if (GetAbilityEnabled(108))
                {
                    Morale -= 80;
                }

                if (Morale < 0)
                {
                    Morale = 0;
                }

                if (Morale > 100)
                {
                    Morale = 100;
                }
            }
            else
            {
                Morale = 50;
            }

            return Morale;
        }

