        // Unit.PAS:1100
        public virtual void MovedTo(MapField OldField, MapField NewField, int MaxCost)
        {
            int Cost = default;
            bool Transported = default;
            EObject Army = default;
            Cost = MovePointCost(NewField.TerrainType, NewField.OverlayType);
            if (Cost < 0)
            {
                Cost = MaxCost;
            }
            else
            {
                if (Cost > MaxCost)
                {
                    Cost = MaxCost;
                }
            }

            if (!AoWHSMap.Current.FUnlimitedMoves || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FPlayerType != PlayerType.Human)
            {
                if (Cost > GetMovePoints())
                {
                    SetMovePoints(0);
                }
                else
                {
                    SetMovePoints((sbyte)(GetMovePoints() - Cost));
                }
            }

            if (NewField.TerrainType == (int)AoWTerrainType.Earth)
            {
                Aow.Game.World.Map.AoWHSMap.Current.ChangeTerrain(null, NewField.Xhx, NewField.Yhx, NewField.Lhx, 0, (int)AoWTerrainType.Dirt);
            }

            if (OldField != null)
            {
                Army = Owner;
                Transported = Army is Army && ((Army)Army).Transporter(255) != null;
                if (!Transported)
                {
                    if (OldField.Lhx == 0)
                    {
                        if (GetAbilityEnabled(69))
                        {
                            Aow.Game.World.Map.AoWHSMap.Current.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfLifeTerrainChange, null);
                        }
                        else
                        {
                            if (GetAbilityEnabled(68))
                            {
                                Aow.Game.World.Map.AoWHSMap.Current.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfDecayTerrainChange, null);
                            }
                        }
                    }

                    if (GetAbilityEnabled(109))
                    {
                        Aow.Game.World.Map.AoWHSMap.Current.ChangeTerrainEx(null, OldField.Xhx, OldField.Yhx, OldField.Lhx, 1, PathOfFrostTerrainChange, PathOfFrostTerrainChanged);
                    }
                }

                if (GetAbilityEnabled(26))
                {
                    ExecuteTrailOfDarkness(OldField);
                }
            }
        }

