        // Unit.PAS:1796
        public virtual bool CanJoin(sbyte Player)
        {
            bool Result;
            Alignment Alignment;
            DiplomaticRelation Relation;
            int I;
            bool condition = FGroup == null;
            if (!condition)
            {
                var behavior = FGroup.GroupClass.Behavior;
                condition = !Set<GroupBehavior>.Of(GroupBehavior.Guard, GroupBehavior.GuardArea).Contains(behavior);
            }

            if (condition)
            {
                if (GetRace() == -1)
                {
                    var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                    Alignment = Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                    if (GetAlignment() != Engine.Alignment.None)
                    {
                        Relation = Aow.Game.Magic.Abilities.AlignmentTables.dAlignmentToDiplomaticRelation(GetAlignment(), Alignment);
                        if (Relation == DiplomaticRelation.Unknown && this is Unit)
                        {
                            Result = false;
                            I = AoWHSMap.Current.FRaces.Count;
                            while (!Result && I != 0)
                            {
                                I -= 1;
                                bool test = Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(I).GetPlayerRelation(Player) >= Status.Polite;
                                if (test)
                                {
                                    var unitResourceIndex = ((Unit)this).FUnitResource.UnitResourceIndex();
                                    test = Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(I).FUnitIndexes.IndexOf(unitResourceIndex) != -1;
                                }

                                Result = test;
                            }
                        }
                        else
                        {
                            Result = Relation == DiplomaticRelation.Peace;
                        }
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    var race = GetRace();
                    Result = Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(race).GetPlayerRelation(Player) >= Status.Polite;
                }

                if (Result && FGroup != null && FGroup.GroupClass.Behavior == GroupBehavior.Hunt && ((HuntAG)FGroup).HuntingPlayer(Player))
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

