        // Unit.PAS:1843
        public virtual bool OfferToJoin(sbyte Player)
        {
            bool Result;
            UnitUserList Group;
            Alignment Alignment;
            if (CanJoin(Player))
            {
                if (GetRace() != -1)
                {
                    var race = GetRace();
                    Result = Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(race).GetPlayerRelation(Player) >= Status.Polite;
                }
                else
                {
                    Group = FGroup;
                    if (Group != null && ((AIGroup)(object)Group).GroupClass.Behavior == GroupBehavior.Refuge)
                    {
                        var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                        Alignment = Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(players.FPlayerRace).GetAlignment();
                        if ((GetAlignment() != Engine.Alignment.None || GetUnitType() == UnitType.Machine) && Aow.Game.Magic.Abilities.AlignmentTables.dAlignmentToDiplomaticRelation(GetAlignment(), Alignment) != DiplomaticRelation.Peace)
                        {
                            Result = false;
                        }
                        else
                        {
                            Result = true;
                        }
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

