        // Unit.PAS:312
        public sbyte UpdateMoraleValue()
        {
            int Player;
            int Value;
            AbstractUnit AUnit;
            Player = FPlayer;
            Value = GetUnitMoraleValue((sbyte)Player, GetIndependentRelation());
            if (!Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting) && GetUnitType() != UnitType.Machine && !(this is Leader) && Owner is Army)
            {
                if (GetUpkeep() != 0 && Player > 0 && !GetAbilityEnabled(155))
                {
                    Value += Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FMoraleValue;
                }

                for (int I = Owner.Count - 1; I >= 0; I--)
                {
                    AUnit = (AbstractUnit)((EChangeNotifyNode)(object)Owner).FChildren.List[I];
                    if (AUnit.GetAbilityEnabled(37) && AUnit != this)
                    {
                        Value += 30;
                    }
                    else
                    {
                        if (Set<Status>.Of(Status.Hostile, Status.Wary).Contains(UnitRelation(AUnit)))
                        {
                            Value -= 10;
                        }
                    }
                }
            }

            if (Value > 125)
            {
                FMoraleValue = 125;
            }
            else
            {
                if (Value < -25)
                {
                    FMoraleValue = -25;
                }
                else
                {
                    FMoraleValue = (sbyte)Value;
                }
            }

            return FMoraleValue;
        }

