        // Unit.PAS:922
        public void CreateMovePointTable(ref FixedArray_Aow_Units_FixedArray_sbyte_16_16 Table)
        {
            Set<MoveType> Moves;
            int Points;
            sbyte Value;
            bool Faster;
            bool Slower;
            Moves = GetMoveTypes();
            if (AoWHSMap.Current.FCombat != null)
            {
                Moves = Moves - Set<MoveType>.Of(MoveType.Tunneling);
            }

            var moveTypesToInt = Aow.Game.Magic.Abilities.MovementTables.MoveTypesToInt(Moves);
            Table = MovementTables.MovePointTables[moveTypesToInt];
            if (FPlayer > 0)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(PlayerEnchantmentType.EnchantedRoads))
                {
                    for (int Terrain = 0; Terrain <= 15; Terrain++)
                    {
                        if (Table[Terrain][4 - -1] != -1)
                        {
                            Table[Terrain][4 - -1] = 2;
                        }
                    }
                }

                if (GetAbilityEnabled(23) || GetAbilityEnabled(1) || GetAbilityEnabled(165))
                {
                    Faster = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.FActiveEnchantments.Contains(PlayerEnchantmentType.AirMastery);
                    Slower = (((byte)Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.FEnemyEnchantments.Image) & 4) != 0;
                    if (Faster && !Slower)
                    {
                        for (int Overlay = -1; Overlay <= 11; Overlay++)
                        {
                            for (int Terrain = 0; Terrain <= 15; Terrain++)
                            {
                                Value = Table[Terrain][Overlay - -1];
                                if (Value > 2)
                                {
                                    Table[Terrain][Overlay - -1] = (sbyte)(int)(((uint)(Value + 1)) >> 1);
                                }
                            }
                        }
                    }
                    else
                    {
                        if (!Faster && Slower)
                        {
                            for (int Overlay = -1; Overlay <= 11; Overlay++)
                            {
                                for (int Terrain = 0; Terrain <= 15; Terrain++)
                                {
                                    if (Table[Terrain][Overlay - -1] >= 1)
                                    {
                                        Table[Terrain][Overlay - -1] = (sbyte)(Table[Terrain][Overlay - -1] * 2);
                                    }
                                }
                            }
                        }
                    }
                }

                if (GetAbilityEnabled(152))
                {
                    for (int Overlay = -1; Overlay <= 11; Overlay++)
                    {
                        for (int Terrain = 0; Terrain <= 15; Terrain++)
                        {
                            Points = Table[Terrain][Overlay - -1];
                            if (Points > 2)
                            {
                                Points -= 1;
                                // { Original retains this redundant lower bound after Points > 2. }
                                if (Points < 2)
                                {
                                    Points = 2;
                                }
                            }

                            Table[Terrain][Overlay - -1] = (sbyte)Points;
                        }
                    }
                }

                if (GetAbilityEnabled(132))
                {
                    for (int Overlay = -1; Overlay <= 11; Overlay++)
                    {
                        for (int Terrain = 0; Terrain <= 15; Terrain++)
                        {
                            Points = Table[Terrain][Overlay - -1];
                            if (Points > 0)
                            {
                                Table[Terrain][Overlay - -1] = (sbyte)(Points + 2);
                            }
                        }
                    }
                }
            }
        }

