            GetMoveTypes();
            var moveTypesToInt = Aow.Game.Magic.Abilities.MovementTables.MoveTypesToInt(GetMoveTypes());
            Cost = MovementTables.MovePointTables[moveTypesToInt][TerrainType][OverlayType - -1];
            if (Cost == -1 || Cost > GetMoves())
