        // Unit.PAS:1454
        public ArmyHS Place(int X, int Y, int L, sbyte Player, Set<UnitPlaceModeElement> Mode)
        {
            HNWalkData Walk = default;
            ArmyHS ArmyHS;
            ArmyHS Result = null;
            Aow.Game.World.Movement.HNWalkData.InitHNWalk(ref Walk, X, Y, 0);
            while (Result == null && (Walk.Radius == 0 || Mode.Contains(UnitPlaceModeElement.ScanArea)) && Walk.Radius < 30)
            {
                if (CanPlace(Walk.X, Walk.Y, L, Player, Mode))
                {
                    ArmyHS = (ArmyHS)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(Walk.X, Walk.Y, L).FindOwnedChild(131607);
                    if (ArmyHS == null)
                    {
                        ArmyHS = new ArmyHS(null);
                        if (Player != -1)
                        {
                            ArmyHS.FArmy.SetPlayer(Player);
                        }

                        if (!ArmyHS.FArmy.AddUnit(this) || !Aow.Game.World.Map.AoWHSMap.Current.PlaceHX(ArmyHS, Walk.X, Walk.Y, L))
                        {
                            ArmyHS?.Dispose();
                            ArmyHS = null;
                        }

                        Result = ArmyHS;
                    }
                    else
                    {
                        if (ArmyHS.FArmy.AddUnit(this))
                        {
                            Result = ArmyHS;
                        }
                        else
                        {
                            Result = null;
                        }
                    }
                }

                if (Result == null)
                {
                    Aow.Game.World.Movement.HNWalkData.WalkToNextHN(ref Walk);
                }
            }

            return Result;
        }

