        private static int P2CompareUnits(object Item1, object Item2)
        {
            int S1;
            int S2;
            var unit = (AbstractUnit)Item1;
            S1 = unit.GetUnitLevel();
            if (unit.GetTransporter())
            {
                S1 += 500;
            }

            if ((AbstractUnit)Item1 is Hero)
            {
                S1 += 50;
                if ((AbstractUnit)Item1 is Leader)
                {
                    S1 += 100;
                }
            }

            var unit2 = (AbstractUnit)Item2;
            S2 = unit2.GetUnitLevel();
            if (unit2.GetTransporter())
            {
                S2 += 500;
            }

            if ((AbstractUnit)Item2 is Hero)
            {
                S2 += 50;
                if ((AbstractUnit)Item2 is Leader)
                {
                    S2 += 100;
                }
            }

            int Result = S2 - S1;
            if (Result == 0)
            {
                if (((AbstractUnit)Item1).FUnitStatus.Contains(UnitStatusElement.Enchanted))
                {
                    S1 = 1;
                }
                else
                {
                    S1 = 0;
                }

                if (((AbstractUnit)Item2).FUnitStatus.Contains(UnitStatusElement.Enchanted))
                {
                    S2 = 1;
                }
                else
                {
                    S2 = 0;
                }

                Result = S2 - S1;
            }

            if (Result == 0)
            {
                Result = ((AbstractUnit)Item2).GetUnitGFXResourceIndex() - ((AbstractUnit)Item1).GetUnitGFXResourceIndex();
                if (Result == 0)
                {
                    Result = ((AbstractUnit)Item2).FUnitID - ((AbstractUnit)Item1).FUnitID;
                }
            }

            return Result;
        }

        private static int P2CompareUnitMoves(object Item1, object Item2) => ((AbstractUnit)Item2).GetMoves() - ((AbstractUnit)Item1).GetMoves();

        internal static sbyte UnitsToIndependentRelation(UnitList Units, sbyte DefaultRelation)
        {
            sbyte Result;
            bool SameRace;
            bool Evil;
            bool Good;
            bool Neutral;
            int I;
            int Race;
            AbstractUnit Unit_;
            Alignment Alignment;
            sbyte Relation;
            Relation = -1;
            SameRace = true;
            I = Units.FChildren.Count;
            while (SameRace && I != 0)
            {
                I -= 1;
                Race = ((AbstractUnit)Units.FChildren.List[I]).GetRace();
                if (Race != -1 && Race != Relation)
                {
                    if (Relation == -1)
                    {
                        Relation = (sbyte)Race;
                    }
                    else
                    {
                        SameRace = false;
                    }
                }
            }

            if (SameRace && Relation == -1)
            {
                Relation = DefaultRelation;
            }

            if (Relation == -1)
            {
                SameRace = false;
            }

            I = Units.FChildren.Count;
            while (SameRace && I != 0)
            {
                I -= 1;
                bool condition = Relation == ((AbstractUnit)Units.FChildren.List[I]).GetRace();
                if (!condition)
                {
                    var alignment = ((AbstractUnit)Units.FChildren.List[I]).GetAlignment();
                    condition = Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(Relation).FAlignments.Contains(alignment);
                }

                SameRace = condition;
            }

            if (!SameRace)
            {
                Evil = true;
                Good = true;
                Neutral = true;
                I = 0;
                int last = Units.FChildren.Count - 1;
                for (; I <= last; I += 1)
                {
                    Unit_ = (AbstractUnit)Units.FChildren.List[I];
                    Alignment = Unit_.GetAlignment();
                    Evil = Evil && Aow.Game.Magic.Abilities.AlignmentTables.alsEvil.Contains(Alignment) && (Unit_.GetRace() == -1 || Set<Alignment>.Of(Engine.Alignment.Evil, Engine.Alignment.PureEvil).Contains(Alignment));
                    Good = Good && Aow.Game.Magic.Abilities.AlignmentTables.alsGood.Contains(Alignment) && (Unit_.GetRace() == -1 || Set<Alignment>.Of(Engine.Alignment.PureGood, Engine.Alignment.Good).Contains(Alignment));
                    Neutral = Neutral && Aow.Game.Magic.Abilities.AlignmentTables.alsNeutral.Contains(Alignment);
                }

                if (Good && !Evil)
                {
                    Result = -2;
                }
                else
                {
                    if (Evil && !Good)
                    {
                        Result = -4;
                    }
                    else
                    {
                        Result = -3;
                    }
                }
            }
            else
            {
                Result = Relation;
            }

            return Result;
        }

