        // Diplomacy.pas:58
        public virtual bool Validate()
        {
            int I;
            AbstractUnit AUnit;
            XYL Location = default;
            bool Result = true;
            I = FUnitIDs.Count;
            while (Result && I != 0)
            {
                I -= 1;
                var item = FUnitIDs[I];
                AUnit = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(item);
                // { Original behavior: missing and dead units do not invalidate the offer. }
                if (AUnit != null && AUnit.FPlayer == 0)
                {
                    AUnit.GetLocation(ref Location.X, ref Location.Y, ref Location.L);
                    Result = FLocation.X == Location.X && FLocation.Y == Location.Y && FLocation.L == Location.L;
                }
            }

            return Result;
        }

        // Diplomacy.pas:80
        public virtual void ListJoinUnits(UnitList Units, ref byte Selection)
        {
            AbstractUnit AUnit;
            for (int I = 0, last = FUnitIDs.Count - 1; I <= last; I++)
            {
                var item = FUnitIDs[I];
                AUnit = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(item);
                Units.AddUnit(AUnit);
            }

            Selection = FSelection;
        }

        // Diplomacy.pas:93
        public virtual bool Accept(ref string ErrorText)
        {
            bool Result;
            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FGems >= FGold)
            {
                Result = true;
            }
            else
            {
                Result = false;
                ErrorText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.P5NotEnoughGoldRStr);
            }

            return Result;
        }

