        // Hero.PAS:1311
        public override void NewTurn(sbyte Player)
        {
            SpellCastEventLog Log;
            base.NewTurn(Player);
            if (Player == FPlayer)
            {
                ValidateHeroUpgrade();
                Player = GetCastingPointsMax();
                FCastingPoints = Player;
                if (FCastingSpellID != 0 && FCastingMana < FCastingProgress)
                {
                    FCastingMana += Player;
                    FCastingPoints = 0;
                    if (FCastingMana > FCastingProgress)
                    {
                        FCastingPoints = (sbyte)(FCastingMana - FCastingProgress);
                        FCastingMana = FCastingProgress;
                    }

                    if (FCastingMana == FCastingProgress)
                    {
                        Log = new SpellCastEventLog(null);
                        Log.FPlayer = FPlayer;
                        Log.FUnitID = FUnitID;
                        Log.FSpellID = FCastingSpellID;
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FEventLogbook.AddEvent(Log);
                        if (AoWHSMap.Current.FSeatedPlayer == FPlayer && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FPlayerType == PlayerType.Human)
                        {
                            Log.Execute(false, ExecuteTrigger.Event, null);
                        }

                        Log.Release();
                    }
                }
            }
        }

