            if (Result && !FRegistered && FUnitID != -1)
            {
                Hero = Aow.Game.World.Map.AoWHSMap.Current.FHeroControl.FindID(FUnitID);
                if (Hero == null || Hero == this)
                {
                    Result = true;
                }
                else
                {
                    if (Hero.Owner == null && CompatibleHero(Hero))
                    {
                        Result = true;
                    }
                    else
                    {
                        Result = false;
                    }
                }
            }

            return Result;
        }

        // Hero.PAS:964
        public override void Activate()
        {
            Hero Hero;
            if (FUnitID != -1)
            {
                Hero = Aow.Game.World.Map.AoWHSMap.Current.FHeroControl.FindID(FUnitID);
                if (Hero != null && Hero != this && Hero.Owner == null && CompatibleHero(Hero))
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FHeroControl.UnRegisterHero(Hero);
                }
            }

            if (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting))
            {
                FLevel = (byte)GetLevel();
            }

            if (FHeroResourceIndex == -1)
            {
                SetHeroResourceIndex(0);
            }

            if (FPlayer > 0 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer) == null && Owner == null)
            {
                FPlayer = -1;
            }

            if (Owner == null && FGroupID != 0)
            {
                FGroupID = 0;
            }

            base.Activate();
            if (AoWHSMap.Current != null)
            {
                if (!FMode.Contains(HeroModeElement.SkipLibraryUpdate) && (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting) || AoWHSMap.Current.FDay == 0))
                {
                    UpdateFromLibrary();
                }

                if (!FRegistered)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FHeroControl.RegisterHero(this);
                }

                if (FPlayer != -1 && Owner != null)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.RegisterPowerSource(FPowerSource);
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FHeroes.AddChild(this);
                }

                FInventory.RegisterItems();
                FHeroItems.RegisterItems();
            }
        }

        // Hero.PAS:993
        public override void Deactivate()
        {
            bool condition = FPlayer != -1;
            if (condition)
            {
                var count = AoWHSMap.Current.FPlayers.Count;
                condition = FPlayer < count;
            }

            if (condition)
            {
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.UnregisterPowerSource(FPowerSource);
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FHeroes.RemoveChild(this);
            }

            base.Deactivate();
        }

        // Hero.PAS:765
        public override bool CanJoin(sbyte Player)
        {
            bool Result;
            Player APlayer;
            if (FRace != -1)
            {
                APlayer = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                var playerRelation = Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(FRace).GetPlayerRelation(Player);
                Result = Set<Status>.Of(Status.Polite, Status.Friendly).Contains(playerRelation);
                if (Result)
                {
                    bool condition = FGroup == null || FGroup.GroupClass.Behavior != GroupBehavior.Refuge;
                    if (condition)
                    {
                        bool test = !GetAbilityEnabled(128) || Player != FDeathPlayer;
                        if (!test)
                        {
                            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                            test = FDeathDay + 2 < players.FDay;
                        }

                        condition = test;
                    }

                    if (condition)
                    {
                        Result = Result && APlayer.FHeroes.Count < APlayer.GetHeroCountMax() && GetLevel() <= APlayer.GetHeroJoinLevelMax();
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:794
        public override bool OfferToJoin(sbyte Player)
        {
            bool Result;
            Player APlayer;
            int Seed;
            int Chance;
            if (CanJoin(Player))
            {
                APlayer = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                if (EmergedToPlayer() == -1)
                {
                    if ((!GetAbilityEnabled(128) || Player != FDeathPlayer) && (FGroup == null || FGroup.GroupClass.Behavior != GroupBehavior.Refuge))
                    {
                        Chance = APlayer.GetHeroJoinChance(GetLevel());
                        Seed = RandSeed;
                        RandSeed = (AoWHSMap.Current.FInitialRandomSeed + AoWHSMap.Current.FDay + FUnitID * 16) & 4088;
                        Result = Random(100) < Chance;
                        RandSeed = Seed;
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = Player == EmergedToPlayer();
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

