        // Hero.PAS:1674
        public virtual void EditDropMsg(ref EMsg Msg)
        {
            MapLevel Level;
            int L;
            int X = default;
            int Y = default;
            int Player;
            bool Placed;
            Level = Msg.Param[0].As<MapLevel>();
            L = Msg.Data[1];
            Aow.Game.World.Map.HexGeometry.HPtoHX(Msg.Payload.Int, Msg.Data[0], ref X, ref Y);
            if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting))
                {
                    Player = ((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(X, Y, L)).GetPlayer();
                    if (Player == -1)
                    {
                        Player = AoWHSMap.Current.FEditorPlayer;
                    }
                }
                else
                {
                    Player = -1;
                }

                Placed = Place(X, Y, L, (sbyte)Player, Set<UnitPlaceModeElement>.Of()) != null;
            }
            else
            {
                Placed = false;
            }

            if (Placed)
            {
                Msg.Result = 0;
            }
            else
            {
                Msg.Result = -1;
            }
        }

