        // Hero.PAS:1579
        public void SetRace(sbyte Value)
        {
            bool Found;
            int Index;
            HeroResource Resource;
            if (FRace != Value)
            {
                Found = false;
                Index = Aow.Game.Engine.AoWHSSet.Current.FHeroResources.GetCount();
                while (!Found && Index != 0)
                {
                    Index -= 1;
                    Resource = Aow.Game.Engine.AoWHSSet.Current.FHeroResources.GetHeroResource(Index);
                    Found = Resource != null && Resource.FRace == Value && GetHeroType() == Resource.FHeroType;
                }

                if (Found)
                {
                    SetHeroResourceIndex(Index);
                }
            }
        }

