        // Hero.PAS:1804
        public bool ExecuteSwapItem(int ItemID1, int ItemID2)
        {
            bool Result;
            Item Item1;
            Item Item2;
            ItemList Owner1;
            ItemList Owner2;
            int Index1;
            int Index2;
            if (CanSwapItem(ItemID1, ItemID2))
            {
                Item1 = Aow.Game.World.Map.AoWHSMap.Current.FItemControl.FindItem(ItemID1);
                Item2 = Aow.Game.World.Map.AoWHSMap.Current.FItemControl.FindItem(ItemID2);
                Owner1 = (ItemList)Item1.Owner;
                Owner2 = (ItemList)Item2.Owner;
                Owner1.BeginUpdate();
                Owner2.BeginUpdate();
                Index1 = Item1.Owner.FindChildIndex(Item1);
                Index2 = Item2.Owner.FindChildIndex(Item2);
                Item1.SetOwner(null);
                Item2.SetOwner(null);
                if (Owner1.GetControlStyle().Contains(EControlStyleElement.ArrayMode))
                {
                    Item2.SetArrayOwner(Owner1, Index1);
                }
                else
                {
                    Item2.SetOwner(Owner1);
                }

                if (Owner2.GetControlStyle().Contains(EControlStyleElement.ArrayMode))
                {
                    Item1.SetArrayOwner(Owner2, Index2);
                }
                else
                {
                    Item1.SetOwner(Owner2);
                }

                Owner2.EndUpdate();
                Owner1.EndUpdate();
                Changed();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:1831
        public bool AutoPlaceItem(Item Item)
        {
            HeroItemPosition Position;
