            else
            {
                Result = true;
            }

            return Result;
        }

        // Hero.PAS:2149
        public bool CanCastSpell(int SpellID, ref string Reason)
        {
            bool Result;
            Spell Spell;
            if (FCastingSpellID == 0)
            {
                Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
                var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                var castingMana = CastingMana(Spell);
                if (players.FMagicControl.FMana >= castingMana || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                {
                    Result = Spell.CanActivate(this, ref Reason);
                }
                else
                {
                    Result = false;
                    Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NotEnoughManaRStr);
                }
            }
            else
            {
                Result = SpellID == FCastingSpellID;
                if (Result && Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID).FSpellType == SpellType.Global && AoWHSMap.Current.FCombatMap != null)
                {
                    Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(CannotCastSpellInCombatRStr);
                    Result = false;
                }
            }

            return Result;
        }

        // Hero.PAS:2176
        public bool CastSpell(int SpellID, ref string Reason)
        {
            bool Result;
            Spell Spell;
            HeroUpdateTE TE;
            if (CanCastSpell(SpellID, ref Reason))
            {
                if (FCastingSpellID == 0)
                {
                    Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
                    if (CastingMana(Spell) <= FCastingPoints || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Result = Spell.CanActivate(this, ref Reason) && Spell.Activate(this);
                    }
                    else
                    {
                        if (!Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).GetBusy())
                        {
                            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                            var castingMana = CastingMana(Spell);
                            if (players.FMagicControl.FMana >= castingMana)
                            {
                                TE = CreateHeroUpdateTE();
                                TE.FMode = HeroUpdateTE.HeroUpdateMode.StartCasting;
                                TE.FItemID = SpellID;
                                Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(FPlayer).AddEvent(TE);
                                TE.Release();
                                Result = true;
                            }
                            else
                            {
                                Result = false;
                                Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NotEnoughManaRStr);
                            }
                        }
                        else
                        {
                            Result = false;
                        }
                    }
                }
                else
                {
                    if (CastingReady())
                    {
                        Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
                        Result = Spell.CanActivate(this, ref Reason) && Spell.Activate(this);
                    }
                    else
                    {
                        Result = true;
                    }
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Hero.PAS:2220
        public bool CanCastCombatSpell(int SpellID, ref string Reason)
        {
            bool Result;
            Spell Spell;
            if (FCastingSpellID == 0)
            {
                Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
                if (CastingMana(Spell) <= FCastingPoints || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                {
                    var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                    var castingMana = CastingMana(Spell);
                    if (players.FMagicControl.FMana >= castingMana || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Result = Spell.CanActivateCombat(this, ref Reason);
                    }
                    else
                    {
                        Result = false;
                        Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NotEnoughManaRStr);
                    }
                }
                else
                {
                    Result = false;
                    Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(NotEnoughChannelingPointsRStr);
                }
            }
            else
            {
                Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
                Result = Set<SpellType>.Of(SpellType.Combat, SpellType.Unit).Contains(Spell.FSpellType) && CanCastSpellInstantly(SpellID, CastingMana(Spell), ref Reason);
            }

            return Result;
        }

        // Hero.PAS:2252
        public bool CastCombatSpell(int SpellID, ref string Reason)
        {
            bool Result;
            Spell Spell;
            Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(SpellID);
            if (CanCastCombatSpell(SpellID, ref Reason))
            {
                Result = Spell.CanActivateCombat(this, ref Reason) && Spell.ActivateCombat(this);
            }
            else
