        {
            MakeDefaultLevelUnit(1);
        }

        // Unit.PAS:2591
        public override sbyte GetAttack() => FAttack;

        // Unit.PAS:2593
        public override sbyte GetDefense() => FDefense;

        // Unit.PAS:2595
