                Result = true;
                Level = AoWHSMap.Current.MapContainer.MapLevels[FL];
                Msg.MsgID = 4363;
                Msg.Result = 0;
                Msg.Param[1] = Player;
                Aow.Game.World.Movement.HNWalkData.InitHNWalk(ref Walk, FX, FY, 0);
