        // Army.PAS:705
        public void UpdateUpkeep()
        {
            byte Upkeep;
            byte Previous;
            int Delta;
            Upkeep = 0;
            for (int I = 0, last = GetCount() - 1; I <= last; I++)
            {
                Upkeep = (byte)(Upkeep + ((AbstractUnit)FChildren.List[I]).GetUpkeep());
            }

            Previous = FUpkeep;
            if (Previous != Upkeep && FStatus.Contains(ArmyStatusElement.Activated))
            {
                Delta = Upkeep - Previous;
                var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep + Delta);
            }

            FUpkeep = Upkeep;
        }

        // Army.PAS:719
        public void ValidateTerrainEx(sbyte TerrainType, sbyte OverlayType, sbyte Player)
        {
            AbstractUnit Transport;
            byte Selection;
            ArmyEventLog Log;
            AbstractUnit AUnit;
            Transport = Transporter(255);
            if (Transport == null || !Transport.ValidTerrain(TerrainType, OverlayType))
            {
                Selection = 0;
                for (int I = GetCount() - 1; I >= 0; I--)
                {
                    Selection = (byte)(Selection << 1);
                    if (!((AbstractUnit)FChildren.List[I]).ValidTerrain(TerrainType, OverlayType))
                    {
                        Selection = (byte)(Selection | 1);
                    }
                }
            }
            else
            {
                Selection = 0;
            }

            if (Selection != 0)
            {
                if (!Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting) && AoWHSMap.Current.FDay != 0)
                {
                    BeginUpdate();
                    Log = new ArmyEventLog(null);
                    Log.FPlayer = Player;
                    if (Set<byte>.WithBounds(0, 255).With(0).With(10).Contains((byte)TerrainType))
                    {
                        Log.FArmyText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsDrownRStr);
                        var unitsDrown = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsDrownRStr);
                        Log.FArmyMessages.Add(unitsDrown);
                        Log.FArmyIcon = 3;
                    }
                    else
                    {
                        switch (TerrainType)
                        {
                            case 9:
                                Log.FArmyText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsBurnedRStr);
                                var unitsBurned = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsBurnedRStr);
                                Log.FArmyMessages.Add(unitsBurned);
                                Log.FArmyIcon = 0;
                                break;
                            default:
                                Log.FArmyText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsCrushedRStr);
                                var aoWETranslateRStr = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(UnitsCrushedRStr);
                                Log.FArmyMessages.Add(aoWETranslateRStr);
                                Log.FArmyIcon = 2;
                                break;
                        }
                    }

                    Log.FArmyView.Setup(this, 255);
                    for (int I = 0, last = GetCount() - 1; I <= last; I++)
                    {
                        AUnit = GetUnit(I);
                        if ((((int)(((uint)Selection) >> I)) & 1) != 0)
                        {
                            var hitPoints = AUnit.GetHitPoints();
                            Log.FDamageValues.Add((byte)hitPoints);
                            Log.FDamageTypes.Add(9);
                            AUnit.SetHitPoints(0);
                        }
                        else
                        {
                            Log.FDamageValues.Add(0);
                            Log.FDamageTypes.Add(9);
                        }
                    }

                    Log.ValidateGameOver();
                    Aow.Game.Events.EventLog.DistributeLocationEventLog(Log, FPlayer, FX, FY, FL, true);
                    Log.Release();
                    EndUpdate();
                }

                Validate();
            }
        }

