        // Army.PAS:790
        public void Validate()
        {
            AbstractUnit AUnit;
            Unit NewUnit;
            Aow.Game.World.Map.AoWHSMap.Current.LockGameOverEvent();
            BeginUpdate();
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (AbstractUnit)FChildren.List[I];
                if (AUnit.GetHitPoints() == 0)
                {
                    if (AUnit.GetAbilityEnabled(107))
                    {
                        NewUnit = new Unit(null);
                        NewUnit.SetUnitResource(Aow.Game.Engine.AoWHSSet.Current.FUnitResources.GetUnitResource(152));
                        AUnit.Killed();
                        AddUnit(NewUnit);
                    }
                    else
                    {
                        AUnit.Killed();
                    }
                }
            }

            EndUpdate();
            Aow.Game.World.Map.AoWHSMap.Current.UnlockGameOverEvent();
        }

        // Army.PAS:812
        public void UpdateFormation()
        {
            int Level;
            int UnitLevel;
            AbstractUnit AUnit;
            string SourceName = "";
            Level = 0;
            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (AbstractUnit)FChildren.List[I];
                AUnit.UpdateMoraleValue();
                if (AUnit.GetAbilityEnabled(46) || AUnit.GetAbilityLevel(46) > 0)
                {
                    ((LeadershipAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(46)).ResetExternalSource(AUnit);
                    UnitLevel = AUnit.GetAbilityLevel(46);
                    if (UnitLevel > Level)
                    {
                        Level = UnitLevel;
                        SourceName = AUnit.GetAbilityOwner(46).GetOwnerName();
                        if (SourceName == Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(ArmyInherentRStr))
                        {
                            SourceName = AUnit.GetName();
                        }
                    }
                }
            }

            if (Level > 0)
            {
                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (AbstractUnit)FChildren.List[I];
                    if (AUnit.GetAbilityLevel(46) < Level)
                    {
                        ((LeadershipAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(46)).SetExternalSource(AUnit, (byte)Level, SourceName);
                    }
                }
            }
        }

        // Army.PAS:841
        public void Update()
        {
            if (UpdateCount == 0 && FStatus.Contains(ArmyStatusElement.Activated))
            {
                LockChanged();
                SortUnits();
                UpdateVisibilityRanges();
                UpdateUnfog();
                UpdateUpkeep();
                UpdateConcealedUnits();
                UpdateConcealment();
                UpdateFormation();
                UpdateIndependentRelation();
                if (Aow.Game.World.Map.AoWHSMap.Current.Status.Contains(HSMapStatusElement.Editting) && FX != -1)
                {
