        // Army.PAS:870
        public void Activate()
        {
            AbstractUnit AUnit;
            Assert(!FStatus.Contains(ArmyStatusElement.Activated), "Army already activated", "Army.PAS", 1171);
            if (FOldAIBehavior == GroupBehavior.None)
            {
                FOldAIBehavior = GetOldAIBehavior();
            }

            for (int I = FChildren.Count - 1; I >= 0; I--)
            {
                AUnit = (AbstractUnit)FChildren.List[I];
                if (!AUnit.FUnitStatus.Contains(UnitStatusElement.Activated))
                {
                    AUnit.Activate();
                }
            }

            FStatus = FStatus + Set<ArmyStatusElement>.Of(ArmyStatusElement.Activated);
            FUpkeep = 0;
            if (FPlayer != -1)
            {
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
            }

            // { Original treats X = 0 as an unset location. }
            if (FX == 0)
            {
                FX = -1;
                FY = -1;
                FL = -1;
            }

            Update();
        }

        // Army.PAS:1186
        public void Deactivate()
        {
            AbstractUnit AUnit;
            if (FStatus.Contains(ArmyStatusElement.Activated))
            {
                if (FUnfogRange != 0)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FogArea(FX, FY, FL, FUnfogRange);
                    FUnfogRange = 0;
                }

                for (int I = FChildren.Count - 1; I >= 0; I--)
                {
                    AUnit = (AbstractUnit)FChildren.List[I];
                    if (AUnit.FUnitStatus.Contains(UnitStatusElement.Activated))
                    {
                        AUnit.Deactivate();
                    }
                }

                if (FPlayer != -1)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                }

                FStatus = FStatus - Set<ArmyStatusElement>.Of(ArmyStatusElement.Activated);
            }
        }

