        // Army.PAS:1298
        public void SetPlayer(sbyte Player)
        {
            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player) == null)
            {
                Player = 0;
            }

            if (Player != FPlayer)
            {
                BeginUpdate();
                if (FStatus.Contains(ArmyStatusElement.Activated))
                {
                    if (FPlayer != -1)
                    {
                        var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep - FUpkeep);
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FArmies.RemoveChild(this);
                    }

                    FPlayer = Player;
                    if (FPlayer != -1)
                    {
                        var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer);
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).SetArmyUpkeep(players.FArmyUpkeep + FUpkeep);
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FArmies.AddChild(this);
                    }

                    for (int I = FChildren.Count - 1; I >= 0; I--)
                    {
                        ((AbstractUnit)FChildren.List[I]).SetPlayer(FPlayer);
                    }

                    if (FX != -1)
                    {
                        Aow.Game.World.Map.AoWHSMap.Current.ScannerIconsChangedRad(FX, FY, FL, 0);
                    }

                    if (FPlayer > 0 && AoWHSMap.Current.FDay > 0)
                    {
                        if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType != PlayerType.Human)
                        {
                            SetBehavior(255, GroupBehavior.Passive);
                        }
                    }

                    UpdateUnfog();
                    UpdateExploration();
                }
                else
                {
                    FPlayer = Player;
                }

                EndUpdate();
            }
        }

