            TransportCount = 0;
            I = 0;
            int last = Units.GetCount() - 1;
            for (; I <= last; I += 1)
            {
                if (Units.GetUnit(I).GetTransporter())
                {
                    TransportCount += 1;
                }
            }

            if (IndexOfTransporter(255) != -1)
            {
                TransportCount += 1;
            }

            if (TransportCount <= 1)
            {
                if (TransportCount == 1)
                {
                    Transport = Transporter(255);
                    if (Transport == null)
                    {
                        I = 0;
                        int limit = Units.GetCount() - 1;
                        for (; I <= limit; I += 1)
                        {
                            if (Units.GetUnit(I).GetTransporter())
                            {
                                Transport = Units.GetUnit(I);
                            }
                        }
                    }

                    if (Units.GetCount() + GetCount() <= Transport.GetTransportCapacity() + 1)
                    {
                        Result = AddUnitsResult.OK;
                    }
                    else
                    {
                        Result = AddUnitsResult.TooManyUnits;
                    }
                }
                else
                {
                    if (Units.GetCount() + GetCount() <= 8)
                    {
                        I = 0;
                        // { Original repeats the list count test before testing each candidate. }
                        if (I != Units.GetCount())
                        {
                            while (I != Units.GetCount() && CanAddUnit(Units.GetUnit(I)))
                            {
                                I += 1;
                            }
                        }

                        if (I != Units.GetCount())
                        {
                            Result = AddUnitsResult.InvalidMoveType;
                        }
                        else
                        {
                            Result = AddUnitsResult.OK;
                        }
                    }
                    else
                    {
                        Result = AddUnitsResult.TooManyUnits;
                    }
                }
            }
            else
            {
                Result = AddUnitsResult.MultipleTransporters;
            }

            return Result;
        }

        // Army.PAS:1782
        public AddUnitsResult CanAddUnitSelection(UnitList Units, byte Selection)
        {
            AddUnitsResult Result;
            DelphiList List;
            int I;
            int TransportCount;
            AbstractUnit Transport;
            List = new DelphiList();
            I = 0;
            int last = Units.GetCount() - 1;
            for (; I <= last; I += 1)
            {
                if ((Selection & 1) != 0)
                {
                    List.Add(Units.GetUnit(I));
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            TransportCount = 0;
            I = 0;
            int limit = List.Count - 1;
            for (; I <= limit; I += 1)
            {
                if (((AbstractUnit)List[I]).GetTransporter())
                {
                    TransportCount += 1;
                }
            }

            if (IndexOfTransporter(255) != -1)
            {
                TransportCount += 1;
            }

            if (TransportCount <= 1)
            {
                if (TransportCount == 1)
                {
                    Transport = Transporter(255);
                    if (Transport == null)
                    {
                        I = 0;
                        int last2 = List.Count - 1;
                        for (; I <= last2; I += 1)
                        {
                            if (((AbstractUnit)List[I]).GetTransporter())
                            {
                                Transport = (AbstractUnit)List[I];
                            }
                        }
                    }

                    var count = GetCount();
                    var transportCapacity = Transport.GetTransportCapacity();
                    if (List.Count + count <= transportCapacity + 1)
                    {
                        Result = AddUnitsResult.OK;
                    }
                    else
                    {
                        Result = AddUnitsResult.TooManyUnits;
                    }
                }
                else
                {
                    var count = GetCount();
                    if (List.Count + count <= 8)
                    {
                        I = 0;
                        while (I != List.Count && CanAddUnit((AbstractUnit)List[I]))
                        {
                            I += 1;
                        }

                        if (I != List.Count)
                        {
                            Result = AddUnitsResult.InvalidMoveType;
                        }
                        else
                        {
                            Result = AddUnitsResult.OK;
                        }
                    }
                    else
                    {
                        Result = AddUnitsResult.TooManyUnits;
                    }
                }
            }
            else
            {
                Result = AddUnitsResult.MultipleTransporters;
            }

            List?.Dispose();
            return Result;
        }

        // Army.PAS:1818
        public AddUnitsResult AddUnitSelection(UnitList Units, byte Selection)
        {
            UnitUserList List;
            AddUnitsResult Result = CanAddUnitSelection(Units, Selection);
            if (Result == AddUnitsResult.OK)
            {
                Units.BeginUpdate();
                List = new UnitUserList(null);
                for (int I = Units.GetCount() - 1; I >= 0; I--)
                {
                    if (((1 << I) & Selection) != 0)
                    {
                        if (!Units.GetUnit(I).GetTransporter())
                        {
                            List.AddUnit(Units.GetUnit(I));
                        }
                        else
                        {
                            AddUnit(Units.GetUnit(I));
                        }
                    }
                }

                for (int I = List.GetCount() - 1; I >= 0; I--)
                {
                    AddUnit(List.GetUnit(I));
                }

                Units.EndUpdate();
                List?.Dispose();
            }

            return Result;
        }

        // Army.PAS:1881
        public AbstractUnit SelectionUnit(byte Selection, int Index)
        {
            int I;
            AbstractUnit Result = null;
            I = 0;
            while (I != FChildren.Count && Result == null)
            {
                if ((Selection & 1) != 0)
                {
                    if (Index == 0)
                    {
                        Result = (AbstractUnit)FChildren.List[I];
                    }

                    Index -= 1;
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
                I += 1;
            }

            return Result;
        }

        // Army.PAS:1919
        public void MakeIndependent(byte Selection, ref ArmyHSList Armies)
        {
            sbyte X;
            sbyte Y;
            sbyte L;
            Army GoodArmy;
            Army EvilArmy;
            DelphiList Races;
            DelphiList Units;
            int Race;
            AbstractUnit AUnit;
            Alignment Alignment;
            ArmyHS ArmyHS;
            ArmyHS PlaceIndependentArmy(sbyte AX, sbyte AY, sbyte AL, Army Army)
            {
                ArmyHS Result;
                try
                {
                    if (Army.GetCount() != 0)
                    {
                        Result = new ArmyHS(null);
                        Result.FArmy.BeginUpdate();
                        Result.FArmy.AddUnits(Army);
                        if (Result.PlaceEx(X, Y, L, Set<ArmyPlaceModeElement>.Of(ArmyPlaceModeElement.Safe, ArmyPlaceModeElement.ScanArea)))
                        {
                            Result.Activate();
                            Result.FArmy.EndUpdate();
                        }
                        else
                        {
                            Result.FArmy.Kill(255);
                            Result?.Dispose();
                            Result = null;
                        }
                    }
                    else
                    {
                        Result = null;
                    }
                }
                catch
                {
                    // { Original suppresses placement failures without releasing a partly built army. }
                    Result = null;
                }

                return Result;
            }

            BeginUpdate();
            GoodArmy = null;
            EvilArmy = null;
            Races = new DelphiList();
            Units = new DelphiList();
            for (int I = 0, last = FChildren.Count - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    Units.Add(FChildren.List[I]);
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            for (int I = Units.Count - 1; I >= 0; I--)
            {
                AUnit = (AbstractUnit)Units.List[I];
                if (AUnit.GetRace() != -1 && !AUnit.GetAbilityEnabled(107))
                {
                    if (AUnit.GetRace() >= Races.Count)
                    {
                        Races.Count = AUnit.GetRace() + 1;
                    }

                    var race = AUnit.GetRace();
                    if (Races.List[race] == null)
                    {
                        var army = new Army(null);
                        var aUnitRace = AUnit.GetRace();
                        Races.List[aUnitRace] = army;
                    }

                    var race2 = AUnit.GetRace();
                    ((UnitList)Races.List[race2]).AddUnit(AUnit);
                    Units.Delete(I);
                }
            }

            for (int I = Units.Count - 1; I >= 0; I--)
            {
                AUnit = (AbstractUnit)Units.List[I];
                Alignment = AUnit.GetAlignment();
                Race = -1;
                for (int J = Races.Count - 1; J >= 0; J--)
                {
                    if (Races.List[J] != null && Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(J).FAlignments.Contains(Alignment))
                    {
                        // { Original chooses the largest compatible race group. }
                        if (Race == -1 || ((ECustomNode)Races.List[Race]).GetCount() <= ((ECustomNode)Races.List[J]).GetCount())
                        {
                            Race = J;
                        }
                    }
                }

                if (Race != -1)
                {
                    ((UnitList)Races.List[Race]).AddUnit(AUnit);
                    Units.Delete(I);
                }
                else
                {
                    if (Aow.Game.Magic.Abilities.AlignmentTables.alsGood.Contains(Alignment) && (!Aow.Game.Magic.Abilities.AlignmentTables.alsEvil.Contains(Alignment) || (GoodArmy != null && EvilArmy == null) || (GoodArmy == null && EvilArmy == null) || GoodArmy != null && EvilArmy != null && GoodArmy.GetCount() >= EvilArmy.GetCount()))
                    {
                        if (GoodArmy == null)
                        {
                            GoodArmy = new Army(null);
                        }

                        GoodArmy.AddUnit(AUnit);
                        Units.Delete(I);
                    }
                    else
                    {
                        if (EvilArmy == null)
                        {
                            EvilArmy = new Army(null);
                        }

                        EvilArmy.AddUnit(AUnit);
                        Units.Delete(I);
                    }
                }
            }

            X = FX;
            Y = FY;
            L = FL;
            EndUpdate();
            for (int I = 0, last = Races.Count - 1; I <= last; I++)
            {
                if (Races.List[I] != null)
                {
                    ArmyHS = PlaceIndependentArmy(X, Y, L, (Army)Races.List[I]);
                    if (Armies != null && ArmyHS != null)
                    {
                        Armies.AddChild(ArmyHS);
                    }

                    ((Army)Races.List[I])?.Dispose();
                    Races.List[I] = null;
                }
            }

            if (GoodArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, GoodArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                GoodArmy?.Dispose();
            }

            if (EvilArmy != null)
            {
                ArmyHS = PlaceIndependentArmy(X, Y, L, EvilArmy);
                if (Armies != null && ArmyHS != null)
                {
                    Armies.AddChild(ArmyHS);
                }

                EvilArmy?.Dispose();
            }

            Units?.Dispose();
            Races?.Dispose();
        }

        // Army.PAS:2029
        public void UpdateIndependentRelation()
        {
            sbyte Race;
            bool Valid;
            bool Evil;
            bool Good;
            bool Neutral;
            int I;
            int UnitRace;
            AbstractUnit AUnit;
            Alignment Alignment;
            if (FPlayer == 0)
            {
                Race = -1;
                Valid = true;
                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    if (!((AbstractUnit)FChildren.List[I]).GetAbilityEnabled(107))
                    {
                        UnitRace = ((AbstractUnit)FChildren.List[I]).GetRace();
                    }
                    else
                    {
                        UnitRace = -1;
                    }

                    if (UnitRace != -1 && UnitRace != Race)
                    {
                        if (Race == -1)
                        {
                            Race = (sbyte)UnitRace;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                if (Valid && Race == -1)
                {
                    if (FX != -1)
                    {
                        Race = FIndependentRelation;
                        FIndependentRelation = -1;
                        FIndependentRelation = (sbyte)((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(FX, FY, FL)).GetIndependentRelation();
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            FIndependentRelation = Race;
                            Race = -1;
                        }
                    }

                    if (Race == -1)
                    {
                        if (FIndependentRelation >= 0)
                        {
                            Race = FIndependentRelation;
                        }
                        else
                        {
                            Valid = false;
                        }
                    }
                }

                I = FChildren.Count;
                while (Valid && I != 0)
                {
                    I -= 1;
                    bool condition = Race == ((AbstractUnit)FChildren.List[I]).GetRace();
                    if (!condition)
                    {
                        var alignment = ((AbstractUnit)FChildren.List[I]).GetAlignment();
                        condition = Aow.Game.Engine.AoWHSSet.Current.FRaceResources.GetRaceResource(Race).FAlignments.Contains(alignment);
                    }

                    Valid = condition;
                }

                if (!Valid)
                {
                    Evil = true;
                    Good = true;
                    Neutral = true;
                    I = 0;
                    int last = FChildren.Count - 1;
                    for (; I <= last; I += 1)
                    {
                        AUnit = (AbstractUnit)FChildren.List[I];
                        Alignment = AUnit.GetAlignment();
                        Evil = Evil && Aow.Game.Magic.Abilities.AlignmentTables.alsEvil.Contains(Alignment) && (AUnit.GetRace() == -1 || Set<Alignment>.Of(Engine.Alignment.Evil, Engine.Alignment.PureEvil).Contains(Alignment));
                        Good = Good && Aow.Game.Magic.Abilities.AlignmentTables.alsGood.Contains(Alignment) && (AUnit.GetRace() == -1 || Set<Alignment>.Of(Engine.Alignment.PureGood, Engine.Alignment.Good).Contains(Alignment));
                        Neutral = Neutral && Aow.Game.Magic.Abilities.AlignmentTables.alsNeutral.Contains(Alignment);
                    }

                    if (Good && !Evil)
                    {
                        FIndependentRelation = -2;
                    }
                    else
                    {
                        if (Evil && !Good)
                        {
                            FIndependentRelation = -4;
                        }
                        else
                        {
                            FIndependentRelation = -3;
                        }
                    }
                }
                else
                {
                    FIndependentRelation = Race;
                }
            }
            else
            {
                FIndependentRelation = -1;
            }
        }

        // Army.PAS:2091
        public void Desert(byte Selection)
        {
            DelphiList Units;
            sbyte Player;
            ArmyHSList Armies;
            int Count;
            int Bit;
            ArmyInfoEventLog Log;
            AbstractUnit AUnit;
            Aow.Game.World.Map.AoWHSMap.Current.LockGameOverEvent();
            Units = new DelphiList();
            Count = SelectionCount(Selection);
            Log = new ArmyInfoEventLog(null);
            Log.FArmyView.Setup(this, 255);
            Log.FSelection = Selection;
            Log.FPlayer = FPlayer;
            Log.FTitle = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertionRStr);
            Log.FTriggers = Set<ExecuteTrigger>.Of(ExecuteTrigger.User);
            if (AoWHSMap.Current.FPlayMode == PlayMode.Turn && Aow.Game.Magic.Abilities.GameTables.AoWEngine.FRegistry.GetClassicWindowPopupEvents().Contains(WindowPopupEvent.Rebellion))
            {
                Log.FTriggers = Log.FTriggers + Set<ExecuteTrigger>.Of(ExecuteTrigger.Event);
                if (AoWHSMap.Current.FRequestCombatType)
                {
                    Log.FTriggers = Log.FTriggers + Set<ExecuteTrigger>.Of(ExecuteTrigger.NewTurn);
                }
            }

            if (AoWHSMap.Current.FPlayMode == PlayMode.Simultaneous && Aow.Game.Magic.Abilities.GameTables.AoWEngine.FRegistry.GetSimultaneousWindowPopupEvents().Contains(WindowPopupEvent.Rebellion))
            {
                Log.FTriggers = Log.FTriggers + Set<ExecuteTrigger>.Of(ExecuteTrigger.Event, ExecuteTrigger.NewTurn);
            }

            Log.FDescription = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(TheLeaderOfThePartyStepsForwardRStr);
            if (Count == 1)
            {
                Log.FText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(OneUnitDesertedRStr);
            }
            else
            {
                Log.FText = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(XUnitsDesertedRStr), [IntToStr(Count)]);
            }

            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FGems == 0 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).GetUpkeep() > Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FIncome)
            {
                if (Count == 1)
                {
                    var desertUnitNoUpkeep = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitNoUpkeepRStr);
                    Log.FMessages.Text = desertUnitNoUpkeep;
                }
                else
                {
                    var desertUnitsNoUpkeep = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitsNoUpkeepRStr);
                    Log.FMessages.Text = desertUnitsNoUpkeep;
                }
            }
            else
            {
                if (ValidateSelection(255) == Selection)
                {
                    if (Count == 1)
                    {
                        var desertUnitLowMorale = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitLowMoraleRStr);
                        Log.FMessages.Text = desertUnitLowMorale;
                    }
                    else
                    {
                        var desertUnitsLowMorale = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitsLowMoraleRStr);
                        Log.FMessages.Text = desertUnitsLowMorale;
                    }
                }
                else
                {
                    if (Count == 1)
                    {
                        var desertUnitLowMoraleSplit = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitLowMoraleSplitRStr);
                        Log.FMessages.Text = desertUnitLowMoraleSplit;
                    }
                    else
                    {
                        var desertUnitsLowMoraleSplit = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DesertUnitsLowMoraleSplitRStr);
                        Log.FMessages.Text = desertUnitsLowMoraleSplit;
                    }
                }
            }

            Aow.Game.Events.EventLog.DistributeLocationEventLog(Log, -1, FX, FY, FL, true);
            Log.Release();
            for (int I = GetCount() - 1; I >= 0; I--)
            {
                Bit = 1 << I;
                if ((Bit & Selection) != 0 && GetUnit(I).GetAbilityEnabled(155))
                {
                    Units.Add(GetUnit(I));
                    Selection = (byte)(Selection & ~(byte)Bit);
                }
            }

            Armies = new ArmyHSList(null);
            Player = FPlayer;
            MakeIndependent(Selection, ref Armies);
            while (Units.Count != 0)
            {
                AUnit = (AbstractUnit)Units[0];
                AUnit.AddRef();
                AUnit.Killed();
                AUnit.SetOwner(null);
                AUnit.Release();
                Units.Delete(0);
            }

            for (int I = 0, last = Armies.GetCount() - 1; I <= last; I++)
            {
                if (Aow.Game.Magic.Abilities.AbilityRules.DiplomaticRelation(0, Armies.GetArmyHS(I).FArmy.FIndependentRelation, Player, 0) == DiplomaticRelation.War)
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, GroupBehavior.Raid);
                }
                else
                {
                    Armies.GetArmyHS(I).FArmy.SetBehavior(255, GroupBehavior.Scout);
                }
            }

            Armies?.Dispose();
            Units?.Dispose();
            Aow.Game.World.Map.AoWHSMap.Current.UnlockGameOverEvent();
        }

        // Army.PAS:2155
        public PartyStatus GetPartyStatus(byte Selection)
        {
            PartyStatus Result;
            int Morale;
            int Count;
            CombatPredictor Predictor;
            int UnitMorale;
            AbstractUnit AUnit;
            Morale = 100;
            Count = 0;
            Predictor = new CombatPredictor();
            for (int I = 0, last = FChildren.Count - 1; I <= last; I++)
            {
                if ((Selection & 1) != 0)
                {
                    AUnit = (AbstractUnit)FChildren.List[I];
                    UnitMorale = AUnit.FMoraleValue;
                    if (AUnit.GetUnitType() != UnitType.Machine)
                    {
                        if (UnitMorale < Morale)
                        {
                            Morale = UnitMorale;
                        }

                        Count += 1;
                    }

                    if (UnitMorale <= 40)
                    {
                        Predictor.AddOpponent(AUnit, 0);
                    }
                    else
                    {
                        Predictor.AddUnit(AUnit);
                    }
                }

                Selection = (byte)(int)(((uint)Selection) >> 1);
            }

            if (Predictor.Execute() == CombatResult.Defeat)
            {
                if (Predictor.GetSuperiority() < 50)
                {
                    Result = PartyStatus.Unruly;
                }
                else
                {
                    Result = PartyStatus.Unrest;
                }
            }
            else
            {
                if (Count == 0 || Morale <= 60)
                {
                    Result = PartyStatus.Stable;
                }
                else
                {
                    if (Morale <= 80)
                    {
                        Result = PartyStatus.Content;
                    }
                    else
                    {
                        Result = PartyStatus.Cheerful;
                    }
                }
            }

            Predictor?.Dispose();
            return Result;
        }

        // Army.PAS:2185
        public void UpdateDesertion()
        {
            PartyStatus Status;
            int Chance;
            byte Selection;
            if (FX != -1 && FPlayer != 0)
            {
                Status = GetPartyStatus(255);
                if (Set<PartyStatus>.Of(PartyStatus.Unruly, PartyStatus.Unrest).Contains(Status))
                {
                    if (Status == PartyStatus.Unrest)
                    {
                        Chance = 10;
                    }
                    else
                    {
                        Chance = 50;
                    }

                    if (Chance > Aow.Game.World.Map.AoWHSMap.Current.Random(100))
                    {
                        Selection = 0;
                        for (int I = FChildren.Count - 1; I >= 0; I--)
                        {
                            Selection = (byte)(Selection << 1);
                            if (((AbstractUnit)FChildren.List[I]).FMoraleValue <= 40)
                            {
                                Selection = (byte)(Selection | 1);
                            }
                        }

                        if (Selection != 0)
                        {
                            Desert(Selection);
                        }
                    }
                }
            }
        }

        // Army.PAS:2208
        public bool ValidateCrusaders()
        {
            int I;
            I = GetCount();
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                if (((AbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                {
                    Result = true;
                }
            }

            if (Result)
            {
                BeginUpdate();
                I = GetCount() - 1;
                for (; I >= 0; I -= 1)
                {
                    if (((AbstractUnit)FChildren.List[I]).GetAbilityEnabled(101))
                    {
                        ((AbstractUnit)FChildren.List[I]).ValidateCrusader();
                    }
                }

                Result = GetCount() != 0;
                EndUpdate();
            }
            else
            {
                Result = true;
            }

            return Result;
        }

        // Army.PAS:2230
        public void NewTurn(sbyte Player)
        {
            if (Player == FPlayer)
            {
                FUserMode = FUserMode - Set<ArmyUserModeElement>.Of(ArmyUserModeElement.TurnDone);
                if (ValidateCrusaders())
                {
                    UpdateDesertion();
                }
            }
        }

        // Army.PAS:2239
        public void NewTurnDone(sbyte Player)
        {
