            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FPlayerType != PlayerType.Human)
                {
                    UpdateGroupBehavior();
                }
            }
        }

        // Army.PAS:2245
        public void NewDay()
        {
            if (AoWHSMap.Current.FDay == 1)
            {
                ResetDestinationPos();
                if (FX != -1 && FPlayer > 0)
                {
                    var visibilityRange = VisibilityRange();
                    Aow.Game.World.Map.AoWHSMap.Current.ExploreArea(FX, FY, FL, FPlayer, visibilityRange);
                    var visibilityRange2 = VisibilityRange();
                    var trueVisionRange = TrueVisionRange();
                    Aow.Game.World.Map.AoWHSMap.Current.UpdatePlayerSeen(FPlayer, FX, FY, FL, visibilityRange2, trueVisionRange);
                }

                InitializeGroupBehavior();
            }
        }

        // Army.PAS:2283
        public bool CanActivate() => true;

        // Army.PAS:2288
        public MoveAction GetMoveAction(sbyte Player)
        {
            MoveAction Result = MoveAction.Normal;
            if (Player != FPlayer)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType == PlayerType.Human)
                {
                    if (!FStatus.Contains(ArmyStatusElement.FullyConcealed))
                    {
                        if (FPlayer == 0 && GetJoinSelection(Player) != 0)
                        {
                            Result = MoveAction.Negotiate;
                        }
                        else
                        {
                            Result = MoveAction.Attack;
                        }
                    }
                }
                else
                {
                    if (FPlayer == 0 && GetJoinSelection(Player) != 0)
                    {
                        Result = MoveAction.Negotiate;
                    }
                    else
                    {
                        Result = MoveAction.Attack;
                    }
                }
            }
            else
            {
                Result = MoveAction.Combine;
            }

            return Result;
        }

        // Army.PAS:2306
        public byte GetCanJoinSelection(sbyte Player)
        {
            byte Result;
            AbstractUnit AUnit;
            if (Player > 0)
            {
                Result = 0;
                for (int I = Count - 1; I >= 0; I--)
                {
                    Result = (byte)(Result << 1);
                    AUnit = (AbstractUnit)FChildren.List[I];
                    if (AUnit.CanJoin(Player))
                    {
                        Result = (byte)(Result | 1);
                    }
                }

                if (IndexOfTransporter(255) != -1)
                {
                    if (Result != ValidateSelection(255))
                    {
                        Result = 0;
                    }
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Army.PAS:2324
        public byte GetJoinSelection(sbyte Player)
        {
            bool WantsJoin;
            int I;
            byte Result = 0;
            if (Player > 0)
            {
                WantsJoin = false;
                I = Count;
                while (!WantsJoin && I != 0)
                {
                    I -= 1;
                    WantsJoin = ((AbstractUnit)FChildren.List[I]).OfferToJoin(Player);
                }

                if (WantsJoin)
                {
                    Result = GetCanJoinSelection(Player);
                }
            }

            return Result;
        }

