        // Army.PAS:2365
        public bool IncommingNegotiateOffer(NegotiateTE Offer)
        {
            bool Result;
            ArmyInfoEventLog Log;
            byte Selection;
            Hero AHero;
            XYLList Locations;
            int I;
            int J;
            int Direction;
            int X = default;
            int Y = default;
            int JoinCount;
            int Side;
            bool Placed;
            if (Offer.FObject == NegotiateObject.Army)
            {
                if (Offer.FResult == NegotiateTE.NegotiateResult.Accept)
                {
                    Selection = GetJoinSelection(Offer.FPlayer);
                    JoinCount = SelectionCount(Selection);
                    if (Offer.FMode.Contains(NegotiateModeElement.PrisonerJoin) || JoinAmount(Offer.FPlayer, Selection) <= Offer.FGold)
                    {
                        BeginUpdate();
                        Offer.FMode = Offer.FMode + Set<NegotiateModeElement>.Of(NegotiateModeElement.MoveOnAccept);
                        Log = new ArmyInfoEventLog(null);
                        Log.FArmyView.Setup(this, Selection);
                        Log.FSelection = 255;
                        Log.FDescription = "";
                        Log.FTitle = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2PartyJoinRStr);
                        Log.FTriggers = Set<ExecuteTrigger>.Of(ExecuteTrigger.User);
                        AHero = Hero(Selection, Set<HeroType>.Of(HeroType.Hero));
                        if (AHero == null)
                        {
                            if (JoinCount == 1)
                            {
                                Log.FText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2OneUnitJoinedRStr);
                                var name = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                                var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2AUnitJoinedTheForcesofYRStr), [name]);
                                Log.FMessages.Text = format;
                            }
                            else
                            {
                                Log.FText = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2XUnitsJoinedRStr), [IntToStr(JoinCount)]);
                                var selectionCount = SelectionCount(Selection);
                                var name = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                                var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2XUnitsJoinedTheForcesofYRStr), [selectionCount, name]);
                                Log.FMessages.Text = format;
                            }
                        }
                        else
                        {
                            Log.FText = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2XJoinedRStr), [AHero.FHeroName]);
                            var name = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Offer.FPlayer).GetName();
                            var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2XJoinedTheForcesOfYRStr), [AHero.FHeroName, name]);
                            Log.FMessages.Text = format;
                        }

                        Aow.Game.Events.EventLog.DistributeLocationEventLog(Log, -1, FX, FY, FL, false);
                        Log.Release();
                        if (ValidateSelection(255) != Selection)
                        {
                            Locations = new XYLList();
                            if (Offer.FArmyHS != null)
                            {
                                var yhx = Offer.FArmyHS.GetYhx();
                                var xhx = Offer.FArmyHS.GetXhx();
                                Direction = Aow.Game.World.Map.HexGeometry.dHXtoHNfast(FX, FY, xhx, yhx);
                                if (Direction > 0 && Direction <= 6)
                                {
                                    Locations.AddXYL(FX, FY, FL);
                                    Side = Direction + 1;
                                    if (Side > 6)
                                    {
                                        Side = 1;
                                    }

                                    // { Original sign extends the wrapped byte coordinates here. }
                                    Aow.Game.World.Map.HexGeometry.CenterHNtoHX((sbyte)Offer.FX, (sbyte)Offer.FY, Side, ref X, ref Y);
                                    Locations.AddXYL((sbyte)X, (sbyte)Y, FL);
                                    Side = Direction - 1;
                                    if (Side == 0)
                                    {
                                        Side = 6;
                                    }

                                    Aow.Game.World.Map.HexGeometry.CenterHNtoHX((sbyte)Offer.FX, (sbyte)Offer.FY, Side, ref X, ref Y);
                                    Locations.AddXYL((sbyte)X, (sbyte)Y, FL);
                                }
                            }

                            J = 0;
                            I = Count;
                            while (I != 0)
                            {
                                I -= 1;
                                if ((Selection & (1 << I)) != 0)
                                {
                                    Placed = false;
                                    while (!Placed && J < Locations.Count)
                                    {
                                        var item = Locations[J];
                                        var locationsItem = Locations[J];
                                        var item2 = Locations[J];
                                        Placed = GetUnit(I).Place(item2.X, locationsItem.Y, item.L, Offer.FPlayer, Set<UnitPlaceModeElement>.Of()) != null;
                                        if (!Placed)
                                        {
                                            J += 1;
                                        }
                                    }

                                    if (!Placed)
                                    {
                                        GetUnit(I).Place(FX, FY, FL, Offer.FPlayer, Set<UnitPlaceModeElement>.Of(UnitPlaceModeElement.ScanArea));
                                    }
                                }
                            }

                            Locations?.Dispose();
                        }
                        else
                        {
                            SetPlayer(Offer.FPlayer);
                        }

                        EndUpdate();
                        Offer.Accept();
                    }
                    else
                    {
                        Offer.FMode = Set<NegotiateModeElement>.Of(NegotiateModeElement.AttackOnReject);
                        Offer.Reject();
                    }
                }
                else
                {
                    if (Offer.FResult == NegotiateTE.NegotiateResult.Reject && !Offer.FMode.Contains(NegotiateModeElement.PrisonerJoin))
                    {
                        Offer.Reject();
                    }
                }

                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Army.PAS:2468
        public void TriggerFireDamage()
        {
            ArmyEventLog Log;
            AbstractUnit AUnit;
            int Damage;
            bool Damaged;
            RandSeed = Aow.Game.World.Map.AoWHSMap.Current.Random(16777215);
            Log = new ArmyEventLog(null);
            Log.FArmyText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2FireDamageRStr);
            Log.FPlayer = GetArmyHS().FArmy.FPlayer;
            var p2FireDamage = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P2FireDamageRStr);
            Log.FArmyMessages.Add(p2FireDamage);
            Log.FArmyIcon = 0;
            var armyHS = GetArmyHS();
            Log.FArmyView.Setup(armyHS.FArmy, 255);
            BeginUpdate();
            Damaged = false;
            for (int I = 0, last = Count - 1; I <= last; I++)
            {
                AUnit = GetUnit(I);
                if (!AUnit.GetImmunityTypes().Contains(DamageType.Fire))
                {
                    Damage = AUnit.ExecuteDamageRole(4, 4, Set<DamageType>.Of(DamageType.Fire));
                    if (Damage > AUnit.GetHitPoints())
                    {
                        Damage = AUnit.GetHitPoints();
                    }

                    if (Damage != 0)
                    {
                        Damaged = true;
                        AUnit.SetHitPoints((sbyte)(AUnit.GetHitPoints() - (sbyte)Damage));
                    }

                    Log.FDamageValues.Add((byte)Damage);
                    Log.FDamageTypes.Add((int)DamageType.Fire);
                }
                else
                {
                    Log.FDamageValues.Add(0);
                    Log.FDamageTypes.Add((int)DamageType.None);
                }
            }

            Log.ValidateGameOver();
            if (Damaged)
            {
                Aow.Game.Events.EventLog.DistributeLocationEventLog(Log, -1, FX, FY, FL, true);
            }

            Log.Release();
            Validate();
            EndUpdate();
        }

        // Army.PAS:2508
        public void RetrieveStormDamageInfo(StormType Storm, int Distance, ref StormDamageInfo Info)
        {
            int Attack;
            int Damage;
            byte Relation;
            int Value = default;
            int Amount = default;
            AbstractUnit AUnit;
            Relation = (byte)(int)Aow.Game.Magic.Abilities.AbilityRules.DiplomaticRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation);
            if (Info.FriendlyRelations.Contains(Relation) || Info.EnemyRelations.Contains(Relation))
            {
                switch (Storm)
                {
                    case StormType.Ice:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case StormType.Lightning:
                        Attack = 8;
                        Damage = 7;
                        break;
                    case StormType.Death:
                        Attack = 7;
                        Damage = 4;
                        break;
                    case StormType.Holy:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case StormType.Fire:
                        Attack = 7;
                        Damage = 5;
                        break;
                    case StormType.Pestilence:
                        Attack = 4;
                        Damage = 3;
                        break;
                    default:
                        Attack = 0;
                        Damage = 0;
                        break;
                }

                for (int I = Count - 1; I >= 0; I--)
                {
                    AUnit = GetUnit(I);
                    if (AUnit.FPlayer != 0 || AUnit.FGroup != null && AUnit.FGroup.GroupClass.Behavior != GroupBehavior.Passive)
                    {
                        AUnit.RetrieveDamageInfo((sbyte)Attack, (sbyte)Damage, Set<DamageType>.Of(StormDamageType[(int)Storm]), ref Value, ref Amount);
                        if (Info.FriendlyRelations.Contains(Relation))
                        {
                            Info.FriendlyDamage += Amount;
                            // { Original assigns the second return to damage. }
                            Info.FriendlyValue += Value;
                        }

                        if (Info.EnemyRelations.Contains(Relation))
                        {
                            Info.EnemyDamage += Amount;
                            Info.EnemyValue += Value;
                        }
                    }
                }
            }
        }

        // Army.PAS:2538
        public void IncommingStorm(StormType Storm, int Distance, sbyte Player)
        {
            ArmyEventLog Log;
            bool Damaged;
            int Damage;
            RandSeed = Aow.Game.World.Map.AoWHSMap.Current.Random(16777215);
            Log = new ArmyEventLog(null);
            Log.FArmyText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameTables.TStormTypeRStr[(int)Storm]);
            Log.FPlayer = Player;
            // { Original appends the storm message. }
            var stormType = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameTables.TStormTypeRStr[(int)Storm]);
            Log.FArmyMessages.Add(stormType);
            Log.FArmyIcon = 2;
            Log.FArmyView.Setup(this, 255);
            BeginUpdate();
            Damaged = false;
            for (int I = 0, last = Count - 1; I <= last; I++)
            {
                Damage = ((AbstractUnit)FChildren.List[I]).ExecuteStormDamage(Storm, Distance);
                if (Damage != 0)
                {
                    Damaged = true;
                }

                Log.FDamageValues.Add((byte)Damage);
                Log.FDamageTypes.Add((byte)(int)StormDamageType[(int)Storm]);
            }

            if (Damaged)
            {
                Log.ValidateGameOver();
                Aow.Game.Events.EventLog.DistributeLocationEventLog(Log, FPlayer, FX, FY, FL, true);
            }

            Log.Release();
            Validate();
            EndUpdate();
        }

        // Army.PAS:2567
        public void UpdateAITarget(in AITargetInfo Info, ref AITargetData Data)
        {
            byte Selection;
            switch (Info.Mode)
            {
                case AITargetMode.Attack:
                case AITargetMode.Raid:
                case AITargetMode.AttackArmies:
                    if (!GetUnitsConcealedForPlayer(255, Info.Player) && Info.Player != FPlayer)
                    {
                        if (FPlayer > 0)
                        {
                            if (Aow.Game.Magic.Abilities.AbilityRules.ValidAttackRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation) || Info.Mode == AITargetMode.Raid)
                            {
                                if (Info.Player != 0 && Leader(255) != null)
                                {
                                    Data.Priority = 300;
                                }
                                else
                                {
                                    if (Info.Player != 0 && Hero(255, Set<HeroType>.Of(HeroType.Hero)) != null)
                                    {
                                        Data.Priority = 100;
                                    }
                                    else
                                    {
                                        Data.Priority = 50;
                                    }
                                }
                            }
                            else
                            {
                                Data.Priority = 0;
                            }
                        }
                        else
                        {
                            if (FPlayer == 0)
                            {
                                Selection = GetJoinSelection(Info.Player);
                                if (Selection != 0)
                                {
                                    var joinAmount = JoinAmount(Info.Player, Selection);
                                    Data.Cost = joinAmount;
                                    Data.TargetType = AITargetType.Negotiate;
                                }
                                else
                                {
                                    if (Aow.Game.Magic.Abilities.AbilityRules.ValidAttackRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation))
                                    {
                                        Data.Priority = 50;
                                    }
                                }
                            }
                        }
                    }

                    break;
                case AITargetMode.GuardArea:
                    if (!GetUnitsConcealedForPlayer(255, Info.Player) && Info.Player != FPlayer)
                    {
                        Data.Priority = 50;
                    }
                    else
                    {
                        Data.Priority = 0;
                    }

                    break;
                case AITargetMode.Hunt:
                    Data.Priority = 10;
                    break;
                case AITargetMode.Recruit:
                    if (Info.Player == FPlayer && (FPlayer != 0 || Aow.Game.Magic.Abilities.AbilityRules.DiplomaticRelation(Info.Player, Info.IndependentRelation, FPlayer, FIndependentRelation) != DiplomaticRelation.War))
                    {
                        Data.Priority = Data.Priority | 1;
                    }

                    break;
            }
        }

        // Army.PAS:2605
        public int AIMovePriority()
        {
            int Result = 0;
            if (Leader(255) != null)
