        public override sbyte MoveFirst(int Direction, bool Instant)
        {
            sbyte[] Result__cell = new sbyte[1];
            ref sbyte Result = ref Result__cell[0];
            MapLevel Level;
            int X = default;
            int Y = default;
            int DX = default;
            int DY = default;
            ImageSequenceAnimation Animation;
            Result = base.MoveFirst(Direction, Instant);
            switch (Aow.Game.Magic.Abilities.GameTables.AoWEngine.FRegistry.GetMovementSpeed())
            {
                case AoWRegistry.MovementSpeed.Normal:
                    FMoveSteps = (sbyte)base.GetMoveSteps();
                    break;
                case AoWRegistry.MovementSpeed.Fast:
                    FMoveSteps = (sbyte)base.GetMoveSteps();
                    if (FMoveSteps > 8)
                    {
                        FMoveSteps = (sbyte)(FMoveSteps - 4);
                    }
                    else
                    {
                        FMoveSteps = 4;
                    }

                    break;
                case AoWRegistry.MovementSpeed.Turbo:
                    FMoveSteps = 2;
                    break;
            }

            if (AoWHSMap.Current.FFPS > 0)
            {
                if (AoWHSMap.Current.FFPS < 15)
                {
                    FMoveSteps = (sbyte)(FMoveSteps / 2);
                }
                else
                {
                    if (AoWHSMap.Current.FFPS < 25)
                    {
                        FMoveSteps = (sbyte)(FMoveSteps - 2);
                    }
                }

                if (FMoveSteps < 2)
                {
                    FMoveSteps = 2;
                }
            }

            if (GetLhx() > 0)
            {
                Level = (MapLevel)Owner.Owner;
                var yhx = GetYhx();
                Aow.Game.World.Map.HexGeometry.CenterHNtoHX(GetXhx(), yhx, Direction, ref X, ref Y);
                if (X >= 0 && Y >= 0 && X < Level.Width && Y < Level.Height)
                {
                    if (Level.GetField(X, Y).TerrainType == 7)
                    {
                        if (Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(42).FImageSequences.GetImageSequence(0) != null)
                        {
                            Animation = new ImageSequenceAnimation(null);
                            Animation.SetImageSequence(Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(42).FImageSequences.GetImageSequence(0));
                            Animation.FAnimationLevel = 27;
                            Aow.Game.World.Map.HexGeometry.HNtoHP(Direction, ref DX, ref DY);
                            Animation.SetXhpOffset(DX / 2);
                            Animation.SetYhpOffset(DY / 2);
                            var lhx = GetLhx();
                            var yhx2 = GetYhx();
                            var xhx = GetXhx();
                            Aow.Game.World.Map.AoWHSMap.Current.PlaceHX(Animation, xhx, yhx2, lhx);
                        }
                    }
                }
            }

            return Result;
        }

