                            {
                                if (FArmy.CanPlace((sbyte)Walk.X, (sbyte)Walk.Y, L))
                                {
                                    MoveTo(Field, 0);
                                    Result = true;
                                }
                            }
                        }
                    }
                }

                Aow.Game.World.Movement.HNWalkData.WalkToNextHN(ref Walk);
            }

            return Result;
        }

        private static readonly string P2ArmyRStr = "Army";

        private static bool ConnectingHX(int X1, int Y1, int X2, int Y2)
        {
            bool Result;
            if (X1 == X2)
            {
                Result = Y1 == Y2 + 1 || Y1 == Y2 - 1;
            }
            else
            {
                if (X1 == X2 - 1 || X1 == X2 + 1)
                {
                    if (!((X1 & 1) != 0))
                    {
                        Result = Y1 == Y2 || Y1 == Y2 + 1;
                    }
                    else
                    {
                        Result = Y1 == Y2 || Y1 == Y2 - 1;
                    }
                }
                else
                {
                    Result = false;
                }
            }

            return Result;
        }

        internal static MoveArmyTE CreateArmyMoveTE(ArmyHS Army, byte Selection, Movepath Path, MoveAction Action, Set<ArmyMoveModeElement> Mode)
        {
            MoveArmyTE Move;
            MoveArmyTE Result = null;
            switch (Action)
            {
                case MoveAction.Normal:
                    Move = new ArmyDefaultMoveTE(null);
                    break;
                case MoveAction.Combine:
                    Move = new ArmyCombineMoveTE(null);
                    break;
                case MoveAction.Attack:
                    Move = new ArmyCombatMoveTE(null);
                    break;
                case MoveAction.Negotiate:
                    Move = new ArmyNegotiateMoveTE(null);
                    break;
                default:
                    Move = null;
                    break;
            }

            if (Move != null)
            {
                if (!Move.Setup(Army, Selection, Path, Mode))
                {
                    Result = null;
                    Move.Release();
                }
                else
                {
                    Result = Move;
                }
            }

            return Result;
        }

        internal static bool MoveArmyEx(ArmyHS Army, byte Selection, Movepath Path, Set<ArmyMoveModeElement> Mode, bool Force)
        {
            int Pos;
            MoveArmyTE Move;
            MoveAction Action;
            bool Moved;
            Moved = false;
            if (Force || !Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Army.FArmy.FPlayer).GetBusy())
            {
                if (Path.Count > 1)
                {
                    Pos = Path.MovePointsToPos(Army.FArmy.MovePoints(Selection));
                    if (Pos == 0)
                    {
                        var item = Path[Pos];
                        var pathItem = Path[Pos];
                        var item2 = Path[Pos];
                        Action = ((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(item2.X, pathItem.Y, item.L)).GetMoveAction(Army.FArmy.FPlayer);
                    }
                    else
                    {
                        Action = MoveAction.Normal;
                    }

                    bool condition = Action == MoveAction.Attack && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Army.FArmy.FPlayer).FPlayerType == PlayerType.Human;
                    if (condition)
                    {
                        var item = Path[0];
                        var pathItem = Path[0];
                        var item2 = Path[0];
                        condition = !Aow.Game.World.Map.AoWHSMap.Current.VisibleForPlayer(item2.X, pathItem.Y, item.L, Army.FArmy.FPlayer);
                    }

                    if (condition)
                    {
                        Action = MoveAction.Normal;
                    }

                    Move = Aow.Game.Draw.ArmyHS.CreateArmyMoveTE(Army, Selection, Path, Action, Mode);
                    if (Move != null)
                    {
                        Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(Army.FArmy.FPlayer).AddEvent(Move);
                        Move.Release();
                        Moved = true;
                    }
                }
            }

            return Moved;
        }

        internal static bool MoveArmy(ArmyHS Army, byte Selection, Movepath Path) => Aow.Game.Draw.ArmyHS.MoveArmyEx(Army, Selection, Path, Set<ArmyMoveModeElement>.Of(ArmyMoveModeElement.SelectEndLocation), false);

        internal static bool MoveArmyXYL(ArmyHS Army, byte Selection, sbyte X, sbyte Y, sbyte L, bool Force)
        {
            bool Result;
            MoveControlSettings Settings;
            Settings = new MoveControlSettings(null);
            var lhx = Army.GetLhx();
            var yhx = Army.GetYhx();
            Settings.SetSourcePos(Army.GetXhx(), yhx, lhx);
            Settings.FPlayer = Army.FArmy.FPlayer;
            Settings.FArmyHS = Army;
            Settings.FSelection = Selection;
            Settings.SetDestinationPos(X, Y, L);
            Army.FArmy.CreateMovePointTable(Selection, Bytes.Of(ref Settings.FMovePointTable));
            Aow.Game.World.Map.AoWHSMap.Current.FMoveControl.ProcessMove(Settings);
            if (Settings.FPath.Count != 0)
            {
                Result = Aow.Game.Draw.ArmyHS.MoveArmyEx(Army, Selection, Settings.FPath, Set<ArmyMoveModeElement>.Of(), Force);
            }
            else
            {
                Result = false;
            }

            Settings.Release();
            return Result;
        }

    }
}

