        }

        // Army.PAS:187
        public bool LeaderKilled()
        {
            int I;
            bool Result = false;
            I = FArmyView.GetCount();
            while (!Result && I != 0)
            {
                I -= 1;
                Result = FArmyView.GetUnit(I) is Leader && FArmyView.GetUnit(I).GetHitPoints() <= FDamageValues[I];
            }

            return Result;
        }

        // Army.PAS:200
        public bool PartyDestroyed()
        {
            int I;
            bool Result = true;
            I = FArmyView.GetCount();
            while (Result && I != 0)
            {
                I -= 1;
                Result = Result && FArmyView.GetUnit(I).GetHitPoints() <= FDamageValues[I];
            }

            return Result;
        }

        // Army.PAS:212
        public void ValidateGameOver()
        {
            FGameOver = LeaderKilled() || PartyDestroyed() && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FArmyView.FPlayer).FArmies.GetCount() == 1;
        }

    }

