            if (Terrain == 5)
            {
                Index = Size + 60 - 1;
            }
            else
            {
                Index = Terrain * 10 + 70 + (Size - 1);
            }

            if (FImageLibrary.ImageExist(Index))
            {
                Result = FImageLibrary[Index];
            }
            else
            {
                Result = null;
            }

            if (Result == null)
            {
                if (Level == 0)
                {
                    Index = Size + 50 - 1;
                }
                else
                {
                    Index = Size + 60 - 1;
                }

                if (FImageLibrary.ImageExist(Index))
