        // Structur.PAS:1862
        public virtual bool Raze(sbyte Player)
        {
            bool Result = default;
            string Reason = "";
            RazeStructureEventLog Log;
            if (CanRaze(Player, ref Reason) && !Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).GetBusy())
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType == PlayerType.Human)
                {
                    Log = new RazeStructureEventLog(null);
                    Log.FStructure = this;
                    Log.FButtons = MessageEventLog.Buttons.YesNo;
                    Log.FTitle = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.WarningRStr);
                    var razeStructureWarning = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(RazeStructureWarningRStr);
                    Log.FMessage.Add(razeStructureWarning);
                    var aoWETranslateRStr = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(DoYouWishToContinueRStr);
                    Log.FMessage.Add(aoWETranslateRStr);
                    Log.Execute(true, ExecuteTrigger.User, null);
                    Log.Release();
                    Result = true;
                }
                else
                {
                    Result = RazeEx(Player);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:1708
        public virtual bool CanRaze(sbyte Player, ref string Reason)
        {
            bool Result;
            CombatPredictor Predictor;
            UnitList Defenders;
            UnitList Units;
            if (!GetRazed() && GetRazeable())
            {
                Predictor = new CombatPredictor();
                Defenders = new UnitList(null);
                Units = new UnitUserList(null);
                ListUnits(Units);
                for (int I = 0, last = Units.Count - 1; I <= last; I++)
                {
                    if (Units.GetUnit(I).FPlayer == Player)
                    {
                        Predictor.AddUnit(Units.GetUnit(I));
                    }
                }

                Units?.Dispose();
                GenerateRazeDefenders(Player, Defenders);
                for (int I = 0, last = Defenders.Count - 1; I <= last; I++)
                {
                    Predictor.AddOpponent(Defenders.GetUnit(I), 0);
                }

                Predictor.Execute();
                Result = Set<byte>.WithBounds(0, 255).With(3).With(4).With(6).Contains(Predictor.FResult) && Predictor.GetSuperiority() > 50;
                if (!Result)
                {
                    Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(NotEnoughForcesRStr);
                }

                Defenders?.Dispose();
                Predictor?.Dispose();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

