        // Structur.PAS:2249
        public virtual void UpdateUnfog()
        {
            int Range;
            int X = default;
            int Y = default;
            if (!FStatus.Contains(MapObjectStatusElement.PlacedOnMap))
            {
                return;
            }

            if (FStatus.Contains(MapObjectStatusElement.Activated) && FPlayer != -1 && AoWHSMap.Current.FSeatedPlayer != -1 && (AoWHSMap.Current.FSeatedPlayer == FPlayer || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation(AoWHSMap.Current.FSeatedPlayer) == DiplomaticRelation.Alliance))
            {
                Range = VisibilityRange();
            }
            else
            {
                Range = 0;
            }

            if (Range != FUnfogRange)
            {
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            Aow.Game.World.Map.HexGeometry.CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                            Aow.Game.World.Map.AoWHSMap.Current.FogArea(X, Y, ((MapField)Owner).Lhx, FUnfogRange);
                        }
                    }
                }

                FUnfogRange = (byte)Range;
                if (FUnfogRange != 0)
                {
                    for (int I = 0, last = FResource.TerrainList.Count - 1; I <= last; I++)
                    {
                        if (FResource.TerrainList.Terrain[I] >= 0)
                        {
                            Aow.Game.World.Map.HexGeometry.CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                            Aow.Game.World.Map.AoWHSMap.Current.UnFogArea(X, Y, ((MapField)Owner).Lhx, FUnfogRange);
                        }
                    }
                }
            }
        }

