        public virtual void UpdateExploration()
        {
            int X = default;
            int Y = default;
            if (FStatus.Contains(MapObjectStatusElement.PlacedOnMap) && FPlayer > 0)
            {
                for (int Player = 1, last = AoWHSMap.Current.FPlayers.Count - 1; Player <= last; Player++)
                {
                    if (Player == FPlayer || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FDiplomaticRelations.GetDiplomaticRelation((sbyte)Player) == DiplomaticRelation.Alliance)
                    {
                        for (int I = 0, lastI = FResource.TerrainList.Count - 1; I <= lastI; I++)
                        {
                            if (FResource.TerrainList.Terrain[I] >= 0)
                            {
                                Aow.Game.World.Map.HexGeometry.CenterHNtoHX(FXhx, FYhx, I, ref X, ref Y);
                                var visibilityRange = VisibilityRange();
                                Aow.Game.World.Map.AoWHSMap.Current.ExploreArea(X, Y, ((MapField)Owner).Lhx, (sbyte)Player, visibilityRange);
                            }
                        }
                    }
                }
            }
        }

