                }

                Update();
            }
        }

        // Structur.PAS:2002
        public void RegisterVictoryLocations()
        {
            for (int I = 1, last = FVictoryLocations.Count - 1; I <= last; I++)
            {
                if (FVictoryLocations[I])
                {
                    if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I) != null)
                    {
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).RegisterVictoryLocation(this);
                    }
                    else
                    {
                        FVictoryLocations[I] = false;
                    }
                }
            }
        }

        // Structur.PAS:2013
