        {
            for (int I = 1, last = FVictoryLocations.Count - 1; I <= last; I++)
            {
                if (FVictoryLocations[I] && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I) != null)
                {
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).UnregisterVictoryLocation(this);
                }
            }
        }

