    // { Interface declaration run owned by P5. }
    // pad resources, terrain types
    public partial class PadControl : EControlStyleObject
    {
        public DelphiList FPadResources;
        public BitList FTerrainTypes;

        // MoveT.PAS:3622
        public override void Dispose()
        {
            FTerrainTypes?.Dispose();
            FPadResources?.Dispose();
            base.Dispose();
        }

        // MoveT.PAS:3614
        public PadControl(ECustomNode owner) : base(owner)
        {
            FTerrainTypes = new BitList();
            FPadResources = new DelphiList();
            SetControlStyle(Set<EControlStyleElement>.Of(EControlStyleElement.FixedChild));
        }

        // MoveT.PAS:3629
        public MapObjectResource GetPadResource(int Size)
        {
            MapObjectResource Result;
            if (Size < FPadResources.Count)
            {
                Result = (MapObjectResource)FPadResources.List[Size];
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // MoveT.PAS:3635
        public void SetPadResource(int Size, MapObjectResource Resource)
        {
            while (FPadResources.Count <= Size)
            {
                FPadResources.Add(null);
            }

            FPadResources.List[Size] = Resource;
        }

        // MoveT.PAS:3641
        public void RegisterPadResource(MapObjectResource Resource, int Size)
        {
            if (GetPadResource(Size) == null)
            {
                SetPadResource(Size, Resource);
            }
        }

        // MoveT.PAS:3646
        public void UnregisterPadResource(MapObjectResource Resource, int Size)
        {
            if (Resource == GetPadResource(Size))
            {
                SetPadResource(Size, null);
            }
        }

        // MoveT.PAS:3651
        public bool CanPlacePad(sbyte X, sbyte Y, sbyte L, int Size)
        {
            bool Result;
            MapObjectResource Resource;
            ILTerrainMO Pad;
            Resource = GetPadResource(Size);
            if (Resource != null)
            {
                Pad = (ILTerrainMO)Resource.CreateResourceUser();
                Result = Pad.CanPlace(AoWHSMap.Current.MapContainer, X, Y, L);
                Pad?.Dispose();
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // MoveT.PAS:3666
        public ILTerrainMO PlacePad(sbyte X, sbyte Y, sbyte L, int Size)
        {
            ILTerrainMO Result;
            MapObjectResource Resource;
            Resource = GetPadResource(Size);
            if (Resource != null)
            {
                Result = (ILTerrainMO)Resource.PlaceResourceUser(AoWHSMap.Current, X, Y, L);
            }
            else
            {
                Result = null;
            }

            return Result;
        }
    }

    // { Interface declaration run owned by P1. }
    // race resources, flag library
    public partial class FlagControl : EControlStyleObject
    {

        public RaceResourceList FRaceResources;
        public CustomImageLibrary FFlags;

        // PlayerC.PAS:1920
        public override void Dispose()
        {
            Aow.Game.Engine.AoWHSSet.Current.ImageLibraryManager.ReleaseIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), "Flags.ILB");
            FFlags = null;
            base.Dispose();
        }

        // PlayerC.PAS:1909
        private protected FlagControl(ConstructionContext context, ECustomNode owner) : base(context, owner)
        {
            var gameSet = (AoWHSSet)owner;
            FFlags = gameSet.ImageLibraryManager.LinkToIL(Set<ILManagerCategoryElement>.Of(ILManagerCategoryElement.Disk), "Flags.ILB");
            this.FRaceResources = gameSet.FRaceResources;

            SetControlStyle(Set<EControlStyleElement>.Of(EControlStyleElement.FixedChild));
        }

        // PlayerC.PAS:1927
        public void ShowFlag(int X, int Y, int FrameOffset, byte FlagID, in SurfaceDesc SurfaceDesc)
        {
            FFlags[4].Show(X, Y, SurfaceDesc);
            FrameOffset = (int)(((uint)FrameOffset) >> 2) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 22].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset + 12].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1937
        public void ShowFlagEx(int X, int Y, int FrameOffset, byte FlagID, in SurfaceDesc SurfaceDesc, bool ShowBase)
        {
            if (ShowBase)
            {
                FFlags[4].Show(X, Y, SurfaceDesc);
            }

            FrameOffset = (int)(((uint)FrameOffset) >> 2) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 22].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset + 12].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1947
        public void ShowStructureFlag(int X, int Y, int FrameOffset, byte FlagID, in SurfaceDesc SurfaceDesc)
        {
            FFlags[(int)(((uint)FlagID) >> 6)].Show(X, Y, SurfaceDesc);
            FrameOffset = (int)(((uint)FrameOffset) >> 1) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 10].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1957
        public void ShowStructureFlagEx(int X, int Y, int FrameOffset, byte FlagID, in SurfaceDesc SurfaceDesc, bool ShowBase)
        {
            if (ShowBase)
            {
                FFlags[(int)(((uint)FlagID) >> 6)].Show(X, Y, SurfaceDesc);
            }

            FrameOffset = (int)(((uint)FrameOffset) >> 1) % 12;
            if ((FlagID & 32) != 0)
            {
                FFlags[FrameOffset + 10].Show(X - 21, Y - 16, SurfaceDesc);
            }
            else
            {
                FRaceResources.GetRaceResource(FlagID & 31).FImageLibrary[FrameOffset].Show(X - 21, Y - 16, SurfaceDesc);
            }
        }

        // PlayerC.PAS:1909
        public static FlagControl Create(ECustomNode owner) =>
            ConstructionContext.Create(owner, static (context, owner) => new FlagControl(context, owner ?? throw new NullReferenceException()));
    }
