        public AbilityControl FAbilityControl;
        public SpellControl FSpellControl;
        public MapObjectResourceList FCombatResources;
        public HexagonControl FCombatHexagons;
        public RoadControl FCombatRoads;
        public ImageSequenceList FImageSequences;
        public TextControl FTextControl;
        public int FHSSCRC;

        // Ability.PAS:74
        public override void Dispose()
        {
            FFireControl?.Dispose();
            FImageSequences?.Dispose();
            FTextControl?.Dispose();
            FAbilityControl.UnregisterAll();
            FSpellControl.UnregisterAll();
            FItemLibraries?.Dispose();
            FHeroLibraries?.Dispose();
            base.Dispose();
            FAbilityControl?.Dispose();
            FSpellControl?.Dispose();
        }

        // Ability.PAS:131
        public override void ReadWrite(EStorageStream Stream)
        {
            string Path = "";
            bool Loaded = default;
            if (Stream.StorageMode().Contains(StorageModeElement.Read))
            {
                Stream.ShowProgress(this, Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(LoadingGamePackRStr), 0);
            }

            base.ReadWrite(Stream);
            Stream.rwEObject(FRaceResources, 10);
            Stream.rwEObject(FItemLibraries, 11);
            if (!Stream.StorageMode().Contains(StorageModeElement.TextOnly))
            {
                Path = ExtractFilePath(GameTables.AoWEngine.HSSFileName);
                if (Stream.StorageMode().Contains(StorageModeElement.Read))
                {
                    Loaded = Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "ABILITY.PFS", FAbilityControl, null);
                    Stream.ShowProgress(this, Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(LoadingUnitsRStr), 70);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "UNITRES.PFS", FUnitResources, null);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "UNITGFX.PFS", FUnitGFXResources, null);
                    Stream.ShowProgress(this, Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(LoadingHeroesRStr), 80);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "HERORES.PFS", FHeroResources, null);
                    Stream.ShowProgress(this, Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(LoadingItemsRStr), 90);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "ITEMGFX.PFS", FItemGFXResources, null);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "FACERES.PFS", FFaceResources, null);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "COMB_RES.PFS", FCombatResources, null);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "SPELLS.PFS", FSpellControl, null);
                    Loaded = Loaded && Aow.Game.Magic.Abilities.GameTables.AoWEngine.ReadFromFileCRC(Path + "TEXT.PFS", FTextControl, null);
                    if (!Loaded)
                    {
                        throw new InvalidOperationException("CRC-CHECK FAILED");
                    }

                    Stream.ShowProgress(this, Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GamePackLoadedRStr), 100);
                }
                else
                {
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "ABILITY.PFS", FAbilityControl, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "UNITRES.PFS", FUnitResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "UNITGFX.PFS", FUnitGFXResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "HERORES.PFS", FHeroResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "ITEMGFX.PFS", FItemGFXResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "FACERES.PFS", FFaceResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "COMB_RES.PFS", FCombatResources, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "SPELLS.PFS", FSpellControl, null);
                    Aow.Game.Magic.Abilities.GameTables.AoWEngine.WriteToFileCRC(Path + "TEXT.PFS", FTextControl, null);
                }
            }
            else
            {
                Stream.rwEObject(FUnitResources, 111);
                Stream.rwEObject(FUnitGFXResources, 112);
                Stream.rwEObject(FHeroResources, 113);
                Stream.rwEObject(FItemGFXResources, 114);
                Stream.rwEObject(FFaceResources, 115);
                Stream.rwEObject(FSpellControl, 117);
                Stream.rwEObject(FAbilityControl, 118);
                Stream.rwEObject(FTextControl, 119);
            }

            Stream.rwEObject(FHeroLibraries, 17);
            Stream.rwStreamProc(18, FImageSequences.LoadFromStream, FImageSequences.SaveToStream);
            if (Stream.StorageMode().Contains(StorageModeElement.Read))
            {
                FImageSequences.LinkToIL();
                FHSSCRC = RetrieveHSSCRC();
            }
        }

        // Ability.PAS:194
        public override void MainReadWrite(EStorageStream Stream)
        {
            string DictionaryFile;
