        // Structur.PAS:3627
        public void NewTurnDone()
        {
            HNWalkData Walk = default;
            MapLevel MapLevel;
            int Chance;
            Fire Fire;
            if (FAge > 0)
            {
                MapLevel = (MapLevel)Owner.Owner;
                var yhx = GetYhx();
                var xhx = GetXhx();
                Aow.Game.World.Movement.HNWalkData.InitHNWalk(ref Walk, xhx, yhx, 1);
                while (Walk.Radius == 1)
                {
                    // { Original excludes the top row when spreading fire. }
                    if (Walk.X >= 0 && Walk.X < MapLevel.Width && Walk.Y > 0 && Walk.Y < MapLevel.Height)
                    {
                        Chance = Aow.Game.World.Map.AoWMapField.IgnitionChance((AoWMapField)MapLevel.GetField(Walk.X, Walk.Y));
                        if (Chance > Aow.Game.World.Map.AoWHSMap.Current.Random(1000))
                        {
                            RandSeed = Aow.Game.World.Map.AoWHSMap.Current.Random(16777215);
                            var lhx = GetLhx();
                            Fire = Aow.Game.Engine.AoWHSSet.Current.FFireControl.PlaceFire(Walk.X, Walk.Y, lhx, FireType.Large);
                            if (Fire != null)
                            {
                                Fire.FPlayer = FPlayer;
                                Fire.FTurnsLeft = 3;
                            }
                        }
                    }

                    Aow.Game.World.Movement.HNWalkData.WalkToNextHN(ref Walk);
                }
            }

            if (FTurnsLeft != 0)
            {
                FTurnsLeft = (sbyte)(FTurnsLeft - 1);
                if (FTurnsLeft != 0)
                {
                    TriggerDamage();
                }
                else
                {
                    Dispose();
                }
            }
            else
            {
                TriggerDamage();
            }
        }

