                if (Source.GetSide() == CombatSideIndex.Defender)
                {
                    Result = WallSituation.Source;
                }
                else
                {
                    Result = WallSituation.Target;
                }
            }
            else
            {
                Result = WallSituation.None;
            }

            return Result;
        }

