            {
                Obj = FCombatData.GetObjects(I);
                Result = Obj.FCombatPlayer != -1 && FCombatData.FPlayers.GetPlayers(Obj.FCombatPlayer).FSideIndex == 1 && !Obj.FStatus.Contains(CombatObjectStatusElement.Destroyed);
                I += 1;
            }

            return Result;
        }

