            Assert(FStatus.Contains(AIExecuterStatusElement.TokenLocked), "", "AI.pas", 947);
            FStatus = FStatus - Set<AIExecuterStatusElement>.Of(AIExecuterStatusElement.TokenLocked);
            Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.TokenExecuter.Unlock();
        }

        // AI.pas:952
        public void Process()
        {
            bool Done;
            int I;
            int Index;
            if (FStatus.Contains(AIExecuterStatusElement.Enabled) && FLockCount == 0)
            {
                FStatus = FStatus + Set<AIExecuterStatusElement>.Of(AIExecuterStatusElement.Executing);
                Aow.Game.World.Map.AoWHSMap.Current.SynchroniseBegin();
                FProcessTimeUsed = 0;
                if (FProcessTimeMode == ProcessTimeMode.Dynamic)
                {
                    FProcessStarted = Aow.Game.Draw.PixelFormats.GetElapsedMilliSeconds();
                }
                else
                {
                    FProcessStarted = 0;
                }

                try
                {
                    switch (AoWHSMap.Current.FPlayMode)
                    {
                        case PlayMode.Turn:
                            if (!Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).GetBusy() && Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.PlayerReady(FPlayer))
                            {
                                FProcessCycles += 1;
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FAIControl.Process(this, FTokenControlDone);
                                FTokenControlDone = false;
                            }

                            break;
                        case PlayMode.Simultaneous:
                            if (FStatus.Contains(AIExecuterStatusElement.TokenLocked))
                            {
                                FProcessCycles += 1;
                                Done = false;
                                I = 0;
                                while (!Done && GetProcessTimeLeft() > 0 && FStatus.Contains(AIExecuterStatusElement.Enabled) && I < FPlayers.Count)
                                {
                                    Done = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FAIControl.Process(this, FTokenControlDone);
                                    if (Done)
                                    {
                                        FPlayerProcessCycles += 1;
                                        I = 0;
                                    }
                                    else
                                    {
                                        I += 1;
                                    }

                                    FTokenControlDone = false;
                                    if (!Done || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FPlayer).FAIControl.GetProcessCyclesMax() <= FPlayerProcessCycles)
                                    {
                                        Index = FPlayers.IndexOf((byte)FPlayer);
                                        Index += 1;
                                        FPlayerProcessCycles = 0;
                                        // { Original behavior: Index = Count is not wrapped here. }
                                        if (Index > FPlayers.Count)
                                        {
                                            Index = 0;
                                        }

                                        FPlayer = (sbyte)FPlayers[Index];
                                    }
                                }

                                FTokenCycle += 1;
                                if (I >= FPlayers.Count || FTokenCycle >= FTokenCycles)
                                {
                                    TokenCyclesCaptured();
                                }
                            }

                            break;
                    }
                }
                catch
                {
                    ShowMessage("AI ERROR");
                }

                Aow.Game.World.Map.AoWHSMap.Current.SynchroniseEnd();
                FStatus = FStatus - Set<AIExecuterStatusElement>.Of(AIExecuterStatusElement.Executing);
            }
        }

        public enum ProcessTimeMode : byte
        {
            Static = 0, Dynamic = 1
        }

        // intf_P5_06.inc:108

    }
}

