        // AIGroup.pas:4191
        public void Cancel()
        {
            if (FStatus == AIMoveControlStatus.Processing)
            {
                ProcessingDone(AIMoveControlStatus.Canceled);
            }
        }

        // AIGroup.pas:4196
        public void Reset()
        {
            Cancel();
            Clear();
        }

        // AIGroup.pas:4202
        public bool Process()
        {
            if (FStatus == AIMoveControlStatus.Processing)
            {
                FProcessCycles += 1;
                switch (FMode)
                {
                    case Mode.CanMove:
                        ProcessCanMove();
                        break;
                    case Mode.TransporterCanMove:
                        ProcessTransporterCanMove();
                        break;
                }
            }

            return FStatus == AIMoveControlStatus.Processing;
