                if (FUnits.GetUnits(I).FStatus != AIMoveExecuterUnitStatus.Lost)
                {
                    var units = FUnits.GetUnits(I);
                    FUnits.GetUnits(I).FUnit.FUnitStatus = units.FUnit.FUnitStatus + Set<UnitStatusElement>.Of(UnitStatusElement.MoveDone);
                }
