            FDayMana = FRequiredMana - FMana;
            if (FDays != 0)
            {
                if (FDays > 1)
                {
                    FDays -= 1;
                }

                FDayGold = Round((double)FDayGold / FDays);
                FDayMana = Round((double)FDayMana / FDays);
            }
            else
            {
                if (FDayGoldMax < FDayGold)
                {
                    FDayGold = FDayGoldMax;
                }

                if (FDayManaMax < FDayMana)
                {
                    FDayMana = FDayManaMax;
                }
            }
        }

