                Aow.Game.Magic.Abilities.GameTables.AoWEngine.OutputDebugMessage(AbilityRules.TMPDID, "RETURNING FROM BUDGETS (GOLD:" + IntToStr(Gold) + "/MANA:" + IntToStr(Mana) + ")");
                ReturnFromBudgets(Gold, Mana);
            }
        }

