                    I = FGroup.Count - 1;
                    for (; I >= 0; I -= 1)
                    {
                        FGroup.GetUnit(I).GetLocation(ref UnitX, ref UnitY, ref UnitL);
                        if (X == UnitX && Y == UnitY && L == UnitL)
