        // AIGroup.pas:3067
        public bool TargetOverlapFound(AIGroupControlTarget Target, AIGroup IgnoreGroup)
        {
            Player Player;
            int I;
            AIGroup Group;
            Player = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = false;
            while (I != 0 && !Result)
            {
                I -= 1;
                Group = Player.FAIGroups.GetGroups(I);
                Result = Group != IgnoreGroup && Group.FTargetType == AIGroupTargetStatus.Execute && Target.FLocation.L == Group.FTargetXYL.L && Aow.Game.World.Map.HexGeometry.dHXtoRad(Group.FTargetXYL.X, Group.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1;
            }

