        // AIGroup.pas:3088
        public bool ValidateTargetOverlap(AIGroup Group, AIGroupControlTarget Target)
        {
            int I;
            int Moves;
            int Points;
            int OtherDays;
            int Days;
            Player Player;
            AIGroup Other;
            Player = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FGroupControl.FGroup.FPlayer);
            I = Player.FAIGroups.Count;
            bool Result = true;
            while (I != 0 && Result)
            {
                I -= 1;
                Other = Player.FAIGroups.GetGroups(I);
                if (Other != Group && Other.FTargetType == AIGroupTargetStatus.Execute && Other.FTargetXYL.L == Target.FLocation.L && Aow.Game.World.Map.HexGeometry.dHXtoRad(Other.FTargetXYL.X, Other.FTargetXYL.Y, Target.FLocation.X, Target.FLocation.Y) <= 1)
                {
                    Moves = Other.GetMovesMin();
                    Points = Other.FTargetMovePoints;
                    if (!Other.FStatus.Contains(AIGroupStatusElement.Done))
                    {
                        Points -= Other.GetMovePointsMin();
                    }

                    OtherDays = Points / Moves;
                    if (Points % Moves != 0)
                    {
                        OtherDays += 1;
                    }

                    Moves = Group.GetMovesMin();
                    var movePointsMin = Group.GetMovePointsMin();
                    Points = Target.FMovePoints - movePointsMin;
                    if (Points > 0)
                    {
                        Days = Points / Moves;
                        if (Points % Moves != 0)
                        {
                            Days += 1;
                        }
                    }
                    else
                    {
                        Days = 0;
                    }

                    Result = Days + 1 <= OtherDays;
                }
            }

            return Result;
        }

