            bool Result = base.Validate();
            return Result && ((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(FTargetX, FTargetY, FTargetL)).GetMoveAction(FArmyHS.FArmy.FPlayer) == MoveAction.Negotiate;
        }

