                    if (GetMapF(FPath[0]).GetMoveAction(FArmyHS.FArmy.FPlayer) == MoveAction.Negotiate)
                    {
                        Result = FArmyHS.GetMoveStatus() < 50;
                    }
                    else
                    {
                        Result = FArmyHS.GetMoveStatus() < 100;
                    }
                }
                else
                {
                    Result = false;
                }
