                Position = FPosition;
                if ((Position & 15) > 7 || (int)(((uint)Position) >> 4) > 7 || FCombat.FCombatData.FParties.GetParty((byte)(int)(((uint)Position) >> 4)).FWall == 0 || FCombat.FCombatData.FWall.FStatus.Contains(CombatObjectStatusElement.Destroyed))
                {
