                if (Source.GetAbilityEnabled(119) && Aow.Game.Magic.Abilities.HitChance.HitRole(7 - Target.GetResistance()))
                {
                    FStrikeMode = FStrikeMode + Set<StrikeModeElement>.Of(StrikeModeElement.Entangled);
                }
            }
