            FastCombatCommand Command;
            for (int I = 0, last = Commands.FTargetSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FTargetSide.GetObjects(I);
                if (Target.GetEnabled() && fcValidRoundDistance(Commands.FSource, Target))
                {
                    var wallSituation = Commands.FSource.FCombat.GetWallSituation(Commands.FSource, Target);
                    fcGetDamageValueEx(Commands.FSource, Target, wallSituation, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new FastCombatCommand(FAbilityID);
                        Command.FTarget = Commands.FTargetSide.GetObjects(I);
                        Command.FMoveCost = 1;
                        Command.FExpectedDV = Aow.Game.Magic.Abilities.AbilityRules.DVtoDEV(Values.SourceDamage, Values.TargetDamage, Commands.FSource, Target);
                        Commands.Add(Command);
                    }
                }
            }
        }

        // AoWAb.PAS:4787
        public override bool fcExecuteCombatCommand(CombatObject Source, FastCombatCommand Command)
        {
            CombatObject Target;
            int Penalty;
            RangedAttackCA Action;
            Target = Command.FTarget;
            if (Source.FCombat.GetWallSituation(Source, Target) == WallSituation.Target)
            {
                Penalty = 2;
            }
            else
            {
                Penalty = 0;
            }

            if (Target.GetEnabled())
            {
                for (int I = GetAttackRepeatRA(Source.GetAbilityOwner()) - 1; I >= 0; I--)
                {
                    Action = CreateRangedAttackCA(Source, Target, Penalty);
                    Source.FCombat.ExecuteCombatAction(Action);
                    Action.Release();
                }

                ((FastCombatUnit)Source).FState = ((FastCombatUnit)Source).FState + Set<FastCombatUnitStateElement>.Of(FastCombatUnitStateElement.Vulnerable);
            }

            return true;
        }

        // AoWAb.PAS:4708
        public override int GetDamageValue(AbstractUnit Attacker, AbstractUnit Defender)
        {
            int Repeats;
            var hitPoints = Defender.GetHitPoints();
            var defense = Defender.GetDefense();
            var resistance = Defender.GetResistance();
            var immunityTypes = Defender.GetImmunityTypes();
            var protectionTypes = Defender.GetProtectionTypes();
            var damageTypesRA = GetDamageTypesRA(Attacker);
            var damageRA = GetDamageRA(Attacker);
            int Result = Aow.Game.Magic.Abilities.AbilityRules.StatisticsToLimitedDV(GetAttackRA(Attacker), damageRA, damageTypesRA, hitPoints, defense, resistance, immunityTypes, protectionTypes);
            Repeats = GetAttackRepeatRA(Attacker);
            return Result * Repeats;
        }

        // AoWAb.PAS:4717
        public override void GetDamageValueEx(AbstractUnit Attacker, AbstractUnit Defender, WallSituation WallSituation, ref AbilityDamageValues DamageValues)
        {
            int Defense;
            int Damage;
            int Repeats;
            Defense = Defender.GetDefense();
            if (WallSituation == Combat.WallSituation.Target)
            {
                Defense += 2;
            }

            var hitPoints = Defender.GetHitPoints();
            var resistance = Defender.GetResistance();
            var immunityTypes = Defender.GetImmunityTypes();
            var protectionTypes = Defender.GetProtectionTypes();
            var damageTypesRA = GetDamageTypesRA(Attacker);
            var damageRA = GetDamageRA(Attacker);
            Damage = Aow.Game.Magic.Abilities.AbilityRules.StatisticsToLimitedDV(GetAttackRA(Attacker), damageRA, damageTypesRA, hitPoints, Defense, resistance, immunityTypes, protectionTypes);
            Repeats = GetAttackRepeatRA(Attacker);
            Damage = Damage * Repeats;
            DamageValues.SourceDamage = Damage;
            DamageValues.TargetDamage = 0;
            var damageTypesRA2 = GetDamageTypesRA(Attacker);
            DamageValues.DamageTypes = damageTypesRA2;
        }

        // AoWAb.PAS:4703
        public override void GetOffensiveStrength(AbilityOwner Owner, ref int Strength, ref Set<DamageType> Types)
        {
