        {
            sbyte Result = FDamageRA;
            if (Owner != null && Owner.GetAbEnabled(32))
            {
                switch (Owner.GetAbLevel(32))
                {
                    case 2:
                        Result = (sbyte)(Result + 1);
                        break;
                    case 3:
                        Result = (sbyte)(Result + 1);
                        break;
                    case 4:
                        Result = (sbyte)(Result + 2);
