        public virtual bool CombatTouchRole(CombatUnit Source, CombatObject Target)
        {
            int Attack;
            bool Result = Aow.Game.Magic.Abilities.HitChance.HitRole(Source.GetAttack() - Target.GetDefense());
            Attack = GetTouchAttack(GetLevel(Source.FUnit));
            if (Result && Attack != -10)
            {
                Result = Result && Aow.Game.Magic.Abilities.HitChance.HitRole(Attack - Target.GetResistance());
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:1904
        public virtual float CombatTouchRoleProbability(CombatUnit Source, CombatObject Target)
        {
