        // AoWAb.PAS:2673
        public override int GetDamageValue(AbstractUnit Attacker, AbstractUnit Defender)
        {
            int Result;
            float Probability;
            if (CanTouchUnit(Attacker, Defender) && !Defender.GetImmunityTypes().Contains(DamageType.None))
            {
