namespace Aow.Game.Commands
{

    // (unit IDs, players)
    public partial class HealingTE : TokenEvent
    {
        public HealingTE(ECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131826;

        public int FSourceID;
        public byte FSourcePlayer;
        public int FTargetID;
        public byte FTargetPlayer;

        // AoWAb.PAS:3853
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FSourceID, 25);
            Stream.rwByte(ref FSourcePlayer, 26);
            Stream.rwInteger(ref FTargetID, 27);
            Stream.rwByte(ref FTargetPlayer, 28);
        }

        // AoWAb.PAS:3861
        public override ExecuteResult Execute(TokenExecuter TE)
        {
            ExecuteResult Result;
            AbstractUnit Source;
            AbstractUnit Target;
            HealingAbility Ability;
            ImageSequenceAnimation Anim;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            base.Execute(TE);
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FSourceID);
            Target = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FTargetID);
            if (Source != null && (byte)Source.FPlayer == FSourcePlayer && Target != null && (byte)Target.FPlayer == FTargetPlayer)
            {
                Ability = (HealingAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(47);
                if (Ability.GetEnabled(Source))
                {
                    Ability.SetEnabled(Source, false);
                    Ability.HealUnit(Target);
                    Target.GetLocation(ref X, ref Y, ref L);
                    Aow.Game.World.Map.AoWHSMap.Current.ValidateObservation((sbyte)FSourcePlayer, X, Y, L, 0);
                    if (Aow.Game.World.Map.AoWHSMap.Current.Visible(X, Y, L, 0))
                    {
                        Anim = new ImageSequenceAnimation(null);
                        Anim.SetImageSequence(Ability.FImageSequences.GetImageSequence(0));
                        Aow.Game.World.Map.AoWHSMap.Current.PlaceHX(Anim, X, Y, L);
                    }

                    if ((byte)AoWHSMap.Current.FSeatedPlayer == FSourcePlayer || Aow.Game.World.Map.AoWHSMap.Current.Watching(X, Y, L, 0))
                    {
                        Ability.FSFXLibrary.Play(0);
                    }
                }

                Result = ExecuteResult.Done;
            }
            else
            {
                Result = ExecuteResult.DoneHalt;
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

namespace Aow.Game.Units
{

    public partial class HealingUnitSelector : UnitSelector
    {
        public HealingUnitSelector() : base()
        { }

        // AoWAb.PAS:3894
        public override bool CanSelectUnit(AbstractUnit AUnit)
        {
            var unitType = AUnit.GetUnitType();
            if (!(Set<UnitType>.Of(UnitType.Humanoid, UnitType.Creature).Contains(unitType) && AUnit.GetHits() != AUnit.GetHitPoints()))
            {
                return false;
            }

            return true;
        }

        // AoWAb.PAS:3904
        public override bool Select()
        {
            bool Result;
            AbstractUnit Source;
            AbstractUnit Target;
            string Error = "";
            int I;
            HealingTE Event;
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FSourceUnitID);
            if (CanSelect(ref Error) && !Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Source.FPlayer).GetBusy())
            {
                I = 0;
                Target = null;
                while (Target == null && I != FUnits.GetCount())
                {
                    if ((FSelection & (1 << I)) != 0)
                    {
                        Target = FUnits.GetUnit(I);
                    }

                    I += 1;
                }

                if (Target != null)
                {
                    Event = new HealingTE(null);
                    Event.FSourceID = Source.FUnitID;
                    Event.FSourcePlayer = (byte)Source.FPlayer;
                    Event.FTargetID = Target.FUnitID;
                    Event.FTargetPlayer = (byte)Target.FPlayer;
                    Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                    Event.Release();
                    Result = true;
                }
                else
                {
                    Result = false;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

