        public override string GetName(AbilityOwner Owner)
        {
            string Result;
            if (Owner == null || GetEnabled(Owner))
            {
                Result = FAbilityName;
            }
            else
            {
                var used = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.UsedRStr);
                Result = FAbilityName + " (" + LowerCase(used) + ")";
            }

            return Result;
        }

        // AoWAb.PAS:3640
        public override bool GetEnabled(AbilityOwner owner)
        {
            HealingAbilityData Data;
            bool Result = owner.GetAbSet(FAbilityID);
            if (Result)
            {
                Data = (HealingAbilityData)owner.GetAbilityData(FAbilityID);
                if (Data != null)
                {
                    Result = Data.FEnabled;
                }
                else
                {
                    Result = true;
                }
            }

            return Result;
        }

        // AoWAb.PAS:3624
        public override Set<AbilityControlTypeElement> GetControlType(AbilityOwner Owner) => Set<AbilityControlTypeElement>.Of(AbilityControlTypeElement.Action, AbilityControlTypeElement.CombatAction);

        // AoWAb.PAS:3801
        public override void fcPrefetchCombatCommands(FastCombatCommandList Commands)
        {
            CombatObject Target;
            FastCombatCommand Command;
            AbilityDamageValues Values = default;
            for (int I = 0, last = Commands.FSourceSide.GetCount() - 1; I <= last; I++)
            {
                Target = Commands.FSourceSide.GetObjects(I);
                if (Target.GetEnabled() && CanTouch(Commands.FSource, Target))
                {
                    fcGetDamageValueEx(Commands.FSource, Target, WallSituation.None, ref Values);
                    if (Values.SourceDamage != 0)
                    {
                        Command = new FastCombatCommand(FAbilityID);
                        Command.FTarget = Target;
                        Command.FSourceDV = Values.SourceDamage;
                        Command.FTargetDV = 0;
                        Command.FExpectedDV = Aow.Game.Magic.Abilities.AbilityRules.DVtoDEV(Values.SourceDamage, 0, Commands.FSource, Target);
                        Command.FMoveCost = 0;
                        Commands.Add(Command);
                    }
                }
            }
        }

        // AoWAb.PAS:3789
        public override bool fcExecuteCombatCommand(CombatObject Source, FastCombatCommand Command)
        {
            CombatObject Target;
            HealingCA Action;
            Target = Command.FTarget;
            fcValidateMoveOutsideWall(Source, Target);
            Action = CreateHealingCA(Source, Target);
            Source.FCombat.ExecuteCombatAction(Action);
            Action.Release();
            return true;
        }

        // AoWAb.PAS:3654
        public override void NewTurn(AbilityOwner Owner, sbyte Player)
        {
            if (Owner is AbstractUnit && ((AbstractUnit)Owner).FPlayer == Player)
            {
                SetEnabled(Owner, true);
            }
        }

        // AoWAb.PAS:3827
        public override bool Activate(AbilityOwner Owner, ref string Reason)
        {
            bool Result;
            UnitSelectorAAI Info;
            HealingUnitSelector Selector;
            if (CanActivate(Owner, ref Reason))
            {
                var unit = Owner as AbstractUnit;
                Info = new UnitSelectorAAI(null);
                Info.FAbilityID = FAbilityID;
                if (unit != null)
                {
                    Info.FUnitID = unit.FUnitID;
                }
                else
                {
                    Info.FUnitID = 0;
                }

                Selector = new HealingUnitSelector();
                var healing = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(HealingRStr);
                Selector.FCaption = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.SelectUnitForXRStr), [healing]);
                if (unit != null)
                {
                    Selector.Setup(unit, (UnitList)unit.Owner);
                }

                Info.SetUnitSelector(Selector);
                // { Original omits Selector.Release here. }
                Aow.Game.World.Map.AoWHSMap.Current.FOnActivateAbilityStore.Raise(Info);
                Info.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // AoWAb.PAS:3670
        public override bool Remove(AbilityOwner owner)
        {
            bool Result = base.Remove(owner);
            if (Result)
            {
                owner.RemoveAbilityDataID(FAbilityID);
            }

            return Result;
        }

        // AoWAb.PAS:3707
        public override int GetDamageValue(AbstractUnit Attacker, AbstractUnit Defender)
        {
            int Result;
            if (!Defender.GetImmunityTypes().Contains(DamageType.None))
            {
                Result = Defender.GetHits() - Defender.GetHitPoints();
                if (Result > 5)
                {
                    Result = 5;
                }

                return Result * 100;
            }

            return 0;
        }

        // AoWAb.PAS:3718
        public override void GetDamageValueEx(AbstractUnit Attacker, AbstractUnit Defender, WallSituation WallSituation, ref AbilityDamageValues DamageValues)
        {
            if (WallSituation == Combat.WallSituation.None && !Defender.GetImmunityTypes().Contains(DamageType.None))
            {
                var hits = Defender.GetHits();
                var hitPoints = Defender.GetHitPoints();
                DamageValues.SourceCost = hits - hitPoints;
                if (DamageValues.SourceCost > 5)
                {
                    DamageValues.SourceCost = 5;
                }

                DamageValues.SourceDamage = DamageValues.SourceCost * 100;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = Set<DamageType>.Of(DamageType.None);
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = Set<DamageType>.Of();
            }
        }

        // AoWAb.PAS:3738
        public override void fcGetDamageValueEx(CombatObject Attacker, CombatObject Defender, WallSituation WallSituation, ref AbilityDamageValues DamageValues)
        {
            int HitPoints;
            if (WallSituation == Combat.WallSituation.None && CanTouch(Attacker, Defender))
            {
                HitPoints = GetHealHitPoints(Defender);
                DamageValues.SourceCost = HitPoints;
                DamageValues.SourceDamage = HitPoints * 100;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = Set<DamageType>.Of(DamageType.None);
            }
            else
            {
                DamageValues.SourceDamage = 0;
                DamageValues.SourceCost = 0;
                DamageValues.TargetDamage = 0;
                DamageValues.TargetCost = 0;
                DamageValues.DamageTypes = Set<DamageType>.Of();
            }
        }

        // AoWAb.PAS:3702
        public override void GetCombatInfo(AbilityOwner Owner, ref AbilityCombatInfo Info)
        {
            base.GetCombatInfo(Owner, ref Info);
            Info.TargetTypes = Set<CombatTargetTypeElement>.Of(CombatTargetTypeElement.Friend);
        }

        // AoWAb.PAS:3693
        public override bool CanTouch(CombatObject Source, CombatObject Target)
        {
            bool Result = base.CanTouch(Source, Target);
            if (Result)
            {
                bool condition = Source is CombatUnit && Target is CombatUnit;
                if (condition)
                {
                    var unitType = ((CombatUnit)Target).FUnit.GetUnitType();
                    condition = Set<UnitType>.Of(UnitType.Humanoid, UnitType.Creature).Contains(unitType);
                }

                Result = condition && (Target.GetHits() != Target.GetHitPoints() || Target.GetAbilityEnabled(96) || Target.GetAbilityEnabled(53) || Target.GetAbilityEnabled(108));
            }

            return Result;
        }

        // AoWAb.PAS:3685
        public override bool CanTouchUnit(AbstractUnit Source, AbstractUnit Target)
        {
            bool Result = base.CanTouchUnit(Source, Target);
            if (Result)
            {
                var unitType = Target.GetUnitType();
                Result = Set<UnitType>.Of(UnitType.Humanoid, UnitType.Creature).Contains(unitType) && (Target.GetHits() != Target.GetHitPoints() || Target.GetAbilityEnabled(96) || Target.GetAbilityEnabled(53) || Target.GetAbilityEnabled(108));
            }

            return Result;
        }

        // AoWAb.PAS:3628
        public void SetEnabled(AbilityOwner Owner, bool Enabled)
        {
            HealingAbilityData Data;
            Data = (HealingAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data == null)
            {
                Data = new HealingAbilityData(null);
                Owner.AddAbilityData(Data);
            }

            Data.FEnabled = Enabled;
        }

        // AoWAb.PAS:3675
        public int GetHealHitPoints(CombatObject Target)
        {
            int Result = Target.GetHits() - Target.GetHitPoints();
            if (Result > 5)
            {
                Result = 5;
            }

            return Result;
        }

        // AoWAb.PAS:3680
        public HealingCA CreateHealingCA(CombatObject Source, CombatObject Target)
        {
            HealingCA Result = new HealingCA(null);
            Result.Initialize(Source.FID, Target.FID);
            return Result;
        }

        // AoWAb.PAS:3760
        public bool HealUnit(AbstractUnit Unit)
        {
            int HitPoints;
            bool Result = false;
            if (Unit.GetHits() != Unit.GetHitPoints())
            {
                HitPoints = Unit.GetHits() - Unit.GetHitPoints();
                if (HitPoints > 5)
                {
                    HitPoints = 5;
                }

                Unit.SetHitPoints((sbyte)(Unit.GetHitPoints() + (sbyte)HitPoints));
                Result = true;
            }

            if (Unit.GetAbilityEnabled(96))
            {
                Unit.RemoveAbility(96);
                Result = true;
            }

            if (Unit.GetAbilityEnabled(53))
            {
                Unit.RemoveAbility(53);
                Result = true;
            }

            if (Unit.GetAbilityEnabled(108))
            {
                Unit.RemoveAbility(108);
                Result = true;
            }

            Unit.Changed();
            return Result;
        }

        // AoWAb.PAS:3659
        public override EClass AbilityDataClass() => P4HealingDataClass;

        private static EClass P4HealingDataClass = global::Aow.Game.Engine.EClass.Of<HealingAbilityData>();
        private static readonly string HealingRStr = "Healing";

    }
}

namespace Aow.Game.Combat.Actions
{

    // (dispelled enchantment IDs)
    public partial class DispelMagicCA : SingleTargetCA
    {

        // AoWAb.PAS:3936
        public DispelMagicCA(ECustomNode owner) : base(owner)
        {
            FEnchantmentIDs = new IntegerList();
        }

        public IntegerList FEnchantmentIDs;

        // AoWAb.PAS:3941
        public override void Dispose()
        {
            FEnchantmentIDs?.Dispose();
            base.Dispose();
        }

        // AoWAb.PAS:3946
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwStreamProc(50, FEnchantmentIDs.LoadFromStream, FEnchantmentIDs.SaveToStream);
        }

        // AoWAb.PAS:3951
        public override void Execute(Combat Combat)
        {
            EnchantmentList Enchantments;
            CombatObject Source;
            CombatObject Target;
            Enchantment Enchantment;
            bool WasSummoned;
            Source = Combat.FCombatData.FindID(FSourceID);
            Target = Combat.FCombatData.FindID(FTargetID);
            if (Source is CombatUnit && Target is CombatUnit)
            {
                Enchantments = new EnchantmentList(null);
                var combatUnit = (CombatUnit)Target;
                combatUnit.FUnit.ListEnchantments(Enchantments);
                WasSummoned = combatUnit.FUnit.GetAbilityEnabled(155);

                for (int I = FEnchantmentIDs.Count - 1; I >= 0; I--)
                {
                    Enchantment = Enchantments.FindID(FEnchantmentIDs[I]);
                    if (Enchantment != null)
                    {
                        Enchantment.Dispel();
                    }
                }

                if (WasSummoned && !((CombatUnit)Target).FUnit.GetAbilityEnabled(155))
                {
                    Source.DoDamage(Target, Target.GetHitPoints());
                }

                Enchantments?.Dispose();
            }
        }

        // AoWAb.PAS:3986
        public override bool Play(CombatViewer Viewer)
        {
            if (Viewer.FTime == 0)
            {
                Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(60).FSFXLibrary.Play(0);
            }

            if (Viewer.FDelay == Viewer.FTime)
            {
                Execute(Viewer.FCombat);
            }

            return Viewer.FDelay * 2 > Viewer.FTime;
        }

        // AoWAb.PAS:3979
        public override void ShowObject(CombatViewer Viewer, CombatObject Obj, int Frame, int Direction, int X, int Y, in SurfaceDesc Surface)
        {
            base.ShowObject(Viewer, Obj, Frame, Direction, X, Y, Surface);
            if (Obj.FID == FTargetID)
            {
                Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(60).FImageSequences.Show(0, X + 32, Y + 32, Viewer.FTime, Surface);
            }
        }

        // AoWAb.PAS:3994
        public void Generate(CombatObject Source, CombatObject Target, int DispelMana)
        {
            EnchantmentList Enchantments;
            int Chance;
            FSourceID = Source.FID;
            FTargetID = Target.FID;
            if (Source is CombatUnit && Target is CombatUnit)
            {
                Enchantments = new EnchantmentList(null);
                ((CombatUnit)Target).FUnit.ListEnchantments(Enchantments);
                for (int I = Enchantments.GetCount() - 1; I >= 0; I--)
                {
                    Chance = Enchantments.GetEnchantments(I).DispelChance(DispelMana);
                    if (Chance > Aow.Game.World.Map.AoWHSMap.Current.Random(100))
                    {
                        var enchantments = Enchantments.GetEnchantments(I);
                        FEnchantmentIDs.Add(enchantments.FEnchantmentID);
                    }
                }

                Enchantments?.Dispose();
            }
        }

        // intf_P4_02.inc:660

    }

    public partial class DispelMagicAbilityCA : DispelMagicCA
    {
        public new const int ClassID = 131775;

        public DispelMagicAbilityCA(ECustomNode owner) : base(owner)
        { }

        // AoWAb.PAS:4018
        public override void Execute(Combat Combat)
        {
            CombatUnit Source;
            base.Execute(Combat);
            Source = (CombatUnit)Combat.FCombatData.FindID(FSourceID);
            ((DispelMagicAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(60)).SetEnabled(Source.FUnit, false);
        }

        // intf_P4_02.inc:660

    }
}

namespace Aow.Game.Commands
{

    // (source unit ID/player, target unit ID/player)
    public partial class DispelMagicAbilityTE : TokenEvent
    {
        public DispelMagicAbilityTE(ECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 131827;

        public int FSourceID;
        public byte FSourcePlayer;
        public int FTargetID;
        public byte FTargetPlayer;

        // AoWAb.PAS:4337
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FSourceID, 25);
            Stream.rwByte(ref FSourcePlayer, 26);
            Stream.rwInteger(ref FTargetID, 27);
            Stream.rwByte(ref FTargetPlayer, 28);
        }

        // AoWAb.PAS:4345
        public override ExecuteResult Execute(TokenExecuter TE)
        {
            ExecuteResult Result;
            int Count;
            int Mana;
            DispelMagicAbility Ability;
            EnchantmentList Enchantments;
            AbstractUnit Source;
            AbstractUnit Target;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            bool Success;
            int Chance;
            ImageSequenceAnimation Anim;
            base.Execute(TE);
            Enchantments = new EnchantmentList(null);
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FSourceID);
            Target = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FTargetID);
            Ability = (DispelMagicAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(60);
            Success = Source != null && (byte)Source.FPlayer == FSourcePlayer && Target != null && (byte)Target.FPlayer == FTargetPlayer;
            Success = Success && Ability.GetEnabled(Source);
            if (Success)
            {
                Target.ListEnchantments(Enchantments);
                Success = Enchantments.GetCount() > 0;
            }

            if (Success)
            {
                Count = 0;
                Mana = ((DispelMagicAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(60)).GetDispelMana(Source);
                for (int I = Enchantments.GetCount() - 1; I >= 0; I--)
                {
                    Chance = Enchantments.GetEnchantments(I).DispelChance(Mana);
                    if (Chance > Aow.Game.World.Map.AoWHSMap.Current.Random(100))
                    {
                        Count += 1;
                        Enchantments.GetEnchantments(I).Dispel();
                    }
                }

                if (Source.FPlayer == AoWHSMap.Current.FSeatedPlayer)
                {
                    if (Count > 0)
                    {
                        var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.XSpellsSuccessfullyDispelledRStr), [IntToStr(Count)]);
                        Aow.Game.World.Map.AoWHSMap.Current.ShowMessage(format);
                    }
                    else
                    {
                        var dispelMagicFailed = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.DispelMagicFailedRStr);
                        Aow.Game.World.Map.AoWHSMap.Current.ShowMessage(dispelMagicFailed);
                    }
                }

                Ability.SetEnabled(Source, false);
                Target.GetLocation(ref X, ref Y, ref L);
                Aow.Game.World.Map.AoWHSMap.Current.ValidateObservation((sbyte)FSourcePlayer, X, Y, L, 0);
                if (Aow.Game.World.Map.AoWHSMap.Current.Visible(X, Y, L, 0))
                {
                    Anim = new ImageSequenceAnimation(null);
                    Anim.SetImageSequence(Ability.FImageSequences.GetImageSequence(0));
                    Aow.Game.World.Map.AoWHSMap.Current.PlaceHX(Anim, X, Y, L);
                }

                if ((byte)AoWHSMap.Current.FSeatedPlayer == FSourcePlayer || Aow.Game.World.Map.AoWHSMap.Current.Watching(X, Y, L, 0))
                {
                    Ability.FSFXLibrary.Play(0);
                }

                Result = ExecuteResult.Done;
            }
            else
            {
                Result = ExecuteResult.DoneHalt;
            }

            Enchantments?.Dispose();
            return Result;
        }

        // NetworkE.pas:230

    }
}

