            Data = (UnitEnchantmentAbilityData)Owner.GetAbilityData(FAbilityID);
            if (Data != null)
            {
                Result = (byte)Data.FEnchantmentDuration;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

