        // Spells.PAS:371
        public bool AIRequestCastSpellExpense(AbstractUnit Source, int Budget, int Mana, int Upkeep)
        {
            bool Result;
            AIBudgetManager Manager;
            if (Upkeep > 0)
            {
                Mana -= Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Source.FPlayer).FMagicControl.AIRequestOverrideUpkeep(Round((double)Upkeep * 0.8));
                if (Mana < 0)
                {
                    Mana = 0;
                }
            }

            Manager = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Source.FPlayer).FAIBudget;
            if (!Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Source.FPlayer).FMagicControl.GetCheatEnabled())
            {
                Result = Manager.RequestBudgetExpenseEx(0, Budget, 0, Mana, Manager.FDefaultBudget, 1 != 0);
            }
            else
            {
                Result = true;
            }

            return Result;
        }

