            FEventSourceID = SourceID;
            FEventPlayerIndex = PlayerIndex;
            FEventMana = Mana;
        }

        // NetworkE.pas:230
        public AbstractUnit GetSource() => Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FEventSourceID);

        public virtual bool Validate(Hero source)
        {
            string reason = "";
            try { return (byte)source.FPlayer == FEventPlayerIndex && source.CanCastSpellInstantly(FEventSpellID, FEventMana, ref reason); }
            finally { reason = ""; }
        }

        public virtual bool Process(AbstractUnit source, int value) => Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FEventSpellID).ExecuteTE(this, source, value);

