        {
            sbyte x = 0, y = 0, l = 0;
            GetSource().GetLocation(ref x, ref y, ref l);
            var spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FEventSpellID);
            spell.PlayDefaultCastEffects(GetSource().FPlayer, x, y, l);
        }

        public override ExecuteResult Execute(TokenExecuter executer)
        {
            base.Execute(executer);
            var source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FEventSourceID);
            if (source == null || executer.ExecuteCount == 0 && !Validate((Hero)source)) return ExecuteResult.DoneHalt;
            return Process(source, executer.ExecuteCount) ? ExecuteResult.Retry : ExecuteResult.Done;
        }
    }
}

