namespace Aow.Game.Units
{

    // (target-unit users, selection bits)
    public partial class UnitSpellCaster : SpellCaster
    {
        // Spells.PAS:859
        public UnitSpellCaster(ECustomNode owner) : base(owner)
        {
            FTargetUnits = new UnitUserList(null);
        }

        public UnitUserList FTargetUnits;
        public byte FSelectionMask;
        public bool FAllowMultipleTargets;
        public byte FValidSelection;

        // Spells.PAS:864
        public override void Dispose()
        {
            FTargetUnits?.Dispose();
            base.Dispose();
        }

        // Spells.PAS:947
        public override bool CanCast(ref string Reason)
        {
            bool Result;
            Hero Hero;
            int Mana;
            Hero = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit<Hero>(FCasterSourceID);
            if (Hero != null && !Hero.FUnitStatus.Contains(UnitStatusElement.Killed))
            {
                if (FSelectionMask != 0)
                {
                    if (!Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Hero.FPlayer).FMagicControl.GetCheatEnabled())
                    {
                        Mana = GetRequiredMana();
                        if (Hero.CastingReady() && Hero.FCastingSpellID == FCasterSpellID)
                        {
                            Mana -= Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FCasterSpellID).FBaseManaCost;
                        }

                        if (Mana <= Hero.GetCastingPoints())
                        {
                            if (Mana <= Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Hero.FPlayer).FMagicControl.FMana)
                            {
                                Result = true;
                            }
                            else
                            {
                                Result = false;
                                Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NotEnoughManaRStr);
                            }
                        }
                        else
                        {
                            Result = false;
                            Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.P2NotEnoughCastingPointsRStr);
                        }
                    }
                    else
                    {
                        Result = true;
                    }
                }
                else
                {
                    Result = false;
                    Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.NoUnitSelectedRStr);
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:981
        public override bool Cast()
        {
            bool Result;
            UnitUserList Targets;
            string Reason = "";
            AbstractUnit Source;
            if (CanCast(ref Reason))
            {
                Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FCasterSourceID);
                if (Source != null)
                {
                    Targets = new UnitUserList(null);
                    for (int I = 0, last = FTargetUnits.Count - 1; I <= last; I++)
                    {
                        if (((1 << I) & FSelectionMask) != 0)
                        {
                            Targets.AddUnit(FTargetUnits.GetUnit(I));
                        }
                    }

                    Result = ((UnitSpell)Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FCasterSpellID)).CastSpell(Source, Targets);
                    Targets?.Dispose();
                }
                else
                {
                    Result = true;
                }
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:896
        public int GetSelectionCount()
        {
            int Bits;
            int Result = 0;
            Bits = FSelectionMask;
            while (Bits != 0)
            {
                if ((Bits & 1) != 0)
                {
                    Result += 1;
                }

                Bits = (int)(((uint)Bits) >> 1);
            }

            return Result;
        }

        // Spells.PAS:1085
        public bool Valid()
        {
            bool Result;
            AbstractUnit Source;
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit<AbstractUnit>(FCasterSourceID);
