                else
                {
                    if (((Hero)Source).FCastingSpellID != FSpellID)
                    {
                        ((Hero)Source).ExecuteStartCasting(FSpellID);
                        Result = true;
                    }
                    else
                    {
                        Result = true;
                    }
                }
            }
            else
            {
                Result = false;
            }

