            UnitSpellTE Event;
            ResetTargetSelection();
            if (!Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Source.FPlayer).GetBusy())
            {
                Event = new UnitSpellTE(null);
                var castingMana = ((Hero)Source).CastingMana(this);
                Event.Initialize(FSpellID, Source, Targets, castingMana);
                Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(Source.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Spells.PAS:1344
        public virtual bool ValidTargetParty(AbstractUnit Source, ArmyHS Party) => !Party.FArmy.FStatus.Contains(ArmyStatusElement.FullyConcealed);

        // Spells.PAS:1346
        public virtual void TargetPartySelected(AbstractUnit Source, ArmyHS Party)
        {
            UnitSpellCaster Caster;
            Caster = new UnitSpellCaster(null);
            SetupUSC(Caster, Source, Party.FArmy);
            Aow.Game.World.Map.AoWHSMap.Current.FCosmeticSurgeryEventsStore.Raise(Caster);
            Caster.Release();
        }

        // Spells.PAS:1224
        public virtual bool ExecuteSpell(AbstractUnit Source, AbstractUnit Target, int Mana, ref FixedArray_int_2 Data) => false;

        // Spells.PAS:1400
        public virtual UnitSpellCA CreateCAEx(CombatObject Source, CombatObject Target, int Mana)
        {
            UnitSpellCA Result;
            if (FSpellControlTypes.Contains(SpellControlTypeElement.Combat))
            {
                Result = new UnitSpellCA(null);
                Result.FSpellID = FSpellID;
                Result.FSourceID = Source.FID;
                Result.FTargetID = Target.FID;
            }
            else
            {
                Result = null;
            }

            return Result;
        }

        // Spells.PAS:1411
        public virtual void ExecuteCA(Game.Combat.Combat Combat, UnitSpellCA Action)
        {
            CombatObject Source;
            CombatObject Target;
            Source = Combat.FCombatData.FindID(Action.FSourceID);
            Target = Combat.FCombatData.FindID(Action.FTargetID);
            if (Source is CombatUnit && Target is CombatUnit)
            {
                if (ExecuteSpell(((CombatUnit)Source).FUnit, ((CombatUnit)Target).FUnit, Action.FMana, ref Action.FSpellData))
                {
                    if (Action.FMana != 0 && (((byte)Combat.FStatus.Image) & 1) != 0)
                    {
                        Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FSpellID).CombatCastingDone(Source, Action.FMana);
                    }
                }
            }
        }

        // Spells.PAS:1422
        public virtual bool AIRetrieveOptimalTargetUnit(AbstractUnit Source, UnitList Targets, ref AbstractUnit Target, ref int Priority)
        {
            bool Result;
            DoubleItemList<AbstractUnit> List;
            int Value;
            List = new DoubleItemList<AbstractUnit>();
            for (int I = 0, last = Targets.GetCount() - 1; I <= last; I++)
            {
                if (ValidTargetUnit(Source, Targets.GetUnit(I)) && Targets.GetUnit(I).GetUnitType() != UnitType.Machine)
                {
                    Value = Targets.GetUnit(I).GetUnitLevel() + FAIValue;
                    List.AddAB(Targets.GetUnit(I), Value);
                }
            }

            if (List.Count != 0)
            {
                List.SortDescendingItemB();
                Target = List[0].A;
                Priority = List[0].B;
                Result = true;
            }
            else
            {
                Result = false;
            }

            List?.Dispose();
            return Result;
        }

        // Spells.PAS:1269
        public void OnValidateTarget(TargetSelectionControl Control, sbyte X, sbyte Y, sbyte L, ref bool Valid)
        {
            AbstractUnit Source;
            ArmyHS Party;
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.Visible(X, Y, L, 0))
                {
                    Party = ((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(X, Y, L)).GetArmyHS();
                    if (Party != null && (Party.FArmy.FPlayer == Source.FPlayer || !((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(X, Y, L)).GetMagicShieldActive()))
                    {
                        Valid = ValidTargetParty(Source, Party);
                    }
                    else
                    {
                        Valid = false;
                    }
                }
                else
                {
                    Valid = false;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1289
        public void OnTargetSelectionChange(TargetSelectionControl Control)
        {
            AbstractUnit Source;
            ArmyHS Party;
            Source = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(Control.FSourceUnitID);
            if (Source != null)
            {
                switch (Control.FChange)
                {
                    case TargetSelectionChange.Deactivated:
                        ResetTargetSelection();
                        break;
                    case TargetSelectionChange.Selected:
                        if (Control.FTargetX != -1)
                        {
                            Party = ((AoWMapField)Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetField(Control.FTargetX, Control.FTargetY, Control.FTargetL)).GetArmyHS();
                            if (Party != null && ValidTargetParty(Source, Party))
                            {
                                TargetPartySelected(Source, Party);
                            }
                        }

                        break;
                }
            }
            else
            {
                ResetTargetSelection();
            }
        }

        // Spells.PAS:1310
        public void ResetTargetSelection()
        {
            var targetSelectionControl = AoWHSMap.Current.FTargetSelection;
            targetSelectionControl.FOnChange -= OnTargetSelectionChange;
            targetSelectionControl.Deactivate();
        }

        // Spells.PAS:1318
        public void SetupTargetSelection(AbstractUnit Source, TargetSelectionControl Control)
        {
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            Control.Initialize(Source);
            Control.FTargetMode = Control.FTargetMode + Set<TargetSelectionModeElement>.Of(TargetSelectionModeElement.ExternalFloater);
            if (FTargetRange != -1)
            {
                Control.FTargetMode = Control.FTargetMode + Set<TargetSelectionModeElement>.Of(TargetSelectionModeElement.ValidateDistance);
                Control.FRange = FTargetRange;
            }
            else
            {
                Control.FRange = 0;
            }

            Source.GetLocation(ref X, ref Y, ref L);
            Control.FSourceX = X;
            Control.FSourceY = Y;
            Control.FSourceL = L;
            Control.FOnChange += OnTargetSelectionChange;
            Control.FOnValidateTarget = OnValidateTarget;
            var format = Aow.Game.Magic.Abilities.AbilityRules.Format(Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(P4SelectTargetPartyForXRStr), [FSpellName]);
            Control.FText.Text = format;
            Control.FTitle = FSpellName;
            Control.FCancelText = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(GameText.CancelRStr);
            Control.FSourceUnitID = Source.FUnitID;
            Control.FSourceImage = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(20).GetPreviewImage();
            Control.FValidTargetImage = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(21).GetPreviewImage();
            Control.FInvalidTargetImage = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(FSpellID).FCastImages.GetImageSequence(22).GetPreviewImage();
        }

        private static FixedArray_byte_9 P4SelectionMasks = global::Aow.Game.Engine.Buffers.FixedArray_byte_9.From((ReadOnlySpan<byte>)new byte[9] { 0, 1, 3, 7, 15, 31, 63, 127, 255 });
        private static readonly string P4SelectTargetPartyForXRStr = "Select target party for %s on map";
    }
}

namespace Aow.Game.Ai
{

    public partial class ResearchSpellAIPA : AIPlayerAction, IAIPlayerActionClass
    {
        public ResearchSpellAIPA(ECustomNode owner) : base(owner)
        { }

        // Spells.PAS:1504
        public override bool Process()
        {
            DoubleItemList Choices;
            SpellList Spells;
            int Value;
            int Index;
            if (FControl.FPlayer.FPlayerIndex != 0 && FControl.FPlayer.FMagicControl.FResearchSpellID == 0)
            {
                Spells = new SpellList();
                Choices = new DoubleItemList();
                FControl.FPlayer.FMagicControl.ListResearchSpells(ref Spells, Set<SpellType>.Of(SpellType.Combat, SpellType.Unit, SpellType.Global));
                for (int I = 0, last = Spells.GetCount() - 1; I <= last; I++)
                {
                    Value = Spells.GetSpell(I).FCastDuration * 100 + 100;
                    var spell = Spells.GetSpell(I);
                    var netPowerToResearch = FControl.FPlayer.FMagicControl.GetNetPowerToResearch();
                    Value = Value - FControl.FPlayer.FMagicControl.ResearchTurns(netPowerToResearch, spell.FResearchCost);
                    if (Value <= 0)
                    {
                        Value = 1;
                    }

                    Choices.AddAB(Spells.GetSpell(I).FSpellID, Value);
                }

                if (Choices.Count != 0)
                {
                    RandSeed = Aow.Game.World.Map.AoWHSMap.Current.Random(16777215);
                    Index = Choices.RandomChanceItemB(0);
                    var item = Choices[Index];
                    FControl.FPlayer.FMagicControl.ExecuteResearchSpell(item.A);
                }

                Choices?.Dispose();
                Spells?.Dispose();
            }

            return false;
        }

        // Spells.PAS:1502
        // inherited player control
        public static new int Priority => 22;

    }

