                FResearchPointsLeft = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FMagicControl.FResearchPointsLeft;
                RandSeed = Aow.Game.World.Map.AoWHSMap.Current.Random(16777215);
                GenerateTransferUnits(Units);
                Units?.Dispose();
            }
        }

