        // Diplomacy.pas:2343
        public virtual void SetupScenario()
        {
            sbyte Player;
            int Level;
            Spell Spell;
            Race Race;
            byte Relation;
            Player = (sbyte)(AoWHSMap.Current.FPlayers.Count - 1);
            while (Player > 1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType != PlayerType.Human)
            {
                Player = (sbyte)(Player - 1);
            }

            Level = 1 + FCompletedScenarios.Count / 4;
            for (int I = 1, last = AoWHSMap.Current.FPlayers.Count - 1; I <= last; I++)
            {
                if (I != Player)
                {
                    for (int J = 0, lastJ = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetCount() - 1; J <= lastJ; J++)
                    {
                        Spell = Aow.Game.Engine.AoWHSSet.Current.FSpellControl.GetSpell(J);
                        bool condition = Spell != null && Spell.FSpellLevel <= Level;
                        if (condition)
                        {
                            var spherePicks = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FLeader.GetSpherePicks(Spell.FMagicSphere);
                            condition = Spell.FSpellLevel <= spherePicks;
                        }

                        if (condition)
                        {
                            if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FMagicControl.FSpells.IndexOf(J) == -1)
                            {
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FMagicControl.FSpells.Add(J);
                            }
                        }
                    }
                }
            }

            for (int I = 1, last = AoWHSMap.Current.FPlayers.Count - 1; I <= last; I++)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType != PlayerType.Human && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation((sbyte)I, Player) != DiplomaticRelation.Alliance)
                {
                    if (FDifficultyLevel == CampaignDifficultyLevel.Easy)
                    {
                        switch (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case PlayerType.CPU2:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU1;
                                break;
                            case PlayerType.CPU3:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU2;
                                break;
                            case PlayerType.CPU4:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU3;
                                break;
                            case PlayerType.CPU5:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU3;
                                break;
                        }
                    }

                    if (FDifficultyLevel == CampaignDifficultyLevel.Hard)
                    {
                        switch (Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType)
                        {
                            case PlayerType.CPU1:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU3;
                                break;
                            case PlayerType.CPU2:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU4;
                                break;
                            case PlayerType.CPU3:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU5;
                                break;
                            case PlayerType.CPU4:
                                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(I).FPlayerType = PlayerType.CPU5;
                                break;
                        }
                    }
                }
            }

            Aow.Game.World.Map.AoWHSMap.Current.SetupPlayerControl(FPlayMode, PlayerConnectionType.Local);
            for (int R = 0, last = AoWHSMap.Current.FRaces.Count - 1; R <= last; R++)
            {
                if (Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(R) != null)
                {
                    Race = Aow.Game.World.Map.AoWHSMap.Current.FRaces.GetRace(R);
                    if (Race != null)
                    {
                        for (int I = 0; I <= 11; I++)
                        {
                            if ((FRaceHistory.IndexOf((byte)I) != -1 || I == Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerRace) && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerRace == R || (FRaceHistory.IndexOf((byte)R) != -1 || Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerRace == R) && I == Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerRace)
                            {
                                Relation = Race.FDefaultRelations[I];
                                switch (Relation)
                                {
                                    case 0:
                                        Relation = 3;
                                        break;
                                    case 1:
                                        Relation = 3;
                                        break;
                                    case 2:
                                        Relation = 4;
                                        break;
                                    case 3:
                                        Relation = 4;
                                        break;
                                }

                                Race.FDefaultRelations[I] = Relation;
                            }
                        }
                    }
                }
            }

            AoWHSMap.Current.FAlliedVictory = AoWHSMap.Current.FCampaignSettings.FAlliedVictory;
            FTransferSettings.ExecuteSelection();
            FScenarioStarted = true;
        }

        // Diplomacy.pas:2416
        public virtual void FinishScenario()
        {
            sbyte Player;
            string FileName;
            FScenarioStarted = false;
            FCompletedScenarios.Add(FCurrentScenarioID);
            FTransferSettings.Retrieve();
            FStream.Clear();
            Player = (sbyte)(AoWHSMap.Current.FPlayers.Count - 1);
            while (Player > 1 && Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player).FPlayerType != PlayerType.Human)
            {
                Player = (sbyte)(Player - 1);
            }

            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
            if (FRaceHistory.IndexOf((byte)players.FPlayerRace) == -1)
            {
                var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(Player);
                FRaceHistory.Add((byte)fPlayersPlayers.FPlayerRace);
            }

            FileName = GetAutoSaveFileName(CampaignAutoSaveType.ScenarioFinished);
            Aow.Game.Magic.Abilities.GameTables.AoWEngine.SaveCampaign(GameTables.AoWEngine.StartupDirectory + "Save\\" + FileName);
        }

