    // RefCount, Day, Source, Target, OtherPlayer, Reaction, EscrowGold, EscrowMana, EventLogID and the
    // proposal (AoWE.DiplomaticProposals.cs), stored as ActionType, Gold, Mana and Message
    public partial class DiplomaticAction : EObject
    {
        // Diplomacy.pas:495
        public new const int ClassID = 131666;

        // Diplomacy.pas:482
        public DiplomaticAction(ECustomNode owner) : base(owner)
        {
            FRefCount = 1;
        }

        public int FRefCount;
        public int FDay;
        public sbyte FSource;
        public sbyte FTarget;
        // The census finds it written for every kind, 255 for the kinds that name no other player.
        public sbyte FOtherPlayer;
        public DiplomaticActionReaction FReaction;
        public DiplomaticProposal Proposal = new DeclareWar();
        public int FEscrowGold;
        public int FEscrowMana;
        public int FEventLogID;

        // Diplomacy.pas:596
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            var (kind, gold, mana) = Proposal.ToFields();
            var message = new StringList();
            foreach (var line in Proposal.Message)
            {
                message.Add(line);
            }

            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FSource), 20);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FTarget), 21);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FOtherPlayer), 22);
            Stream.rwInteger(ref gold, 23);
            Stream.rwInteger(ref mana, 24);
            Stream.rwData(Bytes.Of(ref kind, 1), 1, 25);
            Stream.rwData(Bytes.Of(ref FReaction, 1), 1, 26);
            Stream.rwStrings(message, 27);
            if (Stream.StorageMode().Contains(StorageModeElement.Read))
            {
                Proposal = DiplomaticProposal.FromFields(kind, gold, mana) with { Message = DiplomaticProposal.Lines(message) };
            }

            message?.Dispose();
            Stream.rwInteger(ref FEscrowGold, 28);
            Stream.rwInteger(ref FEscrowMana, 29);
            Stream.rwInteger(ref FEventLogID, 30);
            Stream.rwInteger(ref FDay, 31);
        }

        // Diplomacy.pas:586
        public override int AddRef()
        {
            FRefCount += 1;
            return FRefCount;
        }

        // Diplomacy.pas:589
        public override int Release()
        {
            FRefCount -= 1;
            int Result = FRefCount;
            if (FRefCount == 0)
            {
                Dispose();
            }

            return Result;
        }

        // Diplomacy.pas:613
        public override void MsgProc(ref EMsg Msg, EObject Sender)
        {
            bool Ignore;
            EventLog Log;
            base.MsgProc(ref Msg, Sender);
            if (Msg.MsgID == 537001986 && Msg.Payload.Int == FSource && FReaction == DiplomaticActionReaction.None)
            {
                Ignore = Proposal.LapsesUnanswered(this);
                if (Ignore && (AoWHSMap.Current.FPlayMode != PlayMode.Simultaneous || AoWHSMap.Current.FDay > FDay + 1))
                {
                    FReaction = DiplomaticActionReaction.Ignore;
                    Log = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
                    Assert(Log is DiplomaticActionEventLog, "", "Diplomacy.pas", 697);
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
                    var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
                    var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
                    Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
                    FEscrowGold = 0;
                    FEscrowMana = 0;
                }
            }
        }

        // Diplomacy.pas:992
        public virtual void ExecuteSend(DiplomaticActionTE TE)
        {
            if (FReaction == DiplomaticActionReaction.None)
            {
                var (_, gold, mana) = Proposal.ToFields();
                FEscrowGold = gold;
                var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).SetGems(players.FGems - gold);
                FEscrowMana = mana;
                var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
                Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana - mana);
                Proposal.Sent(this);
            }
        }

        // Diplomacy.pas:826
        public virtual void ExecuteAccept(DiplomaticActionTE TE)
        {
            FReaction = DiplomaticActionReaction.Accept;
            RetrieveDefaultMessage(FSource, FTarget, FOtherPlayer, FReaction);
            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget);
            Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget);
            Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            ApplyRelationModifiers();
            Proposal.Accepted(this);
        }

        // Diplomacy.pas:950
        public virtual void ExecuteReject(DiplomaticActionTE TE)
        {
            DiplomaticActionEventLog Log;
            FReaction = Proposal.RejectReaction(this);
            var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
            Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).SetGems(players.FGems + FEscrowGold);
            FEscrowGold = 0;
            var fPlayersPlayers = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource);
            Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FMagicControl.SetMana(fPlayersPlayers.FMagicControl.FMana + FEscrowMana);
            FEscrowMana = 0;
            RetrieveDefaultMessage(FSource, FTarget, FOtherPlayer, FReaction);
            Log = (DiplomaticActionEventLog)Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FTarget).FEventLogbook.FindID(FEventLogID);
            Log.SetDiplomaticAction(this);
            Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(FSource).FEventLogbook.AddEvent(Log);
        }

        // Diplomacy.pas:722
        public virtual void ExecuteAI(sbyte Player)
        {
            ByteList Peace;
            ByteList War;
            ByteList Unknown;
            ByteList IdealPeace;
            ByteList IdealWar;
            DiplomaticRelation Relation;
            DiplomaticActionReaction Reaction;
            Reaction = FReaction;
            if (Reaction == DiplomaticActionReaction.None)
            {
                Relation = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetDiplomaticRelation((sbyte)(byte)FSource, (sbyte)(byte)FTarget);
                IdealPeace = new ByteList();
                IdealWar = new ByteList();
                Peace = new ByteList();
