namespace Aow.Game.World.Structures
{

    // { Interface declaration run owned by P1. }
    public partial class StructureConstructionControl : ConstructionControl
    {

        public StructureConstructionControl(ECustomNode owner) : base(owner)
        { }

        // Structur.PAS:3195
        public override bool CanConstruct(AbstractUnit AUnit, ref string Reason) => ValidateLocation(AUnit, ref Reason) && (base.CanConstruct(AUnit, ref Reason) && StructureResource(AUnit) != null);

        // Structur.PAS:3201
        public override bool Construct(AbstractUnit AUnit)
        {
            bool Result;
            ConstructStructureTE Event;
            string Reason = "";
            if (CanConstruct(AUnit, ref Reason) && !Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(AUnit.FPlayer).GetBusy())
            {
                Event = new ConstructStructureTE(null);
                Event.FUnitID = AUnit.FUnitID;
                Event.FPlayer = AUnit.FPlayer;
                Event.FControlID = ID();
                Aow.Game.World.Map.AoWHSMap.Current.FTokenManager.GetTokenControl(AUnit.FPlayer).AddEvent(Event);
                Event.Release();
                Result = true;
            }
            else
            {
                Result = false;
            }

            return Result;
        }

        // Structur.PAS:3162
        public virtual bool ValidateLocation(AbstractUnit AUnit, ref string Reason)
        {
            StructureResource Resource;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            MapLevel Level;
            AoWMapField MapField;
            HNWalkData Walk = default;
            bool Result = true;
            Resource = StructureResource(AUnit);
            AUnit.GetLocation(ref X, ref Y, ref L);
            Level = Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetMapLevel(L);
            Aow.Game.World.Movement.HNWalkData.InitHNWalk(ref Walk, X, Y, 0);
            while (Resource.TerrainList.Count > Walk.HN && Result)
            {
                if (Walk.X >= 0 && Walk.Y >= 0 && Walk.X < Level.Width && Walk.Y < Level.Height)
                {
                    if (Resource.TerrainList.GetUsed(Walk.HN))
                    {
                        MapField = (AoWMapField)Level.GetField(Walk.X, Walk.Y);
                        Result = MapField.GetPlayer() == -1 || MapField.GetPlayer() == AUnit.FPlayer;
                        Result = Result && MapField.FindNoneTransparentHS(typeof(Structure)) == null;
                        Result = Result && !Set<byte>.WithBounds(0, 255).With(0).With(2).Contains((byte)MapField.OverlayType);
                        Result = Result && Set<byte>.WithBounds(0, 255).With(12).WithRange(1, 5).Contains((byte)MapField.TerrainType);
                    }
                }
                else
                {
                    Result = false;
                }

                Aow.Game.World.Movement.HNWalkData.WalkToNextHN(ref Walk);
            }

            if (!Result)
            {
                Reason = Aow.Game.Magic.Abilities.AbilityRules.TranslateRStr(CannotBuildOnCurrentLocationRStr);
            }

            return Result;
        }

        // Structur.PAS:3158
        public virtual StructureResource StructureResource(AbstractUnit AUnit) => null;

        private static readonly string CannotBuildOnCurrentLocationRStr = "Cannot build on current location";
    }
}

namespace Aow.Game.Commands
{

    public partial class ConstructStructureTE : TokenEvent
    {
        public ConstructStructureTE(ECustomNode owner) : base(owner)
        { }

        public new const int ClassID = 135962;

        public int FUnitID;
        public sbyte FPlayer;
        public int FControlID;

        // Structur.PAS:3098
        public override void ReadWrite(EStorageStream Stream)
        {
            base.ReadWrite(Stream);
            Stream.rwInteger(ref FControlID, 20);
            Stream.rwInteger(ref FUnitID, 21);
            Stream.rwByte(ref Unsafe.As<sbyte, byte>(ref FPlayer), 22);
        }

        // Structur.PAS:3106
        public override ExecuteResult Execute(TokenExecuter TE)
        {
            AbstractUnit AUnit;
            StructureConstructionControl Control;
            StructureResource Resource;
            Structure Structure;
            string Reason = "";
            string Text = "";
            int Gold = default;
            int Days = default;
            EChangeNotifyNode Owner;
            sbyte X = default;
            sbyte Y = default;
            sbyte L = default;
            MapLevel Level;
            HNWalkData Walk = default;
            ExecuteResult Result = ExecuteResult.DoneHalt;
            base.Execute(TE);
            AUnit = Aow.Game.World.Map.AoWHSMap.Current.FUnitControl.FindUnit(FUnitID);
            Control = (StructureConstructionControl)((ConstructAbility)Aow.Game.Engine.AoWHSSet.Current.FAbilityControl.GetAbility(125)).FConstructionControls.FindID(FControlID);
            if (Control != null && AUnit != null && AUnit.FPlayer == FPlayer && Control.CanConstruct(AUnit, ref Reason))
            {
                Resource = Control.StructureResource(AUnit);
                if (Resource != null)
                {
                    AUnit.GetLocation(ref X, ref Y, ref L);
                    Level = Aow.Game.World.Map.AoWHSMap.Current.MapContainer.GetMapLevel(L);
                    Aow.Game.World.Movement.HNWalkData.InitHNWalk(ref Walk, X, Y, 0);
                    while (Walk.HN < Resource.TerrainList.Count)
                    {
                        if (Walk.X >= 0 && Walk.Y >= 0 && Level.Width > Walk.X && Level.Height > Walk.Y && Resource.TerrainList.GetUsed(Walk.HN))
                        {
                            Aow.Game.World.Map.AoWHSMap.Current.ClearTerrain(Walk.X, Walk.Y, L, 0, -1);
                        }

                        Aow.Game.World.Movement.HNWalkData.WalkToNextHN(ref Walk);
                    }

                    Owner = (EChangeNotifyNode)AUnit.Owner;
                    Owner.BeginUpdate();
                    Structure = (Structure)Resource.PlaceResourceUser(AoWHSMap.Current, X, Y, L);
                    if (Structure != null)
                    {
                        Control.GetInfo(AUnit, ref Text, ref Gold, ref Days);
                        Structure.ExecuteBuild(AUnit, Days);
                        var players = Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(AUnit.FPlayer);
                        Aow.Game.World.Map.AoWHSMap.Current.FPlayers.GetPlayers(AUnit.FPlayer).SetGems(players.FGems - Gold);
                        AUnit.Killed();
                        Result = ExecuteResult.Done;
                    }

                    Owner.EndUpdate();
                }
            }

            return Result;
        }

        // NetworkE.pas:230

    }
}

namespace Aow.Game.Engine.Storage
{

    // { Interface declaration run owned by P2. }
    public partial class ExportTextStream : EWriteTextStorageStream
    {
        // Army.PAS:5685
        public override void rwString(ref string S, int ID)
        {
            string Buffer;
            if (!PropertyTable.PropertyExist(ID))
            {
                if (!IsEmpty(S))
                {
                    Buffer = "[" + IntToStr(ID) + "]=" + "|" + S + "|" + "\r" + "\n";
                    FBuffer.Write(Cp1252.Encode(Buffer).AsSpan().Slice(1 - 1, Buffer.Length));
                    PropertyTable.Add(ID, 0);
                }
            }
            else
            {
                throw new DoublePrioriyIDException("Double priorityID found");
            }
        }

        // Army.PAS:5700
        public override void rwStrings(StringCollection Strings, int ID)
        {
            string S = "";
            string Buffer;
            if (!PropertyTable.PropertyExist(ID))
            {
                if (Strings.Count != 0)
                {
                    for (int I = 0, last = Strings.Count - 1; I <= last; I++)
                    {
                        S = S + Strings[I];
                        if (I != Strings.Count - 1)
                        {
                            S = S + "<eol>";
                        }
                    }
                    {
                        Buffer = "[" + IntToStr(ID) + "]=";
                        if (!IsEmpty(S))
                        {
                            Buffer = Buffer + "|" + S + "|" + "\r" + "\n";
                        }
                        else
                        {
                            Buffer = Buffer + "\r" + "\n";
                        }

                        FBuffer.Write(Cp1252.Encode(Buffer).AsSpan().Slice(1 - 1, Buffer.Length));
                        PropertyTable.Add(ID, 0);
                    }
                }
            }
            else
            {
                throw new DoublePrioriyIDException("Double priorityID found");
            }
        }

        // Engine.pas:1327
        public ExportTextStream(Stream AStream, Engine AEngine) : base(AStream, AEngine)
        { }
    }

    public partial class TranslateTextStream : TranslateStorageStream
    {
        public IvDictionary FDictionary;

        // Army.PAS:5614
        public override void TranslateStrings(ref StringCollection Strings)
        {
            string S;
            int EndOfLine;
            int LineFeed;
            if (Strings.Count != 0)
            {
                S = "";
                for (int I = 0, last = Strings.Count - 1; I <= last; I++)
                {
                    S = S + Strings[I];
                    if (I != Strings.Count - 1)
                    {
                        S = S + "<eol>";
                    }
                }

                S = FDictionary.Translate(S);
                Strings.Clear();
                do
                {
                    EndOfLine = Pos("<eol>", S);
                    LineFeed = Pos("\n", S);
                    if ((EndOfLine < LineFeed || LineFeed == 0) && EndOfLine != 0)
                    {
                        Strings.Add(Copy(S, 1, EndOfLine - 1));
                        S = Copy(S, EndOfLine + 5, S.Length - EndOfLine - 4);
                    }
                    else
                    {
                        if ((LineFeed < EndOfLine || EndOfLine == 0) && LineFeed != 0)
                        {
                            Strings.Add(Copy(S, 1, LineFeed - 1));
                            // { Original reverses the length comparison before reading the following CR. }
                            if (S.Length < LineFeed + 1 && S[LineFeed] == 13)
                            {
                                LineFeed += 1;
                            }

                            S = Copy(S, LineFeed + 1, S.Length - LineFeed);
                        }
                        else
                        {
                            Strings.Add(S);
                            S = "";
                        }
                    }
                }
                while (!IsEmpty(S));
            }
        }

        // Army.PAS:5609
        public override void TranslateString(ref string S)
        {
            S = FDictionary.Translate(S);
        }

        // Engine.pas:1343
        public TranslateTextStream(Engine AEngine) : base(AEngine)
        { }
    }
}

